window.__D("text/hemshech-ayin-beis/c004",{"p":[[3601330467,"העצם כו', משא\"כ מבחי' החכ' אינו נעשה בבחי' מהות נבדל והאור הוא כמו העצם כו'. וזהו דאי' במאו\"א דבינה הוא בחי' קו המדה ונק' משחתא שנותנת מדה וגבול לז\"א, והיינו להיות בחי' הבינה היא מקור ההשתל' להיות בבחי' מהות נבדל, ע\"כ היא בבחי' קו המדה להיות בחי' ההגבלה בהמשכת האור ממדרי' למדרי' עד שבמדרי' התחתונות אין האור מאיר בגילוי כו', משא\"כ בחי' החכ' היא למע' עדיין מקו המדה דס' השתל' העולמות ונמשך האור בכל המדרי' בגילוי כו', וזהו שהחכ' היא עיקר האצי', וכנודע דבינה הוא בחי' ברי' שבאצי' וחכ' בחי' אצי' שבאצי' כו', שמצד בחי' החכ' מאיר האור והגילוי בכל המדרי' דאצי' עד גם בבחי' המל' מאיר האור גם בה\"ס האחרונות שבמל' כו'. וזהו דהמילוים דד' שמות ע\"ב ס\"ג מ\"ה ב\"ן הנה ש' ע\"ב הוא במילוי יודי\"ן דבכל אות מהד' אותי' יש בו יו\"ד כו', ובשם ס\"ג (שהוא בבינה) האותי' י\"ה הן במילוי יו\"ד ואות וא\"ו הוא במילוי אל\"ף, דאות אל\"ף הוא ב' יודי\"ן וקו באמצע, דהיו\"ד שלמע' הוא בחי' החכ' והיו\"ד שלמטה מהפך פניו שזה מורה על הצמצום והוא\nשהאור אינו מאיר בגילוי כו', והיינו דבחו\"ב מאיר גילוי אור כו' (וזהו שגם בבינה נא' ונהר יוצא כו' וכמ\"ש במ\"א). ובוא\"ו שהו\"ע המדות האור הוא בבחי' צמצום כו', וע\"כ נעשים המדות מבחי' הבינה בבחי' מהות נבדל כו', וש' מ\"ה הוא במילוי אלפי\"ן ושם ב\"ן במילוי ההי\"ן דהה' אחרונה הוא בחי' מל' כו', אבל בשם ע\"ב גם בה' אחרונה הוא מילוי יו\"ד כו', והיינו דמבחי' החכ' הוא שמאיר האור בכל הספי' כו', וכ\"ז הוא מפני שהאור הוא מעין העצם כו'. וזה הי' ההמשכה של האבות שהמשיכו בחי' ישסו\"ת והעיקר בחי' מדות שבחכ' כו', והגם שנת\"ל פקל\"ז דישסו\"ת הן בכלל בחי' בינה היינו להיותם בחי' הארה לבד (לא המשכה עצמי' כו') אבל מ\"מ ה\"ה בבחי' פרצוף המוחין, ובפרט בחי' המדות שבחכ' שעי\"ז נמשך גילוי אור כו', וז\"ש וארא אל אברהם כו' באל שדי, ונת\"ל פקמ\"ב שהאבות המשיכו ממקור ההשתל' למע' מבחי' קו המדה והיינו שהמשכה שלהם הי' מבחי' החכ' שנק' ראשית ההשתל' כו'. דהנה ההמשכה שמבחי' בינה מקור ההשתל' הוא ע\"פ מא' קו המדה כו', והיינו דכללות האור הוא שלא כמו\nהעצם כו', ואופן המשכתו הוא שבא במדה וגבול ע\"פ מא' קו המדה בס' השתל' העולמות שבבחי' מל' אינו מאיר גילוי אור והוא בבחי' חסרון האור כו', דמשו\"ז יכול להיות יניקת החיצונים שעי\"ז נעשה ההעלם וההסתר ביותר כו', וכמשנת\"ל שם, אבל האבות ע\"י עבודתם המשיכו מבחי' החכ' ראשית ההשתל' שמשם ההמשכה שלא ע\"פ מא' קו המדה ונמשך הגילוי בכל המדרי' גם בה\"ס אחרונות דמל', וממילא א\"א שיהי' יניקת החיצונים מבחי' המל' וכמשי\"ת, וגם פעלו עי\"ז שיהי' גילוי אלקו' גם למטה כו', והיינו שהאבות המשיכו גילוי בחי' אצי' שזהו מבחי' החכ' שנמשך ומאיר האור בכל המדרי' דאצי' ונמשך הגילוי גם למטה ע\"י בחינת מל' דאצי' כו'. וזהו ג\"כ ההפרש בין הכריתות ברית דנח להכר\"ב דאברהם, דכר\"ב דנח הי' מבחי' יחוד חיצוני דאו\"א וכר\"ב דאברהם מבו' במ\"א שזהו בחי' יחוד פנימי דאו\"א, ולפי המבו' כאן ג\"ז הוא בחי' יחוד חיצוני דאו\"א, רק ההפרש ביניהם דכר\"ב דנח הי' על קיום העולם כו', דבתחלה הי' השחתת העולם והכר\"ב עם נח הי' שיהי' קיום העולם כו', דההמשכה היא מבחי' בינה\nבחי' ברי' דאצי' להיות בחי' העולמות כמו שהן ע\"פ מא' קו המדה כו', אמנם הכר\"ב דאברהם הי' ע\"ז שיהי' גילוי אלקות בעולם כו', והיינו ההמשכה מבחי' חכ'"],[3601330468,"בחי' אצי' שבאצי' שההמשכה היא למע' מקו המדה הנ\"ל שנמשך גילוי האור גם במל' ונמשך הגילוי למטה כו', וע\"ז הי' הכר\"ב שיהי' גילוי אלקו' בעולם כו'.\n<b>וע\"פ</b> הנ\"ל יובן מש\"א במד\"ר שהי' המקום מבקש לכונן את העולם והיינו שיהי' גילוי אלקו' בעולם כו', דא\"ז ענין ברי' והתהוות העולם, דהרי התהוות העולם הי' מבחי' חסרון והעדר הגילוי כו', וענין לכונן את העולם הוא שיהי' גילוי אלקות בעולם כו', ואו' ע\"ז אנו מוצאים בדרך פשיטות שהרי ודאי זאת היא הכוונה פנימי' שהרי אין הכוונה בהתהוות העולם בעצם מציאו' היש, כ\"א תכלית הכוונה הוא שבעולם יאיר גילוי אלקו' כו'. ומ\"ש אנו מוצאים הוא שהרי כן הי' בתחלת הבריאה וכדאי' במד\"ר ע\"פ ויתהלך ה' אלקי' בגן לרוח היום דעיקר שכינה בתחתונים היתה כו', והיינו מה שהוא עיקר הכוונה כבר הי' בתחלת הברי' כו', ועז\"א שאנו מוצאים כו'. אך הרשעים לא היו מניחים שגרמו סילוק השכינה כו', וכמ\"ש במד\"ר שם, וזהו מפני שהמשכה זו א\"ז עיקר ההמשכה דברה\"ע, כי ההמשכה דברה\"ע הוא ההמשכה שע\"פ קו המדה בבחי' חסרון האור כו', ובבחי' זו יכול להיות אחיזת החיצונים כו', והגם שהי' ג\"כ הגילוי שמבחי' חכ' דמשו\"ז הי' עיקר שכינה כו', הרי לא זה הי' עיקר ההמשכה\nכו', והגילוי הי' רק מצ\"ע שלא ע\"י עבודה כו' (כ\"א רק מה שכל ההמשכות שע\"י עבודה הי' תחלה מצ\"ע כו' וכמ\"ש במ\"א), ובההמשכה שבברה\"ע הי' יכול להיות אחיזה ועי\"ז גרמו סילוק האור כו'. עד שבאו האבות וזכו כו', דקדק לו' וזכו היינו שע\"י עבודה דוקא המשיכו האור והגילוי דבחי' חכ' כו', אמר עליהם אני מכונן את העולם להיות גילוי אלקו' בעולם כו'. ומ\"ש שהי' המקום מבקש הנה מקום הוא בחי' יסוד אי' וכדאי' בכהאריז\"ל בפי' ברוך המקום שזהו יסוד אבא הגנוז ביסוד אימא כו'. וזהו שהי' המקום מבקש דבבחי' בינה שמשם ההמשכה בבחי' מדה וגבול הי' מבקש שיהי' הגילוי מבחי' חכ' להיות גילוי אלקו' שזה תכלית הכוונה וזהו שהמשיכו האבות כו'. וזהו כי מראש צורים אראנו דאי' בזהר שזהו בחי' מדות שבחכ', ומגבעות אשורנו מדות שבבינה דה' אושיט פסיעה לבר כו'. וזהו ג\"כ דאי' במדרש כי מראש צורים אלו האבות דהאבות המשיכו בחי' מדות שבחכ' כו', ועז\"א אנו מוצאים שהי' המקום מבקש לכונן את העולם שיהי' גילוי אלקו' בעולם כו' שכן הי' בתחלת הבריאה, אך שהרשעים לא היו\nמניחים כו', עד שבאו האבות וזכו בעבודתם שהמשיכו בחי' מדות שבחכ' כו', אמר עליהם אני מכונן את העולם שיהי' גילוי אלקות למטה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והענין הוא דעצמיות המדות הן לא בבחי' התפעלות והתעוררות כ\"א מצד השלימות, והוא ומדותיו ית' הכל א', וזהו מבחי' החכ', דבינה היא מקור ההשתל' להיות בבחי' נבדל, והיא בחי' קה\"מ להיות הגבלה, ושיהי' אור לא כמו העצם, וחכ' למעלה מקה\"מ, והיא ראשית ההשתל' להיות הגילוי כמו העצם, ומצד החכ' מאיר הגילוי גם במל', וזהו דבש' ע\"ב גם ה' אחרונה במילוי יו\"ד, וחכ' היא עיקר האצי', וזהו שהמשיכו האבות, וזהו מילוי החסרון דבחי' מל' שיהי' גילוי אלקות, ושלא יהי' יניקת החיצונים, וכר\"ב דנח בחי' בינה וכר\"ב דאברהם בחי' חכ'. וזהו מראש צורים אלו האבות, בקש לכונן את העולם להיות גילוי אלקות בעולם.</span>"],[3601330469,"<h3>בס\"ד. ש\"פ פנחס, תער\"ג</h3>\n<b>וידבר</b> ה' אל משה לאמר פנחס בן אלעזר כו', השיב את חמתי מעל בנ\"י כו' לכן הנני נותן לו את בריתי שלום כו', משמעות הענין הוא דהנני נותן לו את בריתי שלום זהו קבלת שכר ע\"ז שהשיב את חמתי כו', וצ\"ל מהו הקבלת שכר דהנני נותן לו כו', גם מהו\"ע ההשבה דהשיב את חמתי מעל בנ\"י שע\"ז הוא הקבלת שכר דהנני נותן לו את בריתי כו'. ובמד\"ר אי' משיב חימה בן של משיב חימה בן של אהרן שהשיב חמה מעל בנ\"י בהקרבת הקטרת, וצ\"ל שייכות השבת חימה של פנחס להשבת חימה של אהרן ע\"י הקטרת ושהשכר ע\"ז הוא שנותן לו את בריתי שלום כו'. ולהבין כ\"ז ילה\"ק משנת\"ל שיש ב' אופני עו\"ע, הא' שהעלול הוא מהות נבדל מהעילה וע\"ה שנמצא כלול בהעילה ומתגלה ממנו מ\"מ ה\"ה בבחי' מהות נבדל ממנו כו', והב' שהעלול הוא מהות העילה והוא רק התפשטות העילה ומ\"מ הוא מהותו כו'. ונת' המשל כמו שו\"מ שהמדות הן בדרך עו\"ע מהמוחין ומ\"מ ה\"ה מהות נבדל מהמוחין כו', ועל כן גם הארת המוחין בהמדות היא הארה נבדלת שאינו ממהות המוחין כו'.\nקנג) <b>ולהבין</b> הדוגמא מזה למע', הנה אי' בת\"ז איהו וחיוהי חד איהו וגרמוהי חד, וידוע דקאי על ע\"ס דאצי' דאיהו וחיוהי חד בהון ואיהו וגרמוהי חד כו', ומובן מזה שאינו דומה בחי' איהו שמתייחד עם חיוהי לבחי' איהו שמתייחד עם גרמוהי, וכמו\"כ בענין היחוד אינם דומים זל\"ז, שהרי אינו או' איהו וחיוהי וגרמוהי חד, אלא או' איהו וחיוהי חד בפ\"ע ואיהו וגרמוהי בפ\"ע הרי מובן שאינו דומה בחי' איהו שמתייחד עם חיוהי לבחי' איהו שמתייחד עם גרמוהי כו, וגם בענין היחוד אינם שוים דאינו דומה ענין היחוד עם חיוהי לענין היחוד עם גרמוהי, ומשו\"ז חלקם בשני חלוקות כו'. דהנה איהו הוא בחי' א\"ס ב\"ה וכדאי' באגה\"ק ד\"ה איהו וחיוהי דאיהו וגרמוהי חד לברוא בהם וע\"י מאין ליש, וידוע דענין ההתהוות הוא בכח ויכולת הא\"ס דוקא לא בחיק הנבראים כלל כו', דמבחי' גרמוהי מצ\"ע אא\"ל ההתהוות כו', איך שנפרש גרמוהי אם ז\"ת או כלים דע\"ס בכלל כו' אין בהם כח ההתהוות כו', דמשו\"ז צ\"ל היחוד דאיהו עם גרמוהי לברוא בהם כו', דההתהוות הוא בכח הא\"ס דוקא כו',\nוהא\"ס ע\"ה שהוא פשוט בתה\"פ שאין בו התחלקות מדרי' כו', ה\"ה מתראה ומתגלה בכמה אופני חילוקי מדרי' כו', ובזה הוא החילוק בין איהו שמתייחד עם חיוהי להאיהו שמתייחד עם גרמוהי, דע\"ה שבחי' איהו מתייחד עם גרמוהי לברוא בהם וע\"י כו', מ\"מ בחי' האיהו שמתייחד עם חיוהי הוא גבוה ונעלה במדרי' הרבה יותר מבחי' איהו שמתייחד עם גרמוהי כו'. ולהבין זה ילהק\"ת מהו בחי' חיוהי וגרמוהי, דהנה בע\"ח אי' דחיוהי הן ג\"ר וגרמוהי ז\"ת, אמנם רבינו ז\"ל באגה\"ק הנ\"ל כ' דחיוהי הן האורות וגרמוהי כלים כו', והנה ע\"פ פשוט חיוהי וגרמוהי הן עד\"מ גוף ונפש דעל עצם מעצמי ת\"א גרמא מגרמי הרי גרמא הן העצמות, דעיקר מציאות וישות הגוף הן העצמות, דהבשר הוא לבוש הגוף וכמ\"ש עור ובשר תלבישני ועיקר הגוף הן העצמות כו', ובאמת העצמו' הן מדרי' גבוה ונעלה שזהו בחי' העצם שלמע' מהתפשטות כו', וכנודע דהתפשטות ה\"ז הארה לבד, והעצמו' מורה על העצם קודם שמתפשט עדיין וכמ\"ש בזהר גרמא"],[3601330470,"בנויין על מוחא דאיהו מיא כו' וכמ\"ש במ\"א, אך ע\"פ פשוט העצמות הן עצם מציאות וישות הגוף כו', ולכן הן קיימים גם לאחר שנרקב הבשר כו'. והדוגמא למע' הוא מ\"ש בת\"ז במא' דפתח אליהו וכמה גופין תקינת לון דקאי על הכלים דע\"ס דאצי' שנק' גופין כו'. ואח\"כ אמר וההוא נביעו איהו כנשמתא לגופא שהן בחי' האורות כו', דעיקר ענין המציאות שבאצי' הן הכלים שהרי האורות הן בבחי' פשיטות עדיין כו', והגם שבאורות יש ג\"כ ע\"ס כו', מ\"מ הרי הע\"ס דאורות הן בבחי' פשיטות עדיין לגבי הע\"ס דכלים כו' וכמשנת\"ל באורך, וכמו בחי' ח\"ס שהיא למע' מן החכ' לגבי חכ' הגלוי' כו', כמו\"כ האורות הן בבחי' פשיטות ובבחי' אין והעדר המציאות לגבי הכלים, דעיקר המציאו' הן הכלים כו', דהכלים הן בחי' הגבול שבאצי' וכמ\"ש בעה\"ק דא\"ס כשם שכחו בבל\"ג כן כחו בגבול שאל\"כ אתה מחסר שלמותו והגבול הנמצא ממנו תחלה הן הכלים דאצי' כו', וכן כ' רבינו ז\"ל באגה\"ק הנ\"ל שהכלים הן בחי' גבול כו', דהנה הפרד\"ס ס\"ל שגם הכלים אינן בבחי' גבול שז\"ש בס\"י מדתן עשר שאין להם סוף כו' וכמ\"ש\nבמ\"א, אך רבינו כ' שהכלים הן בחי' גבול כו'. ושרש הגבול שבאצי' הוא מכח הגבול שבא\"ס שזהו אותי' הרשימה כו', דתכלית הכוונה בהתגלות כח הגבול הוא בכדי שיהי' מציאות היש כו', דכאשרen. ברצונו להאציל ולברוא את העולמו' היינו שיהי' עולמו' בבחי' מציאות כו', נתגלה כח הגבול שבא\"ס כו'. דהרי מבחי' א\"ס הבל\"ג להיות שזהו התגלות מן העצמו' וה\"ז בבחי' א\"ס ובבחי' בל\"ג אא\"ל מזה מציאו' היש כו', וע\"כ כשעלה ברצונו ית' להאציל ולברוא כו' וכמא' שוקיו עמודי שש שוקיו זה העולם שנשתוקק הקב\"ה לבראותו כו', נתעלם בחי' כח הבל\"ג ונתגלה בחי' כח הגבול שמזה הוא התהוות העולמו' כו', והגם דכח הגבול הוא ג\"כ כח העצמו' וכמו\"כ כח הבל\"ג אינו עצמו' ממש, שהרי עצמו' הוא למע' מבחי' גבול ומבחי' בל\"ג ושניהם שוין לגבי' כו', מ\"מ כשעלה ברצונו שיהי' התגלו' מן העצמו' הנה ההתגלות הוא בבחי' א\"ס ובבחי' בל\"ג כו'. ולכן מבחי' כח הבל\"ג אנו יודעים מציאו' העצמו' להיות שהוא בחי' התגלו' העצמות שמצד העצמות כו' וכמשנת\"ל פרק קכ\"ח, אנו יודעים מזה מציאו' העצמו'\nכו', משא\"כ מבחי' כח הגבול לא היינו יודעים גם מציאו' העצמו' כו'. והגם דלכאו' גם מכח הגבול היינו יודעים מציאות העצמות שה\"ז מן העצמו' כו', ועוד זאת דמזה דוקא אנו יודעים את כח העצמות כו', וכנודע דכח העצמו' הוא בכח הגבול יותר מבכח הבל\"ג כו' וכמ\"ש במ\"א, דרשימו הוא מבחי' עצמות א\"ס בבחי' פנימיות יותר, וכמו עד\"מ הזריקה שהיא בכח דוקא ובעצם היד לא ע\"י האצבעות כו' וזהו נטל צרורות וזרקן כו', וכן בהתהוות היש דוקא נראה כח העצמות דהוא לבדו בכחו ויכולתו להוות יש מאין ואפס המוחלט כו' (ובאמת גם מכח הבל\"ג אנו יודעים כח העצמו' כו', דזה שיהי' אור שבבחי' א\"ס ובבחי' בל\"ג ממש ה\"ז רק בכח העצמו' כו', מ\"מ עיקר כח העצמו' הוא בכח הגבול כו', דגדול יותר כח העצמות בענין ההתהוות מבענין הגילוי, והראי' דענין ההתהוות לא יש בחיק הנבראים, משא\"כ ענין הגילוים כמו העצם יש גם בנבראים, רק שהגילוים בנבראים הוא בבחי' גבול מפני שגם העצם הוא בבחי' גבול כו', ויש ג\"כ גילוים בבחי' בל\"ג וכמו באהבה דבכל מאדך (וידוע שזהו עיקר האלקות שבנש\"י\nוכמ\"ש במ\"א), וזהו לך ה' הגדולה זו מע\"ב כו', וכמ\"ש במ\"א דבהתהוות בי\"ע נראה יותר כחו הא\"ס מבהתהוות האצי' כו',"],[3601330471,"ועמשית\"ל בענין אלקי ל' כח). הנה זהו כאשר נתגלה כח הבל\"ג דוקא, והיינו כשיש כח הבל\"ג וכח הגבול אנו יודעים מכח הגבול את כח העצמות כו', כי כח הבל\"ג הוא בחי' גילוי, ומזה שאנ\"ר ויודעים היתרון וההתחדשות שבכח הגבול כו', הרי אנו יודעים בזה כח העצמו' כו', אבל מכח הגבול לבד לא היינו יודעים כח העצמו' וגם לא מציאו' העצמו' כו', מפני שהוא בחי' העלם בעצם ולא הי' כלל ענין הידיעה בעולם, וע\"י גילוי העצמות שיש ענין הגילוים בעולם אנו יודעים כח העצמות שבכח הגבול, וגם אנו יודעים להעריך כח הבל\"ג וכח הגבול והיתרון שבכח הגבול כו', משא\"כ בכח הבל\"ג הרי מזה לבד אנו יודעים מציאו' העצמות (וגם כח העצמות כו'), והיינו להיותו התגלו' העצמו' כו'. ומ\"מ אנו יודעים מזה רק מציאו' העצמו' לא אופן העצמו' כו', והיינו להיות שהאור והעצמו' הן באין ערוך כלל ע\"כ אין אנו יודעים מזה אופן העצמות כו', ולא כמו במדרי' שבאור גופא הרי מההארה אנו יודעים אופן העצם כו', וכמו שמהאו\"פ אנו יודעים את האו\"מ והיינו שאנו יודעים את ההפלאה ואופן ההפלאה\nכו', משא\"כ בעצמו' הנה מבחי' האור והתגלות העצמות אין אנו יודעים אופן העצמו' כו', והיינו מצד הבדלת ערך העצמו' מן ההתגלות כו', דלבד זאת שהעצמו' אינו רק בבחי' מאור כו', וכמ\"ש במ\"א שיש כמה ענינים שהעצמו' נושא בעצמו שאין אנו יודעים מזה כלל כו' (וממילא הרי בחי' האור אינו מגלה את העצמו' כו'), הנה גם בזה שהוא ית' בבחי' מאור ה\"ז בבחי' הבדלת הערך לגמרי מן האור וההתגלו' ממנו כו' וכמ\"ש במ\"א, וע\"כ אין אנו יודעים מזה אופן העצמות כו', אבל מ\"מ אנו יודעים מזה מציאות העצמות להיות עכ\"פ התגלו' העצמו' כו', משא\"כ מכח הגבול לא היינו יודעים גם מציאו' העצמו' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא למעלה הנה איהו וחיוהי חד איהו וגרמוהי חד, איהו בחי' עצמות א\"ס, ועם היותו פשוט ה\"ה מתגלה בכמה אופנים, גרמוהי תרגום של עצמות שזהו עיקר בנין הגוף (ובפנימיות הוא העצם קודם ההתפשטות) והיינו בחי' הכלים, שזהו עיקר המציאות והגבול שבאצי', ושרשם מבחי' הגבול שבא\"ס שנתגלה ע\"י הצמצום בכדי שיהי' התהוות היש שלא הי' אפשר להיות מכח הבל\"ג להיותו התגלות העצמות דלכן יודעים מזה מציאות העצמות (לא אופן העצמות מפני הבדלת הערך דהאור מהמאור, וגם שאינו רק בחי' מאור), והגם דכח הגבול ג\"כ מן העצמות, ואנו יודעים מזה כח העצמות עוד יותר, הנה מכח הבל\"ג להיותוen. אנו יודעים מזה לבד כח העצמות, משא\"כ כח הגבול להיותו העלם אנו יודעים מזה כח העצמות ע\"י הגילוי שמכח הבל\"ג.</span>\nקנד) <b>והנה</b> זה גופא שכח הגבול הוא בחי' העלם הוא לפי שהכוונה בזה הוא להיות התהוות מציאו' יש ודבר נפרד שזהו העלם בעצם (והכוונה היא להיות אתהפכא חשוכא לנהורא כו' וכמשי\"ת), ולכוונה זו נמצא מן העצמות כח הגבול שהוא בחי' העלם כו', וע\"כ בכדי שיהי' התהוות היש הי' צ\"ל התעלמות בחי' כח הבל\"ג שהוא בחי' התגלות העצמו' ושיתגלה כח הגבול כו', דכח הבל\"ג להיותו בחי' גילוי העצמות הי' קודם הצמצום בבחי' התגברות על הכח הגבול, והיינו שכח הבל\"ג הי' בהתגלות וכח הגבול הי' כלול בו שלא הי' ניכר כלל, וע\"כ הי' הצמצום"],[3601330472,"שנתעלם אור הא\"ס ונתגלה כח הגבול כו', ועמשית\"ל בד\"ה ויהי הענן והחשך ויאר. והגם שאין לך דבר שחוץ לעצמותו שהרי אוא\"ס מאיר לאחה\"צ כמו קוה\"צ וכמ\"ש את השמים ואת הארץ אני מלא דאני קאי על עצמות, וכמו האדם שאומר אני הכוונה על עצמותו כו', והיינו דעצמו' אוא\"ס הוא לאחה\"צ כמו קוה\"צ כו' (וההפרש הוא רק בין העלם וגילוי כו', ובידיעת העצמו' הוא בבחי' גילוי כו'), וממילא אין העולמות בבחי' מציאות כו', דכ\"ה באותי' הרשימו גופא דקוה\"צ לא היו בבחי' מציאו' כו', שהרי אותיות הרשימו היו גם קוה\"צ וכמא' גליף גליפו בטה\"ע שזהו אותי' הרשימו כו' וכמ\"ש במ\"א, רק כשהי' האוא\"ס מאיר בגילוי בהאותי' לא היו בבחי' מציאו' וע\"י הצמצום נעשו בבחי' מציאות כו', דהגם שהצמצום לא נגע בהאותי' עצמן רק בבחי' האור שנתעלם כו', הרי עי\"ז נעשו האותי' בבחי' מציאות כו' וכמ\"ש במ\"א. ובאמת הרי האוא\"ס ממלא מקום החלל לאחה\"צ כמו קוה\"צ, וממילא גם לאחה\"צ אין האותי' בבחי' מציאו' כלל כו', וכ\"ה בהעולמו' ונבראי' שבאמת מאיר בהם גילוי אוא\"ס ב\"ה וגם לאחר שנתהוו\nאינם בבחינת מציאות כלל כו', מ\"מ הרי הנבראים מרגישים א\"ע למציאו' יש כו'. הנה זה גופא מה שהנבראי' המה בבחי' מציאו' יש בהרגשתן זהו מבחי' כח הגבול שבא\"ס כו', וכמו\"כ לאחר שנתהוו הנבראים הרי יש בהם אור וחיות לקיים מציאותם כו', זהו ג\"כ מבחי' כח הגבול כו'. דהנה אנ\"ר עד\"מ באדם למטה שיש בו נפש המחי' אותו דמהות הנפש אין אנו יודעים מה הוא אבל זאת אנו יודעים שיש בו נפש המחי' אותו שהרי בצאת הנפש מהגוף נשאר הגוף כאבן דומם כו', הנה לבד הנפש בהכרח שהגוף עצמו יש בו חיות לקיים מציאותו, שהרי גם בצאת הנפש נשאר הגוף עכ\"פ כדומם כו', הרי בהכרח שיש בו חיות כו', וזה לבד הקיסטא דחיותא שזהו מה שנשאר מהנפש גם לאחר הסילוק כו', דזהו\"ע מ\"ש ונפשו עליו תאבל כו', ומשו\"ז קשה רמה כו'. הנה לבד זאת יש בו חיות לקיים עצם מציאות כו', וכמו אדה\"ר קודם שנפח באפיו נ\"ח שהי' מוטל גולם וכמ\"ש גלמי ראו עיניך כו' שהי' במציאו' עכ\"פ כו', וכמו עד\"מ עץ כשכורתין אותו שנפסק צורת חיותו הרי צורת עצם מהותו נשאר קיים כו', ובהכרח הרי יש בו חיות\nהמקיימו כו'. והדוגמא למע' הוא כדאי' במא' דפתח אליהו וכד אנת תסתלק מינייהו אשתארו כולהו שמהן כגופא כו', הרי אשתארו כגופא עכ\"פ כו', וידוע שזהו מצד החיות שיש בעצם הכלים לקיים מציאותם לבד האור המתלבש בתוכם כו', והן השמות דאל אלקים שהן מבחי' הרשימו שרש ומקור הכלים כו', וכמו\"כ כל הנבראי' עד למטה מטה גם אחר שנתהוו יש בהם חיות לקיים מציאותם כו', וזהו מבחי' כח הגבול כו', דהתהוות הנבראי' הוא מכח הגבול כו', וכמו\"כ לאחר שנתהוו נמצא בהם מכח הגבול לקיים מציאותם כו', רק שזהו מה שנמצא בהם לא שהוא בהם בבחי' התלבשו' והתגלו' כו' (שזה שייך בבחי' או\"פ כו'), והחיות הזה זה מה שנמצא בהם כח מבחי' כח הגבול שבא\"ס לקיים מציאותם כו'. וזהו איהו וגרמוהי חד דאיהו הוא בחי' כח הגבול שבא\"ס ומתייחד עם גרמוהי לפעול פעולת ההתהוות, וכן לאחר שנתהוו לקיים מציאותן כו'. אמנם ענין איהו וחיוהי חד הנה חיוהי הן האורות דשרש האורות הן מאוא\"ס הבל\"ג כו', דהגם שהאורות באין ג\"כ בבחי' מדה וגבול וגם בשרשן הן בבחי' ע\"ס כו', הרי נת\"ל פרק ט\"ז\nופרק כ\"ז שא\"ז בחי' כח הגבול שבא\"ס כ\"א זהו מה שהא\"ס הבל\"ג שיער בעצמו להאיר במדה וגבול כו', וא\"כ הרי שרשם הוא"],[3601330473,"מכח הבל\"ג שבא\"ס רק זהו מה ששיער כו', וזהו בחי' איהו שמתייחד עם חיוהי היינו בחי' כח הבל\"ג שבא\"ס שהוא בחי' התגלו' העצמו' כנ\"ל שמתייחד עם האורות כו', והוא בחי' כח הגילוי שבא\"ס כו', וזהו דבחי' איהו שמתייחד עם גרמוהי הוא כח הא\"ס להיות בחי' ההתהוות כו' (והיינו להיות בחי' ההעלם כו'), ואיהו שמתייחד עם חיוהי זהו כח הא\"ס להיות בחי' הגילוי כו', וזהו דב' בחי' איהו הגם ששניהם הם כח הא\"ס כו', מ\"מ בחי' איהו שמתייחד עם חיוהי שזהו בחי' כח הגילוי שבבחי' א\"ס ובבחי' בל\"ג ה\"ז מדרי' גבוה ונעלה יותר מבחי' איהו שמתייחד עם גרמוהי כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזה שנמצא בחי' כח נעלם הוא בכדי שיהי' מציאות יש, וע\"ז הי' הצמצום שיתגלה בחי' כח הגבול והגם שאין דבר חוץ לעצמותו, וכמו שהיו אותיות הרשימו קודם הצמצום כן הם אח\"כ, וכן הנבראים אינם במציאות, מ\"מ הרגש מציאותם בעצמן הוא מכח הגבול, וזהו המקיים מציאותם לאחר שנבראו כמו קיום הגוף עצמו, וזהו בחי' איהו שמתייחד עם גרמוהי, וחיוהי הוא בחי' האור דשרשו מכח הבל\"ג, וזהו בחי' איהו שמתייחד עם חיוהי להיות בחי' גילוי.</span>\nקנה) <b>והנה</b> באגה\"ק ד\"ה איהו וחיוהי חד מובן דבחי' איהו שמתייחד עם גרמוהי זהו בחי' האו\"פ המתייחד עם הכלים כו', אך ג\"ז מובן שם שא\"ז כ\"א לצורך ההתהוות כו' (לא בחי' עצמי' האורות והכלים כמו שהן מצ\"ע כו' כ\"א לפעול פעולת ההתהוות כו'), והיינו מה שהכלי מגביל את האור לפעול כפי אופן מהותה דוקא כו'. וכמו עד\"מ בגוף ונפש הרי לאחר כל העילוים שיש בהגוף ע\"י הנפש המתלבש בתוכו ומתגלה ומתאחד בו כו', הרי הגוף מתגבר על הנפש שע\"י התלבשותו בגוף ה\"ה בא בהגשמה לפי אופן אברי הגוף שיהי' לו שייכות לענינים גשמי', וכמו להשכיל השכלה גשמי' ולראות ראי' גשמי' כו', דהנפש מצ\"ע הרי אינה שייכה להענינים הגשמי' כלל, וכמו\"כ גם כחות הנפש קודם התלבשותם בגוף הרי אינם שייכים לענינים גשמי' וע\"י התלבשותם בגוף נעשים בבחי' שייכות לענינים גשמי' כו'. והנה באמת תכלית הכוונה בירידת הנשמה למטה והתלבשותה בגוף הוא בכדי להאיר את העולם כו', וכמ\"ש נר ה' נשמת אדם וכמו הנר שהוא להאיר את החשך כמו\"כ הנשמה היא נר ה' להאיר כו', ולהיות עוה\"ז\nהוא חשך כפול ומכופל צריכים ריבוי נרות כו', והו\"ע ירידת הנשמו' למטה להאיר את העולם כו', ובד\"כ זהו בעובדי ה' בנשמתן שאינם נתפסים בגשם ואין העולם מעלים ומסתיר להם ואור נשמתן מאיר בהם בהתגלו' כו', וזהו ג\"כ ע\"י הגוף דוקא, דהנשמה קודם התלבשותה בגוף אינו בגדר להאיר את העולם כ\"א ע\"י התלבשותה בגוף כו', רק שהגוף אינו מסתיר על הנשמה אדרבה מגלה אותה להאיר למטה כו', והעיקר הוא ע\"י תומ\"צ עי\"ז דוקא מאירים את העולם כו', דענין להאיר את העולם הוא שיהי' אתהפכא חשול\"נ כו' וכמ\"ש בלק\"ת ד\"ה ואתחנן. וזהו דוקא ע\"י המשכה דבחי' עצמו' א\"ס ב\"ה וכמ\"ש והוי' יגיה חשכי דבכדי להגיה החשך זהו מבחי' ש' ה' דלעילא דוקא כו', דמ\"ש כי אתה נרי הוי' הו\"ע נר ה' דנשמה כו', אבל והוי' יגיה חשכי הוא להיות אתהפכא חשוכא כו', וזהו ע\"י ש' הוי' דלעילא כו',"],[3601330474,"וההמשכה הוא ע\"י תומ\"צ כו'. דזהו ההפרש בין המשכה דנשמה לההמשכה דתומ\"צ, דהנשמו' בכח עצמן ממשיכים רק הארה לבד כו' (וע\"ה שממשיכים מדרי' גבוהות כ\"ז הוא רק הארה לבד כו'), וההמשכה דתומ\"צ הוא המשכה עצמי' כו', דהיינו ההמשכה מלמעלמ\"ט כו' כנודע, ועי\"ז דוקא הוא שיהי' אתהפכא חשול\"נ כו'. וכמו\"כ הביטול האמיתי הוא ג\"כ ע\"י תומ\"צ דוקא וכמ\"ש בסש\"ב פל\"ה דאפי' צדיק גמור עובד ה' ביראה ואה' בתענוגים אעפ\"כ אינה בטלה במציאות לגמרי כו', להיות לאחדים ומיוחדים באיחוד גמור רק הוא דבר בפ\"ע ירא ה' ואוהבו כו', משא\"כ המצות שהן פנימי' רצונו ית' כו', מיוחד ונכלל ברצונו ית' והיו לאחדים ממש ביחוד גמור כו', וכמו\"כ לפעול בעולם להאיר את העולם זהו ע\"י תומ\"צ דוקא כו'. וזהו ג\"כ ההפרש בין האבות למ\"ת, דהנה בענין להאיר את העולם יש בזה חילוק אם במה שהעולם לא יעלים ויסתיר על אלקו' כו', או שהחשך וההעלם יהפך לאור כו'. והאבות שהי' עבודתם בכח עצמן בהתגלות אור נשמתן המשיכו גילוי אלקו' שהעולם לא יעלים ויסתיר כו' (והיינו שלא יהי' בחי'\nחסרון האור וממילא לא יהי' יניקה ואחיזה כו' וכמשנת\"ל פרק קמ\"ג), אבל בכדי שיהי' אתהפכא חשול\"נ זהו ע\"י המשכת העצמו' שנמשך במ\"ת כו', אך כ\"ז הוא בעובדי ה' בנשמתן כו'. משא\"כ עובדי ה' בגופן האור האלקי בא בהם בהגשמה כו', דהגם שממשיכים ג\"כ גילוי אלקו' ע\"י העבודה ויגיעה שלהם שפועלים בירור וזיכוך הנה\"ב כו' מ\"מ ה\"ז בא בהגשמה כו', דכשם שהגוף מסתיר על אור נשמתן כמו\"כ ה\"ה מסתיר על האלקו' שממשיכים כו', וזהו שגם בעבודה ע\"י שנתפס בגשם שז\"ע עובדי ה' בגופם כו' בא האור האלקי בהגשמה כו', וכ\"ש בכללות ענין התלבשו' הנשמה בגוף הרי אור הנשמה נעשה בהגשמה כפי אופן אברי הגוף כו'. והדוגמא מזה למע' בענין איהו וגרמוהי חד שהאור בא בהתלבשו' ותפיסא בהכלי והיינו בבחי' חיצוני' הכלים שמגבילים את האור ובא בהגשמה כפי מהות הכלים כו', (דכמו בנפש ענין עובדי ה' בנשמתן הדוגמא מזה למע' בחי' פנימי' הכלים שההתגלו' הוא האור כו' והוא שאינו נתפס כו', וה\"ז למע' עדיין מהתהוות כו', ומש\"א איהו וגרמוהי חד לברוא כו', זהו בבחי' חיצוני' הכלים\nשעושים הגשמה בהאור כו'). אך בהאור זהו ג\"כ בחיצוני' האור שבזה שייך לומר שהכלים מגבילים את האור שיהי' כמהות הכלים כו', אבל לא בבחי' פנימי' האור כו' (ששם התגברות האור כו', וגם הכלים אינם בבחי' מציאו' ממש כו'). וכידוע שיש שם העצם והתואר והפעולה, דשם העצם הוא בחי' עצם האור שלמע' עדיין מהתלבשות בכלים כו', ושם התואר הוא פנימי' האור שמתלבש בבחי' פנימי' הכלים כו' שעז\"נ יהיב חכמתא לחכימין, דחכמתא הוא בחי' עצם האור ויהיב חכמתא לחכימין היינו לחכימין בעצם בבחי' פנימי' האור והכלי שאינו עדיין לפעול כו' וכמ\"ש במ\"א, ושם הפעולה הוא בחיצוני' הכלים המלבישים לחיצוני' האור שהוא לפעול פעולת ההתהוות כו' (ועמשית\"ל ד\"ה ויקחו לי תרומה). וזהו דבג' עולמו' בי\"ע הכללים נק' אצי' אדם דעשי' דכללות, דעשי' הוא בחי' כח נבדל כו', דהעיקר הוא בבחי' חיצוני' הכלים כו'. והענין דהנה בעשי' יש ב' ענינים הא' שהוא בבחי' התחברות עם הכח הפועל וכמו האומן שעושה כלי שבשעת העשי' הכלי היא בהתחברו' עם כח הפועל ואם יופסק ההתחברות לא תוגמר\nהכלי כו', והב' שלאחר שנפסק ונבדל מכח הפועל אז דוקא ניכרת הפעולה, וכמו בזריקת אבן הרי דוקא כשהאבן יוצא מידו אז ניכרת"],[3601330475,"הפעולה כו', ומה שאצי' נק' עשי' היינו במדרי' הב' הנ\"ל, וכדאי' בס' הבהיר נטל צרורות וזרקן דקאי על אצי' בכלל (מפני ששם בחי' הכלים כו') וכמ\"ש במ\"א. ובאצי' גופא ב' ענינים הנ\"ל זהו בבחי' המל' כמו שהיא באצי' שהיא בבחי' התחברות והתאחדות כו', וכמו שנעשה בבחי' מקור לבי\"ע שנעשה בבחי' נבדל כו', ובכלים דע\"ס בכלל זהו בחי' חיצוני' הכלים כו', וז\"ע היחוד דאיהו וגרמוהי הוא בשביל ההתהוות והיינו שהכלי יסתיר ויעלים על האור להיות התהוות המציאו' כו', משא\"כ איהו וחיוהי חד דאיהו זהו בחי' האוא\"ס הבל\"ג המתייחד עם האורות כו', וענין היחוד הוא להיות העילוי בבחי' חיוהי שיהי' מאיר בהם בחי' עצם האור כו' וכמשי\"ת, ועי\"ז יהי' בחי' הגילוי שלא בהגבלה כו', דהאורות ה\"ה באין בבחי' מדה וגבול שעי\"ז הוא בחי' מיעוט האור ממדרי' למדרי' כו', וע\"י היחוד דאיהו וחיוהי הוא שהאורות יהיו בבחי' גילוי שלא בהגבלה כו'. וזהו ההפרש בין איהו וחיוהי חד לאיהו וגרמוהי חד, דאיהו המתייחד עם גרמוהי זהו בחי' כח הגבול שבא\"ס שענינו הוא להיות בחי' התהוות\nהמציאו' דוקא כו', ובהאור גופא בחי' האיהו הוא בחי' חיצוני' האור לא בחי' עצמו' האור כו', וענין היחוד הוא בחי' תפיסת האור בבחי' חיצוני' הכלים שבזה הוא התגברות הכלים על האור להסתיר על האור לפעול פעולת ההתהוות להיות בחי' מציאות יש כו', אמנם בחי' איהו המתייחד עם חיוהי זהו בחי' האוא\"ס הבל\"ג שהוא בחי' התגלות העצמו' וענינו הוא בחי' הגילוי כו', וענין היחוד הוא להיות בחי' תוס' אור בהאו\"פ שעי\"ז יהי' הגילוי דהאו\"פ שלא בהגבלה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובאגה\"ק דאיהו המתייחד עם גרמוהי הוא האו\"פ, והיינו האור שלצורך ההתהוות שהכלי מגבילו, וכמו שהגוף מגביל ומגשם אור הנשמה, ובאמת ירידת הנשמה הוא להאיר את העולם, וזה ג\"כ ע\"י הגוף, והעיקר הוא בעובדי ה' בנשמתן שהגוף מגלה הנשמה (ולמעלה הוא בחי' פנימיות הכלים ופנימיות האורות), ומ\"מ העיקר הוא ע\"י תו\"מ, דלהאיר הוא להיות אתהפכא חשוכא לנהורא, והוא ע\"י ש' הוי' דלעילא, והנשמות ממשיכים הארה וע\"י תו\"מ המשכה עצמיות, וכן הביטול ויחוד האמיתי הוא ע\"י תו\"מ. וזהו ג\"כ שהאבות המשיכו שהעולם לא יסתיר וע\"י תומ\"צ הוא שהחשך יהפך לאור, ובעובדי ה' בגופם האור בא בהגשמה, ולמעלה הוא בחי' חיצוניות הכלים המלבישים ומגבילים בחי' חיצוניות האור שנק' שם הפעולה, והוא בחי' הארה נבדלת, וכמו האבן כשיוצא מיד הזורק שאז דוקא ניכר הפעולה, וזהו איהו וגרמוהי שהכלי יעלים על האור, שזהו בשרשו מכח הגבול, ואיהו וחיוהי הוא עילוי בהאור שבא במדה וגבול להיות בלי הגבלה.</span>\nקנו) <b>והנה</b> ידוע דשרש ההתהוות הוא מבחי' ז\"א דאצי', דג\"ר הן למע' מהעולמות וכמא' אלפים שנה קדמה תו' לעולם שהן אאלפך חכ' אאלפך בינה כו', וכתי' הנסתרות לה\"א דחו\"ב הן נסתרות עדיין כו', וז\"ת הן מקור העולמות וכמ\"ש זכור רחמיך וחסדיך כי מעולם כו', ובפרקי היכלות אי' שיעור קומה של יוצר בראשית רל\"ו אלפים פרסאות כמנין ורב כח. וידוע דיוצ\"ב היינו ז\"א דאצי' כו', והיינו לפי שבחי' ז\"א דאצי' זהו בחי' המציאות שבאצי' והו\"ע גרמוהי כו', וכמ\"ש"],[3601330476,"בע\"ח דגרמוהי הוא ז\"ת כו'. והענין הוא דהנה אי' בע\"ח דהתהוות ז\"א הוא מג' מדרי' והן אורות ניצוצות וכלים כו', וכולם הם מבחי' דתהו, דאורות הן האורות שנסתלקו כו', וניצוצות הן ניצוצי האור שנשארו בשברי הכלים כו', וכלים הן שברי הכלים שנפלו ומהם נבנה בנין הז\"א כו'. וידוע דספי' דתהו היו בבחי' מציאות דבר דזהו\"ע אנא אמלוך כו', ואפי' הביטול שלהם שלא הי' בבחי' הנחת עצמותו לאמיתי' הכוונה דלא לתהו בראה אלא לשבת כו', ולכן כשנתלבשו בכלים לא יכלו הכלים לסבול כו', וע\"כ בנין הז\"א שהוא מבחי' התהו ה\"ז ג\"כ בבחי' מציאות דבר כו'. והגם דכללות עולם התיקון הוא מה שנתקן מבחי' התהו כמ\"ש בע\"ח, מ\"מ הרי ידוע דהשבירה הי' רק בז\"ת ולא בג\"ר כו', ובבינה הי' השבירה רק בחיצוני' הבינה לא בבחי' פנימי' בינה וכ\"ש בחי' החכ' דכתיב ימותו ולא בחכ' כו', וע\"כ הג\"ר הם בחי' התיקון בעצם ואינם בבחי' מציאות כו', וז\"ת הן מה שנבנה מבחי' התהו וה\"ז בבחי' מציאות כו'. והגם דלידת והתגלות המדות הן מהמוחין שפועלים ביטול וחלישות בהמדות כו', וא\"ז כמו\nבתהו דשם ג\"כ המדות נמשכים מהמוחין ה\"ז בבחי' מעבר לבד כו', אבל בתיקון הרי המדות כלולים תחלה במוחין ומהם המה מתגלים כו', מ\"מ ה\"ה בבחי' מציאות כו', וגם כמו שכלולים בהמוחין ה\"ה בבחי' מציאות כו', וכמשנת\"ל פקנ\"א בענין וצפונך תמלא בטנם שהן בבחי' מציאות דבר כו', והתהוותן מהמוחין הן להיות בבחי' מציאות כו', וממילא גם הארת המוחין אינו מעצמות המוחין, וכנ\"ל פקנ\"ה בענין איהו וגרמוהי דבחי' איהו ה\"ז הארה לבד לא בחי' עצמות האור כו'. אך זהו במדות דבינה דשם הן בבחי' מציאות עד ששייך לומר שהן שם בבחי' עיבור כו', אבל מדות שבחכ' אינם בבחי' מציאות כו', דהגם שיש מדות גם בחכ' כו', הרי בחכ' אינו שייך ענין עיבור והיינו שהמדות דשם אינם בבחי' מציאות כו', וזהו ההמשכה מבחי' חכ' לא בבחי' מהות ומציאות דבר כו', וממילא גם האור הוא בחי' אור עצמי כו' וכנ\"ל בענין איהו וחיוהי כו' (דעיקר חיוהי הוא בחי' החכ' וכמ\"ש בע\"ח שגם בינה נק' גרמוהי לגבי החכ' כו'). והענין הוא דהנה ידוע דבז\"א יש פנימי' וחיצוני', דחיצוני' ז\"א הוא בבחי'\nהתחלקות ופנימי' ז\"א הוא בבחי' התכללות ומאיר בו שם הוי' וכמו ת\"ת שכולל חו\"ג שמאיר בו ש' הוי' כו', וכמו עד\"מ באדם הרי גופי האברים הן מחולקים ומובדלים זמ\"ז במזגו וטבעו כו' היד לכתוב והעין לראות כו', ובפנימי' ה\"ה קשורים וכלולים זע\"ז כו'. וכמו\"כ בחי' חיצוני' ז\"א המדות הן מובדלים ומופרדים זמ\"ז כו', ובפנימי' ה\"ה בבחי' התכללות מבחי' ש' מ\"ה דתיקון כו', וכמ\"ש בסדור שער המועדים, וזהו כמו מבחינת החכ' שזהו בחי' ש' מ\"ה כו'. וזהו ההמשכה דהאבות שהמשיכו גילוי אלקות והיינו שהמשיכו מבחי' איהו וחיוהי חד כו', דהתהוות העולמות הוא מבחי' גרמוהי דבחי' איהו שמתייחד עם גרמוהי זהו רק חיצוני' האור כו', והיחוד הוא רק לצורך ההתהוות שהוא בחי' העלם כו', אבל האבות המשיכו בחי' איהו וחיוהי כו', דהאורות ג\"כ באים בבחי' מדה וגבול כו', אך ע\"י תוס' אור בהם מבחי' איהו עי\"ז הוא ההמשכה שלא בבחי' מדה וגבול ונמשך האור והגילוי בכל המדרי' גם למטה כו'. ואחר כ\"ז הגם שהאבות המשיכו בחי' גילוי אלקות מ\"מ כללות ההמשכה הוא מבחי' האור דס'\nהשתל' כו', רק שהמשיכו מבחי' שרש ומקור ההשתל' כמו שהוא בבחי' חכ' ראשית ההשתל' דההמשכה הוא שלא בבחי' מדה וגבול כו', וע\"כ המשיכו בחי' מילוי החסרון דבחי' מל', דעי\"ז המשיכו גילוי אלקות גם למטה כו',"],[3601330477,"אבל מ\"מ א\"ז גילוי אור חדש ממש כו'. דזהו ההפרש בין ההמשכה דהאבות להמשכה דמ\"ת, דהאבות המשיכו רק משרש ומקור ההשתל' ובמ\"ת נמשך גילוי אור חדש ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ושרש ההתהוות הוא מבחי' ז\"א בחי' גרמוהי לפי הע\"ח, דג\"ר הן עצם התיקון בחי' מ\"ה, וז\"א הוא מבירור אנ\"כ דתהו בחי' מציאות, ולידת המדות מן המוחין להיות בבחי' מציאות, גם מדות שבבינה הן בבחי' מציאות, אבל בחכ' אינם במציאות, וזה נמשך בפנימיות ז\"א שזהו עיקר התיקון וההתכללות, וזהו שהמשיכו האבות בחי' איהו וחיוהי, וכ\"ז הוא מראשית ההשתל' רק שלא ע\"פ קה\"מ, והוא מילוי החסרון לבד, ובמ\"ת נמשך גילוי אור חדש.</span>\nקנז) <b>והענין</b> הוא דהנה כתי' די מחסורו, וארז\"ל אפי' סוס לרכוב ועבד לרוץ כו' שזהו ריבוי השפעה כו', אבל אי אתה מחוייב לעשרו, דענין העושר הוא בבחי' ריבוי ההשפעה שלא בהדרגה כלל כו', ובמאו\"א אות ע' ס\"נ כ' עשיר נק' ז\"א שיש לו כסף רב מהחסדים עכ\"ל, ופי' כסף רב היינו שנמשך מבחי' ת' עלמין דכסופין דיירתין צדיקייא לעלמא דאתי כו', והן בחי' אורות הנמשכים מבחי' עתיק כו', ומבו' במ\"א שזהו בחי' העונג העצמי הבלתי מורגש כו'. וזהו שנא' בהם עובר לסוחר, כי כתר נק' סוחר מל' סחור סחור שהוא בחי' מקיף להשתל' כו', והיינו בחי' חיצוני' הכתר בחי' עגולי א\"א שהן מקור להשתל' הכולל כולם וסובב ומקיף כולם כו' (ומתלבש בזה ג\"כ בחי' ז\"ת דעתיק שזהו עונג הפשוט הבא במורגש כו'), ועובר לסוחר היינו מה שלמע' מבחי' הכתר כו'. וזהו\"ע עשיר שהוא ההמשכה מבחי' פנימי' הכתר שאינו מקור להשתל' כלל כו', ועיקר ענין עשיר הוא בדעת וכמא' אין עני אלא בדעת ואין עשיר אלא בדעת, וידוע דהיינו בחי' ד\"ע וד\"ת, דעשיר הוא בחי' ד\"ע שמחליף מקום פנימי'\nהכתר כו', והוא הדעת שממשיך בחי' עצמות א\"ס כו', וכידוע ההפרש בהספי' בס' עמידתן אם הם עומדים זת\"ז או שהן בבחי' קוין דאז הדעת עומד תחת הכתר והיינו בחי' פנימי' הכתר כו', ועז\"א כשאין הכתר נמנה אז הדעת נמנה היינו שממשיך בחי' פנימי' הכתר באצי' כו', וזהו שאצי' הוא בחי' עצמות לא בחי' הפרשת הארה לבד כו' וכמשנת\"ל פקל\"ז, וד\"ת הוא שממשיך האור דס' השתל' כו', וכמ\"ש במ\"א. וז\"ע די מחסורו בחי' מילוי החסרון לבד היינו ההמשכה דס' השתל' וזה הי' המשכת האבות שהמשיכו תוס' אורות ולהיות גילוי אלקות למטה לפי שהמשיכו האור כמו שהוא בשרשו ומקורו שעי\"ז נמשך גם למטה גילוי אלקות כו'. אבל כ\"ז הוא האור דס' השתל' כו', דכללות ההמשכה דס' השתל' גם בחי' הגדלות שבזה הוא בבחי' קטנות לגבי בחי' עצמות א\"ס ב\"ה שלמע' מע' מס' השתל' כו' כמ\"ש במ\"א, ולכן הי' עיקר ההמשכה שלהם למע' להיות הגדלת הז\"א ברמ\"ח אברים כו', וכמ\"ש בתו\"א ד\"ה משה ידבר והביאורים, ולמטה הגם שהמשיכו גילוי אלקות וכמו ואת הנפש אשר עשו כו', אין לזה ערך לגבי ההמשכה שלהם למע'\nכו', והיינו מפני שהיו בבחי' קטנות עדיין בחי' יניקה לבד ע\"כ הי' עיקר המשכתם למע' כו'. וזהו וארא כו' באל שדי שכל ההמשכות שהמשיכו האבות הגם שהי' בזה גילוים נעלים והמשיכו גילוי אלקות למטה ג\"כ כו', הנה כ\"ז הוא בחי' שם אל שדי לבד כו', וידוע מ\"ש בלק\"ת מהאריז\"ל דהתחלת"],[3601330478,"היח\"ע דמ\"ת הי' מהאבות, והיינו מה שבעבודתם המשיכו גילוי אלקות בעולם ולהיות בחי' ביטול בעולם, אך היחוד שהתחיל מהאבות זהו בבחי' אל שדי אבל עיקר היחוד שמבחי' ש' הוי' זה נעשה ע\"י מ\"ת דוקא כו', וז\"ש ושמי הוי' לא נודעתי להם, דהגם שנא' כ\"פ ש' הוי' גבי האבות כ\"ז הוא הארת ש' הוי' שע\"י ש' אלקים וש' שדי, ונק' אל שדי דשם אל מורה על הגילוי וכל גילוי אור הוא מש' הוי' ואז גם הש' שדי הוא בבחי' גילוי דזהו\"ע שדי באלקותו כו', אבל ש' הוי' עצמו לא נתגלה להם כו', ולכן אמר לבנ\"י אני הוי' דבמ\"ת נתגלה ש' הוי' עצמו כו', ולכן עיקר ענין מ\"ת הוא שיהי' ההמשכה והגילוי למטה דוקא כו'. וז\"ע מ\"ש כי ההרים ימושו והגבעות תמוטינה וחסדי מאתך לא ימוש וברית שלומי לא תמוט, דהרים הן האבות שהמשיכו גילוי אלקות אבל עיקר המשכתם הי' למע' כו', ואו' ע\"ז כי ההרים ימושו כו', אבל וברית שלומי לא תמוט והיינו בחי' יסוד שבעצמות כו', דהנה יסוד הוא המקשר ומחבר וכמ\"ש כי כל בשמים ובארץ דאחיד כו', רק שזהו בחי' יסוד שבאצי' שאינו מקשר עד למטה ממש כו', אבל ברית שלומי הוא בחי' יסוד שבעצמות שמקשר עד למטה מטה כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש פנחס בן אלעזר כו' השיב את חמתי מעל בנ\"י כו', דהנה אי' בזהר דבפנחס נתגלגל נשמת נדב ואביהוא וע\"י נתתקנו. דהנה חטא נדב ואביהוא הי' כמ\"ש בקרבתם לפני ה' וימותו כו', שהו\"ע עריבות נעימות כו', עד שתגעל הנפש את הבשר כו', דלכאורה א\"מ מפני מה נחשב זה לחטא הלא זה עבודה גבוה ונעלה ביותר בבחי' כלוה\"נ ממש כו'. אך הענין הוא שהי' אצלם שלא כפי הכוונה האמיתית, דהכוונה היא כמ\"ש לא לתהו בראה אלא לשבת יצרה והיינו שאחר הרצוא יהי' שוב כו', דמתחלה צ\"ל הרצוא בבחי' כלוה\"נ דהיינו האה' דבכל מאדך שהו\"ע עושין רש\"מ כו', ואח\"כ צ\"ל השוב בקיום התומ\"צ כו', והו\"ע והיו הדברים האלה שאומרים אחר בכל מאדך דבד\"ת הכתוב מדבר כו'. דהנה בפ\"ר דק\"ש או' שמע ישראל ה' אלקינו ה' אחד, ואי' ברוקח דג' שמות ה' אלקינו ה' הם אני ראשון ואני אחרון ומבלעדי אין אלקים, אני ראשון הוא לפה\"צ ואני אחרון לאחה\"צ, ומבלעדי באמצעיתא אין אלקים המסתיר, דאוא\"ס הוא יחיד ומיוחד אחה\"צ כמו קוה\"צ דאתה הוא עד שלא נברה\"ע ואתה כו', ומה\nשנתהוו העולמות בבחי' מציאות כו', הוא מבחי' הארה דהארה לבד שז\"ע בשכמל\"ו כו', והו\"ע איהו וגרמוהי חד בחי' חיצוני' האור המתלבש בחיצוני' הכלים כו'. וכשיתבונן בזה איך דאוא\"ס הוא יחיד ומיוחד לאחה\"צ כמו קודם כו', וההתהוות הוא רק מהארה חיצוני' לבד כו', עי\"ז יהי' הרצוא בבחי' כליון בעצמותו וכמ\"ש מי לי בשמים ועמך לא חפצתי כו', דלבד זאת שאינו חפץ בחיצוני' העולמות אלא שגם בההארה לא חפצתי כ\"א להכלל בעצמות אוא\"ס ב\"ה כו'. וכאשר בא בבחי' הרצוא לבחי' העצמות אז הוא דוקא השוב שז\"ע והיו הדברים האלה בד\"ת הכתוב מדבר, דהיכן מוצאים בחי' העצמות ה\"ז בתו' כו', וזהו תכלית הכוונה בהרצוא שיהי' אחריו שוב כו', וצ\"ל הרצוא באופן כזה שיהי' בבחי' אחיזה בפנימי' בכדי שיהי' אחריו שוב כו'. אך בנדב ואביהו הי' הרצוא בכלות הנפש שלא רצו בהשוב כ\"א בהרצוא והי' אצלם שלא בבחי' אחיזה בפנימי' כו', וע\"כ בהרצוא שלהם הי' הסתלקות הנפש והגוף נשאר קיים כו', וזה הי' החטא שלהם שהי' בהם רצוא בלא שוב כו', ונתתקנו"],[3601330479,"ע\"י פנחס שהי' אצלו מס\"נ בפו\"מ והוא מסירת הגוף דזה גופא היא מצוה שהו\"ע קידוש השם בפו\"מ כו', ומ\"מ הי' בבחי' אחיזה בפנימי' שהרי לא הי' בבחי' כלוה\"נ בפו\"מ והמס\"נ הי' בגדר מצוה לקיים רצונו ית' כו', ולכן ע\"י תיקון חטא נדב ואביהו כו'. וע\"ז ניתן לו הקבלת שכר דהנני נותן לו את בריתי שלום שזהו בחי' יסוד שבעצמות והיינו המשכת עצמות כו', דע\"י מס\"נ ובפרט במס\"נ בפו\"מ שהיא מצוה כו' ממשיכים בחי' עצמות א\"ס ב\"ה, וההמשכה היא ע\"י התו' שנק' ג\"כ ברית שלום, וכידוע שהתו' נק' ברית וכמ\"ש אם לא בריתי יומם ולילה וכתי' וכל נתיבותי' שלום, והיינו שע\"י התו' הוא המשכת העצמות כו', דהתו' היא בחי' חכ' ובבחי' פנימי' ועצמי' החכ' נמשך בחי' פנימי' ועצמי' א\"ס כו' וכמשי\"ת. וזהו דהקבלת שכר שלו הוא בבחי' בריתי שלום שהו\"ע וברית שלומי כו', ומ\"ש השיב את חמתי פי' השיב הו\"ע ההשבה, והיינו שהשיב מן הפירוד אל היחוד כו', ובהשבה יש ב' ענינים, אם ההשבה מן הפירוד לבד או שנכלל ממש ביחודו ית', וכאן הכוונה שהשיב בבחי' היחוד ממש כו', והו\"ע אתהפכא\nחשול\"נ שזהו בכח העצמות דוקא כנ\"ל, וע\"ז הוא השכר הנני נותן לו את בריתי שלום בחי' יסוד שבעצמות כו'. וזהו שא' במדרש משיב חימה בנו של אהרן שהשיב חימה ע\"י הקטרת, דהנה י\"א סממני הקטרת ידוע שהן נגד י\"א כתרין כו', דענין ההקטרה הוא האתהפכא כו', וכמו\"כ פנחס השיב את חמתי שהרע נהפך לטוב כו', והקבלת שכר ע\"ז הוא ברית שלום כו', וזהו פנחס בן אלעזר כו', דבפנחס הי' מס\"נ בפו\"מ רק שהי' בבחי' אחיזה בפנימי' והיא גופא הי' מצוה כו', ועי\"ז השיב את חמתי בבחי' אתהפכא חשול\"נ כו', וע\"כ הנני נותן לו את בריתי שלום בחי' יסוד שבעצמות להיות המשכת העצמות עד למטה מטה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> די מחסורו אי אתה מחויב לעשרו, עשיר ז\"א שיש לו כסף רב הן ת' עלמין דכסופין והן עובר לסוחר, סוחר עיגולי אריך, עובר לסוחר עתיק, אין עשיר אלא בדעת ד\"ע שממשיך מפנימיות הכתר, וזהו ש' הוי' שנמשך במ\"ת ואמת הוי', והאבות המשיכו ש' שדי, ולכן הי' עיקר הגילוי למעלה (ומ\"מ הי' זה הכנה) למ\"ת. וזהו כי ההרים ימושו וברית שלומי לא תמוט, יסוד שבעצמות שנמשך עד למטה. וזהו פנחס כו' ברית שלום, נדב ואביהו הי' רצוא בלא שוב ובתיקון צ\"ל רו\"ש ה' אחד מס\"נ ואח\"כ והיו הדברים האלה, ופנחס תיקן ע\"י מס\"נ בפו\"מ בגדר מצוה, ע\"כ הנני נותן לו ברית שלום בחי' וברית שלומי לא תמוט.</span>"],[3601330480,"<h3>בס\"ד. ש\"פ מטות, תער\"ג</h3>\n<b>וידבר</b> משה אל ראשי המטות לבנ\"י לאמר, זה הדבר אשר צוה ה' כו', וצ\"ל מהו ההפרש בין שבטים למטות דפעמים נא' שבטים וכמ\"ש כל אלה שבטי ישראל כו', ופעמים נא' מטות מהו ההפרש ביניהם. ומפני מה בנדרים נא' ל' מטות כו'. גם מהו\"ע ראשי המטות כו'. גם צ\"ל מ\"ש זה הדבר אשר צוה ה' מהו ההקדמה"],[3601330481,"הזאת והול\"ל מיד איש איש כו', מהו אומרו תחלה זה הדבר כו'. ולהבין זה ילה\"ק משנת\"ל דהמשכה דתו' הוא המשכת אור חדש כו', דהאבות הגם שהמשיכו בחי' גילוי אלקות בעולם מ\"מ ההמשכה הוא האור דס' השתל' לא גילוי אור חדש כו', וז\"ש ושמי הוי' לא נודעתי להם לא ניכרתי במדת האמיתי' שלי דהיינו אמיתי' ש' הוי' עצמו לא נמשך להאבות להיות המשכתם הוא רק האור דס' השתל' כו', רק שהמשיכו משרש ומקור ההשתל' כמו שהוא בבחי' החכ' שעי\"ז המשיכו גילוי אלקות כו'. וז\"ע וארא כו' באל שדי כו' שדי באלקותו לכל ברי' וגם שאין העולם ומלואו כדאי כו', וכמשנת\"ל (ד\"ה ויקח קרח), וה\"ז למע' מההמשכה דברה\"ע ע\"פ מא' קו המדה דההמשכה במדרי' התחתונה אינו כפי מהות מדרי' העליונה כו', והאבות המשיכו האור שלא ע\"פ מא' קו המדה והמשיכו עי\"ז גילוי אלקות בעולם כו', מ\"מ א\"ז או\"ח כו', אך ע\"י התורה נמשך גילוי או\"ח ממש בחי' גילוי אור עצמי כו'.\nקנח) <b>אך</b> לכאורה צ\"ל והלא כל ההמשכות והגילוים שבעולמות הכל הוא ע\"פ קו המדה, דאא\"ל שום המשכה וגילוי בעולמות כ\"א ע\"י המדידה כו', דגם אורות מקיפים הם בבחי' מדידה כו', וכמ\"ש ושקל בפלס הרים, דהרים הן הרים הגבוהים ליעלים בחי' מדות דא\"א ה\"ה ג\"כ במשקל כו' וכמ\"ש במ\"א, ומכ\"ש או\"פ שהם בבחי' משקל ומדידה כו', והמדידה הוא באופן המשכת האור ובאופן שיתקבל בעולמות כו' (ידוע במשל דמשפיע ומקבל שלאחר שמעלים המשפיע אור שכלו העצמי שנמצא בו אור השכל השייך אל המקבל, ה\"ה נמצא תחלה בבחי' נקודה ואח\"כ מפרט הפרטים בעצמו מה שיכול להתגלות אל המקבל, וזה עדיין לפי ערך שכלו של המשפיע ולמעלה עדיין מגילוי אל המקבל, וצ\"ל עוד צמצום שיהי' אור השכל לפי ערך כלי המקבל שיתקבל בכלים וחושים של המקבל כו', וכמ\"ש באגה\"ק סי' ט\"ו בענין כליות יועצות שלא יומשך כמו שהוא שכל דק מאד במוחו ושכלו רק ישתנה קצת מדקות שכלו ויתהווה שכל שאינו דק כ\"כ כדי שיוכל הבן לקבל כו' עכ\"ל, וזהו שהנקודה והפרטים לעצמו הוא המדידה בהמשכת האור והגילוי,\nואח\"כ מה שמתהווה שכל שלפ\"ע המקבל זהו המדידה באופן שיתקבל אל המקבל כו', ובהדוגמא מזה למעלה יובן דהמשכת האבות הוא ג\"כ בחי' חיצוניות האור רק שזהו כמו שהוא בעצמות המשפיע כו', והיינו בחי' אורות עצמיים דע\"ס דאצי' בבחי' חיצוניותן כו' ועמשנת\"ל פקל\"ז). ואפי' הגילוים דתומ\"צ הן ג\"כ בבחי' מדידה כו', דזהו\"ע פרטי הענינים שיש במצות וכמו תפילין וציצית ושבת כו', דהחילוקים הם באופני ההמשכות כו' (דע\"ה שכולם הם המשכות העצמות ומ\"מ הם במצות חלוקות דהיינו החילוק באופני ההמשכה כו'). ויש מדידה בכל מצוה ומצוה באופן עשייתה כו', דזהו מה שהתו' מפרש ומבאר איך היא כל מצוה ואז דוקא נמשך האור ע\"י כו', דציצית הוא באופן כך וכך ותפילין באופן כך וכך כו', ושבת לאו זמן תפילין דמצד ההמשכה דשבת א\"צ אז לתפילין כו', הרי כ\"ז הוא המדידה באופן המשכת האור והגילוי כו'. וכמו\"כ יש מדידה באופן גילוי אור התו' בעולמות וכנודע שיש תו' אצי' ותו' הברי' וכמו ועל תורתך שלמדתנו דפי' בכהאריז\"ל על תורתך תו' האצי' שלמדתנו היא תו' הברי' כו', שזהו ההפרש באופן הגילוי כמו שהוא באצי' וכמו שהוא בברי' כו'. הרי שכל המשכה וכל גילוי שמאיר"],[3601330482,"בעולמות הכל הוא בבחי' מדידה כו', וא\"כ איך נא' דההמשכה דברה\"ע הוא ע\"פ מא' קו המדה, וההמשכה דהאבות אינו ע\"פ קו המדה וכ\"ש ההמשכה דתו' שאינה ע\"פ קו המדה, מאחר שכל ההמשכות הן בבחי' מדידה כו'. אך הענין הוא דבאמת כל המשכה צ\"ל בבחי' מדידה, אך בבחי' קו המדה יש בזה כמה מדרי' כו', והענין הוא דהנה כתי' והנה איש מראהו מראה הנחשת ופתיל פשתן בידו וקנה המדה, ואי' בזהר פ' פקודי זמנין קו המדה וזימנין קנה המדה דאינון פתיל וקנה כו', דהנה ההפרש בכלל בין קו המדה וקנה המדה הוא ההפרש בבחי' חסדים וגבו' כו', דהנה כל מדידה הוא בחי' גבו' שהרי המדידה הו\"ע ההגבלה שזהו בחי' גבו' כו', ושרשו מבחי' בוצינא דקרדוניתא שזהו בחי' גבו' דעתיק שמלובש במו\"ס כו', אך קנה המדה הוא בחי' חסדים כו', דהנה קנה גדולו הוא על המים וכמו קנה וסוף קמלו, וכמו כאשר ינוד הקנה במים כו', וזהו פתיל וקנה דפשתן עיקר גדולו הוא מן העפר ולכן גדל בד בד יחידי שהו\"ע ההתחלקות שמיסוד העפר כו', וזהו פתיל וקנה היינו קו המדה וקנה המדה, דקו המדה הוא בחי' גבו'\nוקנה המדה חסד כו'. והענין הוא דהנה קו המדה הוא שנותן מדה וקצבה אל אצי' הספי' בבחי' התפשטות והתגלות שלהם כו', דבכל ספי' יש מדה וקצבה להתפשטות שלה דעד פה תבא כו', בכדי שיוכל להיות הספי' האחרת שלמטה ממנו, דכל זמן שהספי' העליונה היא בהתגלות אא\"ל אצי' הספי' התחתונה כ\"א דוקא כאשר נפסקה התפשטות הספי' העליונה אז יכול להיות אצי' ספי' התחתונה כו', וכמו ספי' הכתר אם הי' ההתפשטות וההתגלות שלה בבחי' א\"ס לא הי' אפ\"ל אצי' ספי' החכ' כו'. וכמו עד\"מ באדם למטה בכחות הנפש דכאשר הרצון הוא בהתגלות אא\"ל התגלות השכל כו', דלהיות שהרצון הו\"ע אחר לגמרי מהשכל ע\"כ בהתגלות הרצון לא יהי' התגלות השכל כו', וכמו שאנ\"ר בחוש דמי שהוא בעל רצונות בטבעו לא יהי' אצלו הנהגה שכלי' דלהיות שהנהגתו הוא ע\"פ הרצון אין אצלו הנהגה שכלית כו', ובאמת אינו שייך כלל לענין השכל דמפני התגלות הרצון אצלו תמיד לא יבין ענין שכלי לאמתתו כו', הרי כשהרצון הוא בהתגלות לא יש התגלות השכל כ\"א דוקא כאשר נפסק התגלות הרצון אז יהי' התגלות השכל כו'. וכ\"ה\nבעבודה דכאשר הרצון הוא בהתגלות דהיינו בבחי' רעו\"ד אינו שייך אז לשכלי כו', דלהיות שרעו\"ד הוא למע' מהדעת ע\"כ בהתגלות בחי' רעו\"ד אינו שייך אז לשכל והתבוננות כו', וזה גם ברעו\"ד הבאה ע\"י התבוננות כו', וכנודע שגם רעו\"ד באה ההתעוררות ע\"י התבוננות והוא ההתבוננות בבחי' עצמות אוא\"ס בבחי' ההפלאה והרוממות דאוא\"ס שעי\"ז מתעורר ברעו\"ד כו', הרי שזה בא ע\"י השגה, והיינו שתחלה צ\"ל ההשגה בהגילוים שבעולמות באופני הגילוים שמזה יבין את העילוי וההפלאה דאוא\"ס ויתפעל בבחי' רעו\"ד כו'. הנה כאשר מתפעל ברעו\"ד אינו שייך אז לשכלי כו', דע\"ה שזה בא ע\"י השגה, מ\"מ לאחר שמשיג את הגילוים ובא לידי ההשגה וההרגש דההפלאה דאוא\"ס שעי\"ז נתפעל ברעו\"ד כו', הנה בעת ההתפעלות דרעו\"ד נאבד אצלו ההרגש שכלי כו', הגם שמזה בא ההתעוררות מ\"מ כאשר מתעורר ברעו\"ד נאבד ההרגש שכלי וה\"ה בהתפעלות שלמע' מטו\"ד כו' (ולכאורה זהו כמו המדות דהתגלותן הוא דוקא בהתעלמות השכל, הנה לבד זאת שבעצם מהותן אינם דומין כלל, דמדות הן בבחי' הרגש עצמו כמשנת\"ל פקמ\"ט והוא\nשרוצה האור והגילוי שזה טוב לו כו', והרצון שלמעלה מהשכל הוא אדרבא ביטול כל עצמותו, וכמ\"ש בסש\"ב פי\"ט הגם שתהי' אין ואפס"],[3601330483,"ותתבטל שם במציאות לגמרי כו', אעפ\"כ זה רצונה וחפצה בטבעה כו' (רק להיות שזהו בבחי' רצון עכ\"פ מבו' במ\"א שזהו עדיין בבחי' יש מי שרוצה כו', וזהו ההפרש בין מקיף דחי' למקיף דיחידה שאינו בבחי' רצון כלל והוא כשלהבת העולה מאלי' בלי בחירה ורצון כלל כו' וכמ\"ש במ\"א), והיינו מפני שבמדות אין בזה הרגש האלקי כ\"כ כ\"א ההרגש דקרבת אלקים לו טוב, וברצון דרעו\"ד הוא הרגש הא\"ס ביותר ע\"כ הוא בבחי' ביטול כל מציאותו כו'. הנה גם באופן התעוררות הרצון הרי שע\"פ טו\"ד הוא דוקא לאחר שמתעלם ההשגה וההתבוננות, ורעו\"ד הוא שההתעוררות היא בעת תוקף התגלות אור המוחין (והיינו כמ\"ש במ\"א דבכוחות הגלוים הרי מוחין ומדות א\"א להיות יחד דבעת התגלות המוחין הוא למעלה מהמדות, והמדות מבלבלין אל המוחין, ודוקא לאחר הפסק המוחין יכול להיות המדות כו' וכמו שמבו' כאן, ובכחות הנעלמים יכולים להיות ביחד דבעת התגלות המוחין יכול להיות המדות (וברעו\"ד המבו' כאן הוא דוקא בעת תוקף התגלות המוחין כו'), והוא מפני שהמדות אינם בבחי' הרגש עצמו, וגם המדות אינם\nמבלבלים אל המוחין כו', וזהו דברעו\"ד התעוררות הרצון הוא בתוקף התגלות המוחין. ועוד דבמדות הרי המדה היא מן ההשגה וההתבוננות, וכמשנת\"ל פק\"נ שיש התבוננות מיוחדת למדת האהבה והתבוננות מיוחדת ליראה, וברעו\"ד התעוררות הרצון הוא מההרגש דא\"ס היינו לא מהרגש ההפלאה דא\"ס כ\"א מהרגש הא\"ס, וההשגה וההתבוננות בההפלאה דא\"ס הוא בכדי להביאו להרגש הא\"ס, ומזה הוא שמתעורר בתוקף הרצון כו', ולפמשנת\"ל פקנ\"א לכאו' מתדמין הם, אך במדות הוא שהבכן הוא למטה הרבה מהמוחין, וברעו\"ד הוא בעילוי רב, ומשום ההרגש דא\"ס הוא שנאבד ההרגש שכלי, וגם משום דבהתעוררות הרצון מתעלה מענין השכל כו', ובכ\"ז עיקר סיבת הדבר הוא דבמדות הוא רצון העשוי ונק' אהבה התלוי' בדבר שכל עיקר האהבה היא מהשכל, וברעו\"ד הוא רצון עצמי שאינו תלוי בדבר, והשכלי הוא להביא להרגש הא\"ס והתגלות הרצון העצמי כו' ועמשית\"ל פ'). רק יש בזה הפרש אם ההתבוננות היא רק בענין ההפלאה דאוא\"ס או שההתבוננות הוא באופן ההפלאה דאז גם הרעו\"ד היא שכלי' כו', דכאשר הרעו\"ד היא מהשגת אופן\nההפלאה ה\"ה בבחי' אה' בתענוגים, ואה' בתענוגים הם בחי' פנימי כו' (וכנודע דפנימי' המקיף הוא בחי' פנימי כו'), והיינו כאשר ההשגה וההרגש הוא באופן ההפלאה דאוא\"ס ב\"ה ה\"ה בבחי' כליון להתענג על הוי' שזהו בחי' פנימי כו', אבל כאשר ההשגה היא רק בענין ההפלאה ומזה הוא מתפעל ברעו\"ד ההתפעלות הוא למע' מטו\"ד שהשכלי נאבד בעת ההתפעלות כו', ומכ\"ש כאשר הרעו\"ד היא מצד העצם שלא ע\"י השגה והתבוננות כלל (דהיינו בחי' מקיף דיחידה) שאינו שייך אז לשכלי כו'. וכמו בר\"ה ויו\"כ ועשי\"ת שמאירים ומתגלים אז המקיפים שבנפש דאינו שייך אז העבודה דמוח ולב כמו כל השנה שהעיקר הוא העבודה בהשגה והתבוננות והתעוררות אהוי\"ר שע\"י התבוננות כו', משא\"כ בזמן הנ\"ל אין העבודה במוח ולב כ\"א בבחי' המקיפים דנפש כו', הרי שבהתגלות הרצון לא יוכל להיות התגלות השכל כו'. והנה הרצון הוא מקור השכל היינו כשרוצה להתחכם לא רק הרצון בעצם הדבר כו', דבזה שרוצה בהדבר לא יהי' עדיין ההתחכמות מזה כ\"א כאשר רוצה להתחכם דבזה ה\"ה יורד (ער טרעט א() מעצם הרצון כו', ואז ישכיל ויתחכם כו', וגם בהרצון להתחכם זהו דוקא כשהרצון הוא"],[3601330484,"בבחי' מקיף, דכאשר הרצון להתחכם הוא בתוקף ההתגלות לא יתחכם כו', כי זה מבלבל לההתחכמות כו', רק כשרוצה להתחכם והוא בבחי' מקיף מרחוק אז ישכיל ויתחכם כו' כמ\"ש במ\"א. הרי שבהתגלות הרצון אא\"ל התגלות השכל, כ\"א כאשר נפסק ומתעלם הרצון ונשאר רק אפס קצהו אז הוא התגלות השכל כו'. וכ\"ה במוחין ומדות דכאשר המוחין הם בהתגלות אא\"ל התגלות המדות, רק כאשר נפסק ומתעלם אור המוחין אז יכול להיות התגלות המדות כו' וכידוע. וכמו\"כ במוחין גופא בחו\"ב כו', דהגם שנקודת ההשכלה מתלבשת בהשגה שהרי כל ענין ההשגה הוא להבין את הנקודה ולפרט הפרטים שבה כו', מ\"מ א\"ז עצמות החכ' שהרי עצמות החכ' הו\"ע ראי' והתאמתות וההנחה שמצד ההתאמתות שזה א\"א לבא בהשגה כו', וגם בנקודת ההשכלה (דהיינו מה שמהחכ' בא בחי' שכל גלוי כו'), הרי העיקר הוא ההנחה שכלי' שהוא ג\"כ ענין התאמתות כו' וכמשנת\"ל פמ\"ב, וכאשר מאיר בחי' ההתאמתות וגם ההנחה שכליות אין מניח לענין השכל והשגה (דאס דער לאזט ניט צום השגת הענין), דהרי התאמתות ה\"ז למע' הרבה מהשגה וע\"כ הרגש ההתאמתות\nאינו מניח לענין ההשגה כו'. והגם שמבו' במ\"א שע\"י בחי' הראי' דחכ' תהי' ההשגה ג\"כ באופן נעלה ביותר שבא על עומק הענינים שבהשכלי ביותר כו', האמת כ\"ה דכאשר יודע עצם הענין בבחי' ראי' שהוא במהות הדבר ה\"ה בא בהשגה ג\"כ על עומק ופנימי' הענין בהשכלות עמוקות ביותר כו', אך זהו דוקא כשמתעלם ההתאמתות כו', דכאשר ההתאמתות היא בהתגלות א\"ז מניח לההשגה, כ\"א כאשר מתעלם ההתאמתות ומ\"מ ה\"ה יודע את הענין בעצם מהותו אז תהי' ההשגה בעומק הענין ביותר כו'. וזהו מה שנת\"ל בד\"ה הנ\"ל דכאשר מייגע באיזה ענין שאינו מובן ונופל בשכלו שהוא באופן כך וכך ומתיישב אצלו הענין, וכאשר רוצה להביא הענין לידי השגה עדיין אינו מושג כו', שזהו לפי שבתחלה הי' אצלו בבחי' הנחה שכלי' לבד כו', והעצה הוא שיקשר עצמו (ער זאל זעך צו טראגין) איך הי' אצלו הענין בעת ההנחה כו', ומתחדש בהתקשרות הזאת דכאשר מקשר עצמו עוד הפעם אל ההנחה אז הוא בבחי' ירידה מעצם ההנחה (ער איז שיים א(גיטראטין מההנחה ממש), והוא שייך יותר אל השכלי מאל ההנחה כו', ועי\"ז יבא אל השגת\nהענין כו'. וזהו ההפרש דכאשר ההתגברות היא ההנחה אז השכלי בהעלם וכאשר השכלי הוא בהתגלות אז ההנחה היא בהעלם כו', ואז תהי' ההשגה כו', הרי דמהתגלות החכ' אא\"ל השגה דבינה כ\"א כאשר מתעלם אור החכ' ונשאר רק אפס קצהו אז תהי' ההשגה דבינה כו', הרי דבכחות הנפש בהתגלות הכח העליון אא\"ל התגלות כח רק כאשר נפסק ומתעלם הכח העליון אז יהי' התגלות הכח התחתון כו'. וכמו\"כ הוא למע' באצי' הספי' דכאשר הספי' העליונה מאירה בגילוי אא\"ל התהוות ואצי' ספי' התחתונה, ובכדי שיהי' התהוות ואצי' הספי' התחתונה צ\"ל הפסק בהתפשטות הספי' העליונה כו', וז\"ע קו המדה שהוא ההגבלה להגביל התפשטות הספי' בכדי שיהי' אצי' הספי' האחרת כו', וזהו דקו המדה הוא בחי' גבו' שזהו לפעול ההגבלה והעדר התפשטות הספי' כו'. וזהו הטעם מה שבהשתל' הספי' כל מה שנשתלשל ממדרי' למדרי' מתגלה בחי' הדינין והגבו' יותר כו', שהרי הכתר הוא בבחי' רחמים פשוטים כו', והחכ' אי' בחייט שיש בה קצת דין כו', ובינה מינה דינין מתערין רק שזהו בסופה בבחי' חיצוני' הבינה כו', ובז\"א יש חו\"ג כו', ועיקר ההתחלקות הוא בז\"א ע\"י בחי' הגבו' כו', ומל' עיקר בנינה הוא מהגבו' כו' כנודע."],[3601330485,"<b>וזהו</b> מפני שאצי' הספי' הוא ע\"י מא' קו המדה שהוא בחי' ההגבלה להגביל כו', ע\"כ ממדרי' למדרי' מתגלה הגבו' יותר כו'. אמנם בחי' קנה המדה שהוא ג\"כ ענין המדידה, אבל המדידה הוא בבחי' חסד כו', והיינו המדידה בבחי' האור והגילוי כו', שגם גילוי האור יש בזה מדידה באיזה אופן יומשך האור כו', רק שמדידה הזאת היא בבחי' החסד כו'. דהנה תחלה היא המדידה בהתהוות הספי' וכמשנת\"ל דבכדי שיהי' התהוות ואצי' הספי' התחתונה צ\"ל הגבלה והפסק בהתפשטות הספי' העליונה כו', וזהו ע\"י קו המדה כו', ואח\"כ כאשר כבר נאצלה הספי' התחתונה והיא כלי לקבל את האור כו', גם בזה יש מדידה באיזה אופן יומשך האור והגילוי מהספי' העליונה בהספי' התחתונה כו', והיינו שיהי' גילוי יותר מכפי שנקצב ע\"פ קו המדה כו', שע\"י המשכת האור והגילוי נעשה המתקת הגבו' כו'. והענין הוא כדאי' במד\"ר פ' אמור ע\"פ עלה אלקים בתרועה עומד מכסא דין ויושב על כסא רחמים, והיינו שהדין נהפך לחסד ורחמים כו', וזהו\"ע עלה אלקים העלי' דש' אלקים שנעשה כמהות ש' הוי' שע\"י הגילוי דש' הוי' בש'\nאלקים נעשה הש' אלקים כמהות ש' הוי' כו', והוא שיהי' גילוי בחי' א\"א בז\"א עד שז\"א יהי' כמו א\"א כו', ומדידה זו באופן המשכת האור זה\"ע קנה המדה שהוא בחי' חסדים כו'. ובד\"כ זהו ההפרש בין המדידה שמבחי' הבינה להמדידה מבחי' חכ', דבינה הוא בחי' קו המדה וכמשנת\"ל (ד\"ה פנחס בן אלעזר) בשם המאו\"א דעיקרה הוא בחי' גבו' ה\"ג דאימא ומקבלת מבחי' גבו' דעתיק שמלובש במו\"ס כו', וקנה המדה הוא בחי' חכ' דעיקרה בחי' חסדים ומקבלת מבחי' חסד דע\"י שמלובש בגולגלתא כו' (וזהו ההפרש בין המדידה דברה\"ע להמדידה שבהמשכת האבות, דהמדידה דברה\"ע הוא ע\"י קו המדה כו', וההמשכה שהאבות המשיכו בחי' גילוי אור זהו ע\"י המדידה דבחי' קנה המדה כו').\n<span data-k=\"ks\"><b>קיצור.</b> וצ\"ל והלא כל הגילוים גם או\"מ הוא ע\"פ קה\"מ ומכ\"ש או\"פ שיש מדידה באופן הגילוי שזהו בעצם האצי' עדיין ואיך שיתקבל בעולמות, אך הנה יש קו המדה וקנה המדה, פתיל וקנה, קה\"מ הוא גבו' למדוד ספי' שיוכל להיות הספי' שאחרי', דבתוקף התגלות הרצון א\"א להיות שכל, ובעבודה רעו\"ד למעלה מהשכל, גם שבא ע\"י התבוננות ההפלאה, זהו מהרגש הא\"ס שמתגלה רצון העצמי, ובהתעוררות הרצון נאבד ההרגש שכלי (ובהשגת אופן ההפלאה הוא אהבה בתענוגים), והרצון להתחכם הוא מקור החכ', וג\"ז כשאינו בתוקף, וכן בחו\"ב הרי עצם החכ' היא התאמתות שזהו למעלה מהשגה, ויהי' מזה השגות עמוקות אך לאחר התעלמות ההתאמתות, וגם הנחה שכליות למעלה מהשגה, רק בהתגברות השכלי על ההנחה, וכן לאחר התעלמות המוחין הוא התגלות המדות, והדוגמא מזה בע\"ס המדידה ע\"י קה\"מ, ולכן כל שמשתלשל יותר מתגלה יותר בחי' הדין והגבו', אמנם קנ\"ה הוא בחי' חסדים, והוא מדידת האור שיהי' המתקת הגבו', וכמו עלה אלקים, והוא המשכת א\"א בז\"א, ובד\"כ הוא ההפרש בין המדידה דבינה והמדידה דחכ', שמקבלת מבחי' חסד דעת\"י.</span>\nקנט) <b>והנה</b> המדידה דתורה הוא בחי' גבו' (והיינו שא\"ז כמו שהחכ' מקבלת מבחי' חסד דעת\"י כ\"א זהו בחי' פנימי' ועצמי' החכ' שמקבלת מבחי' גבו'"],[3601330486,"דעתיק כו', והו\"ע פנימי' אבא פנימי' עתיק כו' וכמשי\"ת), הגם שהתו' היא תו' חסד יש בזה ג\"כ גבו' וכמ\"ש מימינו אש דת כו', אך הגבו' היא בחי' תגבורת כח כו', והוא להיות שהתו' היא המשכת העצמות כו', ובכדי שיהי' המשכת העצמות צ\"ל בבחי' תגבורת כח כו', הא' מפני שהעצמות אינו בגדר המשכה ובגדר גילוי, וע\"כ בכדי שיהי' המשכת וגילוי העצמות ה\"ז בבחי' תגבורת כח כו', הב' שהעצמות אינו בערך שיתקבל בעולמות כמא' הוא מקומו ש\"ע ואין העולם מקומו כו', ולזאת צ\"ל תגבורת כח כו'. וידוע דכל תגבורת בא בהתחלקות פרטים וכמו גבורות גשמים שיורדים טיפין טיפין וכמו מעין המתגבר שנובע טיפין טיפין, והכל הוא מהות א' רק שבא בהתחלקות מצד התגבורת כו'. וכמו\"כ בחי' המשכת העצמות שהוא בתגבורת דוקא ה\"ז בא בבחי' התחלקות פרטים, וא\"ז התחלקות כי הכל מהות א', וההתחלקות הוא רק מצד התגבורת כו'. וזהו\"ע פרטי המצות כמו ציצית ותפילין וכה\"ג שזהו בחי' התחלקות הפרטים מצד התגבורת העצמות והכל הוא בחי' עצמות א\"ס כו', רק שבחי' העצמות אינו בא בפרט א' כ\"א בריבוי\nפרטים מצד התגבורת והכל הוא בחי' עצמות כו', וזהו ג\"כ המדידה באופן המצוה שהתורה מפרש ומבאר את המצות שצ\"ל באופן כך וכך, דמאחר שבא בבחי' התחלקות פרטים הרי יש מדידה באיזה אופן נמשך כו', והיינו כשהמצוה היא באופן כך וכך נמשך בזה המשכת העצמות כו', וגם בתו' גופא היא המשכת העצמות וצ\"ל בזה מדידה שמצד התגבורת כו'. וזהו שהמדידה דתו' היא בבחי' גבו' הן בהמשכת התו' שזהו בבחי' תגבורת העצמות והן באופני המשכות דמצות כו', והכל הוא המשכת העצמות כו'. ומה שיש חילוקים בתו' כמו תורת אצי' ותו' הברי' כו' זהו באופני הגילוים בעולמות כו', וכמו עד\"מ באדם שיש לו מקומו שהוא נמצא שם ויכול להיות עצמותו נמצא שלא במקומו וזה שיהי' נמצא שלא במקומו זהו בתגבורת כח כו', והחילוק הוא שבמקומו הוא בהתגלות ושלא במקומו אינו בהתגלות כו', וגם בזה יש חילוקים שבמקום זה הוא בהתגלות יותר ובמקום זה שאינו בהתגלות כ\"כ כו', דבכללות הוא דשלא במקומו אינו בהתגלות כמו במקומו רק שבזה גופא יש חילוקים אם שמתגלה יותר או שאינו מתגלה כ\"כ כו'. והדוגמא\nהוא למע' כבי' דכתי' ברוך כבוד הוי' ממקומו וכתי' כי הנה ה' יוצא ממקומו שיש בחי' מקומו העצמי שבבחי' התגלות העצמות כו', וזאת אין אנו יודעים מהו מקומו העצמי ואיך הוא התגלות העצמות כו' (ואפ\"ל שזהו כמו בידיעתו העצמי' שהכל הוא מקומו העצמי ובבחי' התגלות העצמות ממש כו', וצריכים לומר שזהו למע' גם מבחי' ידיעת עצמו כו'), וכמו שיוצא ממקומו כבי' בבחי' התגלות חוץ למקומו היינו בעולמות (שבידיעתן הן חוץ למקומו העצמי שז\"ע אין העולם מקומו כו') שיש בזה חילוק שמתגלה יותר או שאינו מתגלה כ\"כ כו', והו\"ע תו' האצי' ותו' הברי' כו', והכל הוא המשכת העצמות שנמשך ומתגלה בעולמות כו', דזהו ההתחדשות דמ\"ת להיות בחי' המשכת העצמות כו'. והענין הוא דהנה כל ענין התו' הוא להיות המשכת אור האצי' ממש בבי\"ע שגם למטה יהי' המשכת אור האצי' ממש כו', ולא כמו בס' השתל' ע\"פ מא' קו המדה שאין אור האצי' מאיר בבי\"ע והיינו דאור הקו שזהו בחי' ש' מ\"ה דאיהו אורח האצי' כו' אינו מאיר כלל בבי\"ע כו', שהרי יש פרסא המפסקת בין אצי' לברי' ומה שמאיר בברי'\nהוא אור של תולדה לבד כו', וגם לא כמו ההמשכה של האבות שהוא להיות גילוי אור האצי' כו', ה\"ז רק כמו שאצי'"],[3601330487,"הוא בחי' הפרשת הארה לבד כו', אבל ענין התו' היא להיות גילוי אור האצי' ממש בבי\"ע כו', והיינו בחי' פנימיות האצי' שנת\"ל פקל\"ז. וע\"ה שג\"ז בא בס' והדרגה באופן הגילוי וכנ\"ל בענין ועל תורתך שלמדתנו, דתורתך היא תורת האצי' ושלמדתנו הוא תו' הברי' כו', ומ\"מ גם בתו' שלמטה נמשך מהות אור האצי' ממש כו', דכשם שפרטי חלקי התו' מקרא משנה ותלמוד אי' בע\"ח דמקרא חב\"ד דאצי' ומשנה חג\"ת ותלמוד נה\"י דאצי', ובפע\"ח דמקרא בעשי' ומשנה ביצי' ותלמוד בברי' כו', הרי המקרא שבעשי' הוא בחי' חב\"ד דאצי' (רק שמתגלה ממנה בחי' נה\"י לבד כו' וכמ\"ש במ\"א). וזהו הטעם מה שבמקרא יש קדושה יותר מבתושבע\"פ, וגם יש בזה גילוי אלקות יותר שהאלקות מאיר בגילוי כו', שזהו לפי שמקרא חב\"ד דאצי' ומשנה ותלמוד ברי' ויצי' כו' (וזהו דמקרא שוה לכל ישראל דגם מי שאין לו רק בחי' נפש דעשי' מ\"מ ה\"ה שייך למקרא ומברך נותן התורה כו', והיינו לפי שמקרא בחב\"ד דאצי' וירדה בעשי' כו', ומשנה ותלמוד הן דוקא לבעלי מוחין (ובפרטי' משנה היא פסק הלכה והו\"ע המדות ותלמוד פלפול\nבטעמי ההלכות כו'), כמו שהתלמוד בברי' כו'), ומ\"מ הרי הכל בחי' אצי' רק שירדו בבי\"ע כו'. וכמו\"כ כללות התו' היא באצי' וירידתה למטה הוא המשכת אור האצי' למטה כו', שז\"ע מ\"ש במד\"ר דפ' וארא הנ\"ל דבמ\"ת עמד ובטל הגזירה כו', ובפ' האזינו ובקהלת ע\"פ ידעתי כי כל אשר יעשה האלקים כו' (קהלת ג' י\"ד) אי' ברא הקב\"ה את העליונים לעליונים ואת התחתונים לתחתונים כו', בא משה ועשה את התחתונים לעליונים ואת העליונים לתחתונים שכך כתיב ומשה עלה אל האלקים, וירד ה' על ה\"ס, והיינו דבמ\"ת נתחדש זאת שיהי' גילוי האצי' למטה כו' דבמ\"ת הי' ממש גילוי אצי' למטה וכדאי' במכילתא ע\"פ וירד ה' על הר סיני הרכין הקב\"ה השמים ושמי השמים העליונים והציען על ההר, דשמים הו\"ע בחי' אצי', ושמי השמים זהו בחי' אוא\"ס שלמע' מאצי' כו', שהי' במ\"ת בגילוי ממש למטה כו', וכ\"ה בכללות ענין התו' שזהו המשכת עצמות אצי' ממש למטה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והמדידה דתורה היא בחי' גבו', והוא תגבורת כח להיות המשכת העצמות, וגם שההמשכה היא כבי' לא במקומו העצמי, הנה ה' יוצא ממקומו, מקומו העצמי היא בידיעתו העצמית, חוץ למקומו העצמי, הוא בידיעת הנמצאים, וכל תגבורת בא בהתחלקות, והכל הוא העצמית, וזהו ג\"כ פרטי המצות, ומה שיש תורת האצי' ותורת הברי' זהו באופן ההתגלות, ומ\"מ בכ\"מ הוא המשכת העצמית, דז\"ע התורה להיות עצמיות האצי' בבחי' המשכה והתגלות, וזהו מקרא חב\"ד דאצי' וירד בעשי' והגילוי הוא בבחי' נה\"י, וגם משנה ותלמוד הוא מאצי', וזהו כללות מ\"ת המשכת אצי' בבי\"ע.</span>\nקס) <b>וביאור</b> הענין הוא, דהנה ידוע דהע\"ס דאצי' הן בחי' ממוצע בין אוא\"ס המאציל אל הנבראים כו', דכל התהוות וכל השפעה בעולמות הכל הוא מאוא\"ס ב\"ה והוא ע\"י אמצעות האצי' כו'. ולכאורה א\"מ הלא הנבראים הן באין ערוך לגבי אוא\"ס שאין להם שום ערך ויחוס כלל וא\"כ איך שייך ממוצע ביניהם, דענין האמצעית שייך בב' דברים שהן במהות א' רק שזה למעלה הרבה מזה, בזה שייך ענין הממוצע שע\"י יכול להיות ההשפעה מהעליון אל התחתון,"],[3601330488,"והו\"ע ירידת ההשפעה ממדריגתה כמו שהיא בהעליון שנתמעט בזה האור וגם באה בהתלבשות עד שנעשית לפ\"ע התחתון כו'. וכמו עד\"מ בהשפעת השכל מהרב אל התלמיד דהשכל כמו שהוא אצל הרב גם שהוא מדוד כבר לפי אופן המקבל, ה\"ה למע' עדיין מהמקבל לפי שמאיר בזה בחי' העומק והפנימי' ע\"כ אינו בערך המקבל עדיין כו', וע\"י האמצעות שבזה דהיינו שנתמעט האור דהעומק והפנימי' מתעלם כו', וגם בא בהתלבשות בענינים שבערך המקבל כו', עי\"ז יוכל להתקבל אל המקבל כו'. דכ\"ז הוא במשפיע ומקבל שהן בערך זל\"ז כו', אבל בדברים המובדלים לגמרי בעצם מהותם שבאין ערוך כלל מה שייך ממוצע בזה כו', וכמו שאינו שייך שום ממוצע בין בבע\"ג למה שהוא בגבול כיון שלגבי בבע\"ג שוה הגבול היותר קטן עם הגבול היותר גדול א\"כ אין שום אמצעי ביניהם אלא או גבול או בבע\"ג כו'. אך הענין הוא דהנה נת\"ל באורך איך שיש ב' מיני המשכות מאוא\"ס, הא' הוא בבחי' א\"ס ממש, והב' בבחי' גבול ומדה כו', והבחי' הא' היא בחי' רצה\"ע שבא בבחי' מקיף לכל העולמות בשוה כו', ובחי' הב' הוא הקו הנמשך מאוא\"ס\nשבא בבחי' מדה וגבול לפ\"ע העולמות ובא בבחי' התלבשות והתחלקות בע\"ס דאצי' כו', וגם בשרשו ומקורו של הקו כמו שהוא לפה\"צ יש בו ע\"ס והן ע\"ס הגנוזות במאצילן כו', רק ששם הם בתה\"פ והאחדות כו', ולאחר הצמצום באים בבחי' התחלקות והעיקר בהתלבשותם בהכלים כו'. ומב' בחי' אלו הן ב' מיני המשכות והשפעות בעולם, הא' בבחי' ארך אפים ורב חסד שלמע' מהצמצום כו', וכמארז\"ל כמה א\"א לפניו שכל הדורות היו מכעיסין כו' שזה שגם המכעיסים מקבלים שפע וחיות בעוה\"ז מקדושתו ית', זהו מבחי' א\"א ורב חסד כו', וכמארז\"ל (פסחים דקי\"ח ע\"א) הני כ\"ו כל\"ח שאמר דוד כנגד מי, כנגד כ\"ו דורות שברא הקב\"ה בעולמו ולא נתן להם תורה וזן אותם בחסדו כו', והיינו מבחי' רב חסד דא\"א ששם כחשיכה כאורה שאינו תופס מקום כלל וכמ\"ש אם חטאת מה תפעל כו' (והיינו בבחי' חיצוני' המקיף, משא\"כ בפנימי' המקיף שם הכוונה שיהי' קיום התו\"מ דוקא כו' וכמ\"ש במ\"א). וז\"ע שני אלפים תהו שהי' ההמשכה בבחי' ריבוי האור שזהו מבחי' החסד כו' (ובאמת הרי ריבוי האור אינו לטובה אמיתי' שה\"ז הי'\nסיבת השבירה כו', ומבו' במ\"א דהכוונה בבנין התהו שהי' ע\"מ לסתור זהו בכדי להפריד הסיגים והפסולת שנעשו ע\"י הצמצום כו', וכנודע דהצמצום הוא בחי' גבו' דש' אלקים, והגבו' הן סיבת הסיגים כו', ובכדי להפרידן בשביל זה הי' בנין התהו והי' בבחי' ריבוי אור ונשברו כו', וכן בסוף כל ההשתל' בריבוי ההשפעה לעוברי רצונו הוא כמ\"ש ומשלם לשונאיו כו' להאבידו כו'). ואח\"כ שני אלפים תו' דאורייתא מחכ' נפקת וחכ' יש בה קצת דין כמ\"ש החייט, והוא המדידה וההגבלה להיות ההמשכה במקום הראוי דוקא כו', ובד\"כ הוא בחי' התיקון להיות בבחי' מיעוט האור וריבוי הכלים והיינו שיהיו כלים לקבל את האור, וכפי אופן הכלי הוא המשכת האור כו' (ומ\"מ הרי התו' נק' תו' חסד לפי שהיא גילוי או\"פ שזהו בחי' גילוי ממש כו', וגם בחי' הגבו' דתו' תכליתן חסד, וכמ\"ש בלק\"ת ד\"ה החלצו ההפרש בין הגבו' שקודם מ\"ת להגבו' דתו' כו'), ובכללות זהו הקו הנמשך מאוא\"ס שהוא ההמשכה שבבחי' מדה וגבול כו'. והנה ע\"ה שהקו בא בבחי' מדה וגבול ה\"ה הארה ממש מא\"ס ב\"ה שהאור מעין המאור רק\nשזהו מה שא\"ס מאיר בבחי' גבול ומדה כו', וע\"ד מ\"ש העה\"ק בענין הכלים דע\"ס שזהו משלמות הא\"ס שכשם שיש לו כח בבבע\"ג כן יש"],[3601330489,"לו כח בגבול כו', כמו\"כ הוא בבחי' הקו שזהו מה שיש בא\"ס ג\"ז הכח שיהי' מאיר בגבול ומדה כו'. ויובן ביותר עפמשנת\"ל פט\"ז דהגבול דאורות אינו בחי' כח הגבול שבא\"ס שה\"ה ש' הוי' כו' (דכח הגבול הן השמות דאל אלקים כו'), והוא מה שהאוא\"ס הבל\"ג שיער בעצמו להאיר בבחי' מדה וגבול כו', וה\"ה בבחי' דבקות במקורו דזהו מה שהוא בבחי' אור, דכל אור אא\"ל כ\"א בבחי' דבקות כו' כנודע, וא\"כ מאחר שהוא בחי' אור ה\"ה בבחי' דבקות במקורו ומעין מקורו שגם הוא בבחי' א\"ס והו\"ע הכנף מין כנף כו', דהציצית הן בחי' או\"פ ומ\"מ ה\"ה מין כנף כו'. ובפרט לפמשנת\"ל פכ\"ח דבהאו\"פ יש בו בחי' הרושם מהאוא\"ס הבל\"ג כו', דנת' שם שיש ב' מיני צמצום, דבבחי' האור שלהאיר במדה וגבול (והיינו בשרש ומקור האו\"פ כו') הי' הצמצום בבחי' מיעוט לבד כו', ובהאוא\"ס הבל\"ג הי' הצמצום בבחי' סילוק כו', דבבחי' סילוק האור נשאר רשימו מהאוא\"ס הבל\"ג בהאור שלהאיר במדה וגבול כו'. וזהו סבת ב' הענינים הפכים שבהקו שהוא בבחי' קו המדה וגם פועל ההתכללות דאנת הוא דקשיר לון כו', דבמ\"א\nמבו' שזהו לפי שהקו בעצם הוא בחי' האוא\"ס הבל\"ג רק שנמשך ע\"י הצמצום שעושה בו הגבלה כו', ועי\"ז הוא שיש בו ב' הענינים הנ\"ל. ולפי המבו' כאן דגם בשרשו הוא להאיר בבחי' מדה וגבול כו', א\"כ איך יש בו ב' הענינים הפכים הנ\"ל, רק שזהו ע\"י הרושם מאוא\"ס הבל\"ג שבקו כו', ולהיות שהקו הוא משוער מהאוא\"ס הבל\"ג וגם יש בו רושם מהאוא\"ס כו', והוא בבחי' מדה וגבול כו', ע\"כ הוא בבחי' ממוצע בין אוא\"ס אל העולמות. דבכדי שיהי' התהוות א\"ק מאוא\"ס שנק' אדם דברי' דכללות זהו ע\"י הקו הנמשך מאוא\"ס, שזהו ההמשכה שבבחי' מדה וגבול וה\"ה הארה ממש מאוא\"ס ב\"ה, שזהו מה שאוא\"ס שיער בעצמו להאיר במדה וגבול, דזה שהוא משוער מאוא\"ס הבל\"ג וגם יש בו רושם הא\"ס כו', הרי מצד זה יש בו התדמות אל האוא\"ס הבל\"ג כו', ומה שהוא בבחי' מדה וגבול ה\"ה בבחי' התדמות אל בחי' א\"ק כו', וע\"כ הקו הוא בבחי' ממוצע להיות עי\"ז התהוות בחי' א\"ק כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וביאור הענין דהנה אצי' ממוצע בין אוא\"ס והעולמות, וצ\"ל הלא ממוצע יצדק בדברים שהן בערך זל\"ז כמו מומ\"ק, אבל איך יצדק בין גבול ובלי גבול. הענין הוא דהנה נת' שיש ב' המשכות בבחי' א\"ס ובבחי' מדה וגבול, וזהו כמה א\"א לפניו, והו\"ע ריבוי האור דתהו בחי' חסד (ועי\"ז הי' השבירה והכוונה בשביל הפרדת הפסולת), ותורה הו\"ע התיקון בבחי' מדה (ובעצם היא בחי' תורת חסד), והו\"ע הקו, והרי שרשו מאור הא\"ס, מין כנף, וגם יש בו רושם הא\"ס, ולכן הוא בחי' גבול ובלי גבול, וע\"כ הוא בחי' ממוצע שיהי' מאוא\"ס התהוות א\"ק.</span>\nקסא) <b>אך</b> הנה המדרי' שלפני האצי' הכל הוא בבחי' סתימות והעלם והכל בבחי' פשיטות בבחי' העדר מציאות דבר כו', אמנם כאשר בא באצי' ה\"ז שבא בגילוי דאצי' הוא הפרשת הארה מאוא\"ס כו', ובבחי' מציאות אור אור החכ' ואור הבינה אור החסד כו', ומ\"מ הרי אצי' הוא בחי' אור כו', דאור הוא בבחי' דבקות במקורו כו' כנ\"ל (ושרשו הוא מהע\"ס הגנוזות במאצילן שהן בבחי' פשיטות ואחדות כו', וגם בהקו הן בחי' ע\"ס בלי מ\"ה כו', וכמו\"כ הע\"ס דאצי' הן בבחי' פשיטות כו', וכנודע מ\"ש בע\"ח שאין הכלים נעשים אורות אלא מאצי' לבי\"ע אבל"],[3601330490,"לא למע' מאצי' כו', וע\"כ הן בבחי' פשיטות עדיין כו'), וא\"כ הרי גם הע\"ס דאצי' זהו מה שהאוא\"ס שיער בעצמו כו' וגם יש בזה רושם הא\"ס כו'. ונמצא יש בהם ב' הענינים, והיינו שיש בהם מבחי' אוא\"ס המאציל שה\"ז מה שהאוא\"ס שיער בעצמו להאיר בגבול היינו להיות בבחי' חכים ומבין וחסדן כו', והוא מין כנף ממש כו', דמשו\"ז האצי' הוא בבחי' דמיון וערך לאוא\"ס המאציל כו', וזהו שאצי' נק' אדם ל' אדמה לעליון בחי' אוא\"ס המאציל כו'. אמנם מה שהן בבחי' גבול ותכלית ע\"ה שזהו כח הא\"ס להאיר בבחי' מדה וגבול כו', אעפ\"כ כיון שזהו הארה שבבחי' גבול ותכלית, הנה הגם שהגבול ותכלית דע\"ס אינו בערך הגבול ותכלית דבי\"ע וגם לגבי בחי' היותר אחרונה שבאצי' אין ערוך כטפה לגבי ים אוקיינוס כו', מ\"מ כיון שנק' גבול ותכלית לגבי א\"ס הרי מצד זה הן מתדמין לבחי' בי\"ע כו', ולכן נק' האצי' ממוצע בין המאציל א\"ס ב\"ה לנבראים כו'. ובהע\"ס דאצי' גופא ב' מדרי' שבהממוצע זהו בחי' ח\"ע וח\"ת, דהרי נודע דעיקר גילוי הקו הוא בחכ', וחכ' היא בחי' כח מה היינו בבחי' בלי מהות\nומציאות דבר עדיין כו', וזהו שהחכ' היא בבחי' נקודה בבחי' העדר המציאות כו', וע\"כ השראת אוא\"ס ב\"ה הוא בחכ' דוקא והיינו ששורה שם בחי' הא\"ס הבל\"ג כו', וכמ\"ש במ\"א ועמשית\"ל פ'en., וע\"כ גם בחי' החכ' היא בבחי' בל\"ג עדיין. וכידוע בענין אור מים רקיע דחכ' הוא בחי' מים דניידי כו', וכמו נקודת ההשכלה שיכולים להסבירה בכמה אופנים שונים וגם יכולים להטותה עדיין לכל צד כו', דכמו שבאה בהשגה דבינה ה\"ז בבחי' רקיע דאגלידו מיא באופן כך וכך דוקא כו', אבל נקודת החכ' יכולים להטותה כו'. וכמו\"כ יובן בבחי' החכ' למע' שאינו בבחי' הגבלה עדיין לפי שאינו בבחי' מציאות דבר ושורה בה אוא\"ס ב\"ה כו', ופנימיות החכ' היא בחי' אור שאינו בבחי' מציאות כלל כו' וכמ\"ש בסי' בד\"ה הללו אל בקדשו. וח\"ת הוא בחי' מל' שזהו שרש ומקור בי\"ע שבאצי' כו', והמל' היא בבחי' יש ומציאות כו', וכמ\"ש במ\"א דכל ענין המלוכה הוא בחי' התנשאות וישות כו', וזהו דדוד הי' בר נפלי דלא הוו לי' חיין כי הכלי לאוא\"ס הוא בחי' ביטול והעדר המציאות דוקא, והמל' להיותה בבחי' יש\nומציאות א\"ז כלי לאוא\"ס ב\"ה, ורק אדה\"ר נתן לו ע' שנין, דאדה\"ר הוא בחי' ח\"ע והחכ' להיותה בבחי' העדר המציאות ה\"ה כלי לאוא\"ס ב\"ה כו' כנ\"ל. וע\"כ זהו ב' המדרי' שבהממוצע, דח\"ע זהו המדרי' שמצד אוא\"ס ב\"ה, וח\"ת היא המדרי' שמצד הנבראים כו'. ובפרטיות ב' המדרי' שבהממוצע הן בחי' אורות וכלים דע\"ס (עמשנת\"ל פ\"ח), שהרי האור הוא בבחי' פשיטות עדיין, וכמו שנת\"ל דכללות האור ע\"ה שזהו האור בבחי' מדה וגבול, דגם בשרשו ומקורו הן בבחי' ע\"ס הגנוזות במאצילן, ה\"ה שם בבחי' פשיטות ובבחי' אחדות ממש כו', וגם בהקו שאחה\"צ שהקו עשוי מנקודות פרטי' כו', ה\"ה מ\"מ בבחי' בלי מה כו', עד שגם כמו שהאור בא באצי' הרי הע\"ס דאורות הן בבחי' פשיטות לגבי הע\"ס דכלים כו', הרי שהאור בד\"כ הוא בבחי' פשיטות עדיין כמו שמבחי' אוא\"ס המאציל כו', ובפרט מצד שיש בו מבחי' האוא\"ס ב\"ה דמשו\"ז הוא מעין המאור דבחי' אוא\"ס הבל\"ג כו'. ועיקר ענין המציאות דע\"ס בחי' חכ' וחסד הוא בהכלים דוקא כו', וגם הכלים דע\"ס ה\"ה אלקות ממש רק שזהו מבחי' כח הגבול שבא\"ס וכמ\"ש\nבעה\"ק, וע\"כ הן כלים להאור שיתלבש בתוכן לפי שהן אלקות כו'. וזהו ב' המדרי' שבהממוצע שהאור שהוא בבחי' פשיטות ה\"ז כמו מצ\"ע אוא\"ס הבל\"ג כו', והכלים שהן בבחי' גבול"],[3601330491,"ה\"ז בערך הנבראים כו', וע\"ה שהגבול שבנבראים הוא באין ערוך כלל לגבי הגבול שבאצי' כו', מ\"מ להיותו בבחי' גבול ה\"ז מגביל את האור להיות בערך ובגדר מקור לנבראים כו', וכמ\"ש באגה\"ק איהו וגרמוהי חד לברוא כו', שזהו ע\"י הכלים כו' (ובאגה\"ק שם הקשה איך הוא חד עם גרמוהי כו', וי\"ל הכוונה שם שהיחוד הוא רק הנוגע להתהוות לא שהן בבחי' יחוד ממש, כמו יחוד האור עם המאציל עליון שהוא בבחי' יחוד ממש להיותו בבחי' אור כו', והיחוד עם הכלים הוא שמתייחד עמהם רק לברוא בהם וע\"י כו' וכמשנת\"ל פקנ\"ה, וזה גופא הוא מפני שהכלי היא ג\"כ אלקות ממש כו', והאור הוא שבא במדה וגבול אם שע\"י הצמצום הוא בא ונמשך בבחי' גבול כו', או שכך הוא גם בשרשו ומקורו כו'). ובמ\"א מבואר שהכלים הם רק בבחי' כח המגביל והיינו שפועלים ההגבלה חוץ לאצי' כו', שההארה כשתומשך חוץ לאצילות תהי' בבחי' גבול כו' וכמ\"ש במ\"א (וכ\"ה בעה\"ק שהן רק כח הגבול כו', וכ\"מ בפרד\"ס, ובאגה\"ק כ' שהן גבול ותכלית כו' וכמ\"ש במ\"א). וע\"כ האצי' ע\"י שכלול מב' מדרי' אורות וכלים (דלמע'\nמאצי' לא יש עדיין כלים כ\"א באצי' דמשו\"ז נק' אדם דעשי' כמ\"ש במ\"א), עי\"ז הוא בבחי' ממוצע בין אוא\"ס אל הנבראים כו'. וענין האמצעי הוא בב' ענינים להיות התהוות הנבראים שזהו ע\"י אור האצי' דוקא (לפי שההתהוות צ\"ל דוקא מהאור הדבוק במקורו כו' וכמ\"ש באגה\"ק ובמ\"א), וגם בכדי להיות ידיעת אלקות בעולמות וכמ\"ש הפרד\"ס שע\"י האצי' יודעים הנבראים מאלקות גם מבחי' אוא\"ס שלמע' מאצי' כו', וכמשנת\"ל פ\"ו דבכדי שיהי' בנבראים ידיעת והשגת אלקות והרגישות אלקות (שז\"ע חו\"ב ומדות כו'), כ\"ז הוא ע\"י אמצעית אצי' כו', והיינו שע\"י שהאור דאצי' הוא בבחי' מדה וגבול לפ\"ע העולמות כו' (והיינו העולמות שלמע' מאצי' ועולם האצי' כו'), וע\"י הכלים שהן בבחי' גבול ותכלית בערך בי\"ע כו', הנה ע\"י הכלים נמשך הארה אלקי' גם בבי\"ע להיות עכ\"פ ידיעת והשגת אלקו' כו'. אך הידיעה שבבי\"ע היא בחי' ידיעת המציאות לבד להיות דמה שבא מאצי' לבי\"ע ע\"י אמצעית אצי' (ע\"פ מא' קו המדה כו') הוא בחי' אור של תולדה לבד כו', וע\"כ הידיעה היא רק בבחי' המציאות דאלקות וג\"ז לא\nבבחי' ידיעה ממש שנדע ממש את המציאות דאלקות כו', מפני שכל ידיעתנו באלקות הוא מהנבראים שנבראו (והיינו שמפעולותיו ית' אנו יודעים את אלקות כו'), ע\"כ כמה שנשלול את החומרי' והישות ונקשור עצמינו אל הדקות והרוחניות לא נדע מציאות אלקות ממש, רק אנו יודעים מציאות הרוחניות אבל לא מציאות אלקות כו', כ\"א נשמות הגבוהות ובפרט נשמות דאצי' יודעים מציאות אלקות כו', אבל סתם נשמות אינם יודעים גם את מציאות אלקות ממש כו', ומ\"מ ע\"י הידיעה במציאות הרוחני אנו יודעים ג\"כ מציאות אלקות לא בבחי' ידיעה ממש כ\"א בבחי' השערה עכ\"פ כו', וע\"י תומ\"צ הרי יש גילוי אלקות ממש כו', וכללות ידיעת הנבראים באלקות זהו ע\"י אמצעית האצי' כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש וידבר משה אל ראשי המטות כו', דהנה ההפרש בין שבטים למטות, דשבטים הן ענפים המתפשטים מן האילן דע\"ה שאינם גוף האילן ה\"ה מסתעפים ומתפשטים מגופו של אילן ויונקים ממנו כו', והמטה הוא שנתקשה ונעשה דבר בפ\"ע ואינו יונק מן האילן כו'. והדוגמא מזה ברוחניות דהנה האבות הן המרכבה בחי' חג\"ת דאצי' והן בחי' מרכבתא עילאה שזהו גופא דאילנא כו'."],[3601330492,"<b>והשבטים</b> זהו בחי' הארת אצי' שנמשך בבי\"ע דזהו בחי' מרכבתא תתאה כו', כי הארת אצי' בהתחברותה עם הברי' שברי' נעשה בבחי' ביטול ה\"ז בחי' מרכבתא תתאה כו', דכללות ענין המרכבה הו\"ע הביטול כו', וזהו לפי שיונקים מגופא דאילנא כו', ובד\"כ זהו בעובדי ה' בנשמתן שאינם נתפסים בגשם ויודעים ומשיגים אלקות ודבוקים במקורם כו', אבל מטות הן נשמות דבי\"ע שהאלקות בא בהם בהגשמה דלהיותם נתפסים בגשם ע\"כ ההשגה שלהם והתעוררות אהוי\"ר שלהם הכל הוא בהגשמה כו', וזהו מפני שהם נפרדים ממקורם שאינם יונקים מגופא דאילנא כו'. ובנשמות אלו שייך ענין הנדרים כו', דהנה נדרים הו\"ע הפרישות וכמא' נדרים סייג לפרישות כו', והיינו כאשר רואה דבר שא\"א לתקנו ואדרבה יכול להורידו ח\"ו ה\"ה פורש א\"ע מזה כו'. וזה שייך בנשמות דבי\"ע דבכדי לפעול הכנעת החומר בכלל הוא ע\"י הסיגופים ומכ\"ש בכדי שיהי' איזה עבודה היינו שישיג ענין אלקי ויונח אצלו כו', צ\"ל לזה הזהירות ביותר מהמותרות כ\"א רק המוכרח לו וג\"ז יהי' לש\"ש כו', ובפרט מהמותרות שיכול להוריד צריך להזהר מאד\nכו', דכ\"ז הוא ע\"י אמצעית אצי' שנעשה מציאות היש ע\"כ צ\"ל ענין הנדרים כו'. אך עיקר הכוונה הוא התרת הנדר שזהו מצד החכ' דחכם מתיר כו', דהנה נדרים הם מבינה וכמא' נודר בחיי המלך שזהו בינה כו', להיות דבינה הוא מקור ההשתל' להיות המדות בבחי' מציאות דבר, וכמו\"כ נעשה מזה מציאות יש בבי\"ע דמשו\"ז צריכים לנדרים כו', אבל חכ' שזהו בחי' גילוי אור ובחי' ביטול כו' עי\"ז יהי' התרת הנדר והו\"ע אתהפכא חשול\"נ כו'. וזהו וידבר משה אל ראשי המטות דלהיות דהתרת נדרים הוא מחכמה ע\"כ וידבר משה שהוא בחי' חכמה בחי' מה כו'. ואומרו כאן מטות לפי שכל ענין הנדרים הוא בנשמות דבי\"ע שנק' מטות כו', אך עיקר הכוונה הוא התרת הנדר דוקא כו', וזהו וידבר משה שהוא ההמשכה מבחי' חכ', דבההמשכה שמבחי' החכ' נמשך הגילוי גם בבי\"ע כמו בהמשכת האבות וכ\"ש במשה ע\"י התו' כו'. וענין ראשי המטות הוא כי במטות יש עוד ענין והוא בחי' שכל המטה כלפי חסד כו', שזהו מדות שבחכ' כו' כמשנת\"ל, ונק' זה ראשי המטות דהיינו מה שחכ' הוא ראשית ההשתל' כו', וזהו ג\"כ ענין זה\nהדבר דזה הוא בחי' גילוי המהות משה נתנבא בזה כו', ולהיות דהכוונה הוא דוקא בהתרת הנדר שמחכ' ע\"כ מקדים לאמר זה הדבר כו', ועוד דהנה וידבר משה אל ראשי המטות זהו ההמשכה במדות וזה הדבר הוא ההמשכה במל' שנק' דבר כו'. וזהו וידבר כו' דכללות ענין הנדרים שייך בנשמות דבי\"ע כו', אך עיקר הכוונה הוא להיות התרת הנדר מבחי' חכ' כו', וזהו וידבר משה אל ראשי המטות המשכה מבחי' חכ' במדות להיות בבחי' שכל המטה כו', בחי' מדות שבחכ' כו', זה הדבר הוא ההמשכה במל' כו', ועי\"ז הוא הגילוי בבי\"ע להיות התרת הנדר שהו\"ע אתהפכא חשול\"נ כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולמעלה מאצי' הכל בבחי' פשיטות והעלם, ובאצי' בא בבחי' גילוי, דהאור הוא מעין העצם, ויש בו רושם הא\"ס, ולכן הוא בבחי' פשיטות לגבי הכלים, וזהו אדם אדמה לעליון, ומ\"מ הוא להאיר במדה וגבול, וזהו ב' מדרי' שבהממוצע, ובע\"ס חכ' היא בחי' מ\"ה ושורה בה אוא\"ס, ולכן חכ' אינו בהגבלה, מיא ניידי, ופנימיות החכ' בחי' אור, וח\"ת בחי' יש ומציאות, ובד\"כ ב' המדרי' שבממוצע דאצי' הוא בחי' האור שהוא בחי' פשיטות ובל\"ג, והכלים בחי' גבול,</span>"],[3601330493,"<b>ובמ\"א</b> שזהו להגביל חוץ לאצי', והאמצעי הוא שיהי' התהוות וגם הגילוי בעולמות עכ\"פ בבחי' ידיעת המציאות, וע\"י התורה גילוי אלקות ממש. וזהו ראשי המטות, שבט הארת אצי', ומטה נשמות דבי\"ע, וצריכים לנדרים, והתרת הנדר מחכ'."],[3601330494,"<h3>בס\"ד. ש\"פ מסעי, תער\"ג</h3>\n<b>אלה</b> מסעי בני ישראל אשר יצאו מארץ מצרים כו', ויכתוב משה את מוצאיהם למסעיהם, ואלה מסעיהם למוצאיהם, וצ\"ל מהו\"ע מוצאיהם למסעיהם, והול\"ל ויכתוב משה את מסעיהם מהו מוצאיהם למסעיהם, ומהו עוד ואלה מסעיהם למוצאיהם כו'. גם צ\"ל אומרו ויכתוב משה הלא כל התורה הקב\"ה אומר ומשה כותב מהו אומרו כאן ויכתוב משה כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דאצי' הוא ממוצע בין אוא\"ס המאציל אל הנבראים דבכדי שיהי' התהוות הנבראים מאוא\"ס זהו ע\"י התהוות האצי' כו', דלכאורה א\"מ איך שייך ממוצע בב' דברים נבדלים שאינם בערך כלל כו', וכמו שאינו שייך ממוצע בין בל\"ג וגבול כו'. נת' ע\"ז שהממוצע הוא הקו הנמשך מאוא\"ס שיש בו מבחי' בל\"ג ומבחי' הגבול שהרי הקו הוא המשכה שבבחי' מדה וגבול כו', ושרשו הוא מאוא\"ס הבל\"ג, והוא מה שהאוא\"ס הבל\"ג שיער בעצמו להאיר במדה וגבול הרי יש בו כח הא\"ס כו', ונמצא יש בו ב' הענינים דבחי' בל\"ג ובחי' גבול כו', ע\"כ הוא בבחי' ממוצע כו'. רק שהמדרי' שלפני האצי' הרי הכל בבחי' סתימות והעלם, ע\"כ עיקר הממוצע הוא אצי'\nשהוא בבחי' מציאות אור ומ\"מ הוא בבחי' אור הדבוק במקורו ע\"כ הוא בבחי' ממוצע כו', ובע\"ס דאצי' גופא ב' המדרי' הן בחי' ח\"ע וח\"ת או אורות וכלים כו'.\nקסב) <b>והנה</b> ידוע שהתורה היא ג\"כ בחי' ממוצע בין אוא\"ס לנבראים, דברי' והתהוות העולמות הוא ע\"י התו', וכמו\"כ ע\"י התורה הוא ההתחברות דאוא\"ס עם העולמות כו', וזהו מה שהתו' נק' דרך וכמ\"ש כי ישרים דרכי הוי' ואי' בזהר דאינון ארחין דאורייתא כו', וכמ\"ש ושמרו דרך ה' לעשות צדקה ומשפט כו', וכמו הדרך שבו הולכים ממקום למקום כו', כמו\"כ תורה היא הדרך שע\"י נעשה התחברות דאוא\"ס עם עולמות כו', והיינו שהתו' היא בבחי' ממוצע שע\"י הוא התהוות העולמות וכן גילוי אוא\"ס בעולמות הוא ע\"י התו' כו'. והענין דהנה אי' בזהר תרומה דקס\"א ע\"א קוב\"ה אסתכל באורייתא וברא עלמא בר נש דאשתדל באורייתא מקיים עלמא כו', ופי' קוב\"ה הוא בחי' עצמות אוא\"ס עצמות המאציל שמובדל בערך מהעולמות כו', ואסתכל באורייתא הוא שנתצמצם ע\"י התו' כו', דכשם שהע\"ס דאצי' הם מגבילים את האור להיות בבחי' מקור לעולמות בע\"ג כו' כנ\"ל, כמו\"כ התו' מגביל את האור כו'. דהנה אורייתא מחכ' נפקת שהחכ' היא בחי' או\"פ, וכמו עד\"מ בכחות הנפש הרי הכח שהוא בבחי' או\"פ ובבחי' התיישבות"],[3601330495,"העיקר הוא כח השכל כו' דהכחות שלמעלה מהשכל כמו כח הרצון ה\"ה בבחי' מקיף כו', וכן גם המדות בעצם הן בבחי' מקיף רק ע\"י המוחין נעשה בבחי' פנימי כו' (וכמ\"ש מזה לעיל פמ\"ז), וכמו\"כ הוא למעלה דעיקר או\"פ הוא בחי' החכ' כו', וקוב\"ה בחי' עצמות אוא\"ס שלמע' מהחכ' ע\"י דאסתכל באורייתא ה\"ה בא בבחי' הגבלה להיות בבחי' או\"פ כו'. והענין הוא כדאי' במד\"ר בראשית פ\"ד שאל את ר\"מ אפשר אותו דכתי' בי' את השמים ואת הארץ אני מלא הי' מדבר עם משה מבין שני בדי ארון, א\"ל הבא מראות גדולות, א\"ל ראה בבואה שלך ראה אותה גדולה, הבא מראות קטנות וראה בבואה שלך ראה אותה קטנה, א\"ל ומה אתה כו', הוי כשרוצה את השואה\"א אני מלא וכשהוא רוצה הי' מדבר עם משה כו', הרי שאותה המדרי' ממש דאת השמואה\"א אני מלא הי' מצמצם א\"ע בין שני בדי הארון כו', וכמובן ממשל המראות כו'. כי חכ' היא כלי לאוא\"ס ב\"ה דהשראת אוא\"ס הוא בבחי' ביטול דוקא, והחכ' היא בבחי' ביטול דהנחת עצמותו שזה עיקר הביטול, וכמ\"ש גבי משה ונחנו מה בלי מהות ומציאות דבר כו', וע\"כ היא כלי\nלהשראת אוא\"ס ב\"ה כו' (והוא כמ\"ש בזהר פ' בלק דקפ\"ז ע\"א ע\"פ החכם עיניו בראשו דשכינתא שרי' על רישי' כו', והיינו בבחי' החכ' שבו, וזהו החכם עיניו בראשו כו' וכמ\"ש הרמ\"ז שם), וזהו המבו' בכ\"ד דאוא\"ס שורה בחכ' כו'. ומה שנק' בש' השראה הוא שיכול להיות שיהי' שורה בה בבחי' העלם ג\"כ, דענין ההתלבשות הוא שמאיר בגילוי ממש, וכמו התלבשות אורות בכלים הוא שהאור מאיר בגילוי ממש בהכלי והיינו שבהכלי מושג האור כו' וכמ\"ש בסש\"ב פמ\"ח, משא\"כ ענין השראה הוא ששורה שם האור בהעלם כו' (רק שבהתלבשות האור הוא בבחי' צמצום ומיעוט ועי\"ז הוא בהתגלות כו', דזה שיהי' האור בגילוי בהכלי הוא ע\"י שהוא לפ\"ע הכלי שבהכרח שיהי' בזה בחי' מיעוט כו', ובכללות הוא בחי' הארה לבד כו', משא\"כ האור שבבחי' השראה הוא בחי' מהות האור כמו שהוא, ובזה יתרון גדול בהשראה לגבי התלבשות כו' (גם בהתלבשות יש אופן התלבשות שהוא בבחי' העלם לגמרי כמו ענין הגלות וכמ\"ש באגה\"ק סי' כ\"ה ד\"ה להבין אמ\"ב צוואת הריב\"ש ז\"ל, שזהו לא רק שהאור מתעלם כ\"א שיש דבר המעלים שמעלים\nומסתיר עליו כו', וכמ\"ש במ\"א בענין ההתלבשות שיש שהמלובש שולט וזהו במדרי' הקדושה שהמלובש הוא בהתגלות כו', ויש שהמלביש שולט כו', וב' מיני התלבשות אלו יש בהתלבשות הנה\"א בהנה\"ב, דכאשר הנה\"א הוא בהתגלות ה\"ה מושל ושולט על הנה\"ב וכל ההנהגה הוא ע\"י הנה\"א כו', וכאשר הנה\"ב הוא בהתגברות ה\"ה מושל ושולט על הנה\"א שגם הנה\"א נמשך אחריו, וכידוע בענין סרכות הריאה שהריאה נסרכת ונדבקת דהיינו שהארת נה\"א נמשך ונדבק אחר הנה\"ב כו'. ובהשראה לא יש ענין כזה כו'. וזהו ג\"כ מצד ההפרש הנ\"ל דלהיות שהתלבשות הוא בהאור שהוא בחי' הארה לבד ושבא בבחי' מיעוט כו', ע\"כ במדרי' תחתונות יכול להיות התלבשות כנ\"ל, וכמו ענין סרכות הריאה הרי שייך רק בנשמות נמוכות שהן בבחי' גסות הרוח שהרוחני' שלהם הוא בבחי' גסות כו' וכמ\"ש בלק\"ת ד\"ה להבין ענין מי אל כמוך. וכמו\"כ למע' התלבשות הנ\"ל שייך בההארה הבאה בבחי' מיעוט וצמצום ביותר במדרי' התחתונות כו', והשראה להיות שזהו בעצם האור כמו שהוא ע\"כ אינו שייך בזה התלבשות באופן הנ\"ל)). רק שהשראה הוא שיכול להיות שאינו מאיר בגילוי כו' כנ\"ל, ונר' שא\"ז שהאור הוא"],[3601330496,"בבחי' מקיף לבד כ\"א שנמצא בבחי' פנימי' רק שאינו בבחי' גילוי כו', ופי' וענין שאינו בבחי' גילוי אין זה שאינו מתגלה כלל שזהו כשלא יש כלי אל האור שאז אין האור מתגלה כלל כו', וכאן הרי אדרבה יש כלי אל האור והוא הביטול כו' (והיינו מה שהעדר הכלי הוא כלי כו'), אלא הכוונה בזה שאינו בבחי' גילוי היינו שאינו מתגלה ממש להיות מושג ממש כו', וכמ\"ש בסש\"ב פל\"ה בענין השראת השכינה דכאשר בטל במציאות אז הוא ששורה ומתגלה בו ה' אחד כו', הרי דהשראה הוא ג\"כ התגלות רק שאינו בהתגלות ממש בבחי' גילוי המהות כו', דמש\"א ששורה ומתגלה ה' אחד אין הכוונה שמתגלה בהם מהות הדבר ממש כו' (שהרי גם ע\"י המצות ההמשכה היא בבחי' מקיף כו' ועמ\"ש בפמ\"ו), כ\"א מה שיודעים ומרגישים את היחוד דה' אחד כו', שכ\"ה גם בנשמות הגבוהים השייכים ליחוד זה היינו שיודעים ומשיגים ונרגש בנפשם ענין ה' אחד כו', ומ\"מ א\"ז גילוי מהות הענין כו' (ובד\"כ צריכים לחלק בזה בין ראיית העין לראיית עין השכל כו', דהנה התגלות עצם מהות הדבר ממש הוא בראיית העין, וכמו שיהי' לעתיד\nדכתי' ונגלה כבוד ה' וראו כל בשר כו', משא\"כ בראיית עין השכל דבעין השכל דבלבא אתחזי כולא כו', הגם שזהו מדרי' גבוה ונעלה מאד א\"ז ראיית עצם המהות ממש כו', ולכן יש חילוקי מדרי' במדרי' הראי' שזהו מפני שא\"ז עצם המהות ממש כו' וכמ\"ש במ\"א, ולע\"ל שיהי' בחי' ראיית העין וכמ\"ש כי עין בעין יראו כו' כתיב כי כולם ידעו אותי בלי התחלקות מדרי' כו', וי\"ל דלעתיד יהי' באמת בבחי' התלבשות ממש דהיינו שעצם המהות יהי' בבחי' גילוי ממש בבחי' השגת המהות כו').\n<span data-k=\"ks\"><b>קיצור.</b> והנה התורה היא ממוצע בין אוא\"ס ועולמות, קוב\"ה אסתכל באורייתא, קוב\"ה עצמות המאציל, ומתלבש בתו' בבחי' פנימי, וכמו החכ' שהוא או\"פ, ולהיות החכ' בבחי' ביטול אוא\"ס שורה בחכ', וענין השראה הוא שאינו מושג מהות האור, התלבשות הוא שמושג בהכלי, רק שזהו הארה ובבחי' מיעוט, והשראה הוא שעצם האור שורה שם, ולכן בהתלבשות יש אופן שהמלביש שולט משא\"כ בהשראה, והוא שבא בבחי' או\"פ רק שאין המהות מושג, וכמו גילוי ה' אחד גם בנשמות הגבוהות, וי\"ל שזהו בבחי' ראיית עין השכל, וגילוי המהות הוא ראיית העין, כי עין בעין יראו.</span>\nקסג) <b>והענין</b> הוא כמו שמצינו במרע\"ה שהי' בחי' יסו\"א שאמר ונחנו מה שהי' בבחי' הביטול דמ\"ה דחכ', ואעפ\"כ א\"ל א\"ס ב\"ה וראית את אחורי ופני לא יראו, שלא השיג בחי' פנימי' החכ' בחי' אוא\"ס השורה בכלי החכ' שלו כו' (וי\"ל דזהו שא' רשב\"י לרע\"מ בעין השכל דבלבך אתחזי כולא דבחי' אוא\"ס השורה בחכ' הי' בו בבחי' ראיית עין השכל, ולעתיד יהי' בבחי' ראיית העין ממש כו'), והיינו דע\"ה דאוא\"ס שורה בחכ' עכ\"ז יכול להיות שאינו מתגלה בחכ' רק בחי' אחורים ולא בחי' פנים כו', אע\"פ שגם בחי' הפנים שורה בו כי פנימי' אבא פנימי' עתיק מ\"מ אינו מתגלה בו רק בחי' אחורים וחיצוני' כו', וכמו עד\"מ במוח האדם מלובש הנשמה ושורה שם כמ\"ש בסש\"ב פנ\"א דעיקר משכנה והשראתה כו', הוא כולו במוחין שבראש כו', אעפ\"כ אין אדם משיג מהות הנשמה איך ומה היא אע\"פ שהיא שורה בו, ואינו משיג רק הארה ממנה היינו השכל והמח'"],[3601330497,"שזה מושג המהות, היינו שאנו משיגים מהות הכח ולא רק שאנו יודעים מציאותו, כמו כח המשכיל מקור השכל שאנו רק מרגישים מציאותו לבד, משא\"כ כח השכל הגלוי הרי אנו יודעים מהותו איך ומה הוא (רק שכללות ידיעה האנושית היא רק ידיעת המציאות לבד שאין אנו משיגים מהות הרוחני, אבל הידיעה במציאות השכל אינו רק שאנו יודעים שישנו במציאות כ\"א שאנו יודעים איך הוא מציאותו בבחי' השגה ממש, משא\"כ במקור השכל כו' וכמ\"ש במ\"א, ולמע' הו\"ע השגת המהות ממש כו'), אבל כללות הנשמה השורה במוח שבראש הרי אינו מושג אף שהיא שורה שם כו'. ועד\"ז הוא בהבדל הבדלות לאין קץ שגם בחי' הח\"ע ע\"ה שאוא\"ס מלובש בה דאפי' פנימי' עת\"י הוא פנימי' אבא, מ\"מ אינו מתגלה המהות בבחי' חכ' רק מבחי' חיצוני' לבד, וכנודע דאבא יונק ממזלא בחי' שערות דא\"א לבד שנק' בשם אחורי כו', והיינו דבבחי' חיצוני' החכ' מה שבא בזה בבחי' התלבשות ובבחי' גילוי ממש הוא מבחי' חיצוני' הכתר, ובחי' פנימי' הכתר הוא בבחי' השראה לבד שאינו מושג המהות כו', וז\"ע אבא יונק ממזלא דהיינו מבחי'\nפנימית הכתר. וכמ\"ש במ\"א ההפרש בין מה שאו\"א מלבישים לזרועות דא\"א ומה שאו\"א יונק ממזלא, דמבחי' ז\"ת דא\"א בא בבחי' התלבשות ממש באו\"א, והמזלות שהן מבחי' מו\"ס שבו מלובש בחי' עתיק ההמשכה משם באו\"א הוא בבחי' שערות ובבחי' יניקה לבד כו', ועמ\"ש בלקו\"ת בהבי' דוהניף. וי\"ל שזהו כמו בנגלה דתו' שמושג המהות ממש, משא\"כ בפנימי' התו' שמושג רק המציאות לבד וכמ\"ש בהבי' דולא תשבית, ועד\"ז הוא בבחי' חכ' דבחי' הפנימי' הוא בבחי' ידיעת המציאות לבד, וזהו ופני לא יראו כו' בבחי' ראיית המהות כו', וז\"ע השראה כו'. ובפי' הספד\"צ מהאריז\"ל אי' משל הנ\"ל על בחי' רדל\"א כבי' כאדם שאינו משיג מהות הנשמה שבו, כך בחי' רדל\"א אינו משיג מהות עצמות אוא\"ס המלובש בו (שזהו עיקר בחי' עתיק וכמ\"ש בהבי' דשבת שבתון בסופו), ובסי' בפי' ברוך שאמר מבו' פי' לא ידע שאינו בבחי' מהות ידוע בעצמו כו' (ובדרוש וככה ספכ\"ג שאינו בבחי' הרגש כלל), וי\"ל שזהו ג\"כ ענין השראה כו'. ולפ\"ז י\"ל דמ\"ש על לעתיד כי כולם ידעו אותי בבחי' ידיעה והשגה כו', יהי' ההתחדשות בכל\nהמדרי' גם בבחי' לא ידע כו', ולא יהי' התחדשות בעצם הדבר כ\"א מה שיהי' בבחי' ידיעה כו'. אמנם בחי' חיצוניות האור שהוא בבחי' התלבשות בחכ' היינו בבחי' גילוי, הנה בחכ' דמע\"ב ה\"ז בחי' הארה לבד מבחי' הפנימי' והעצמות כו', ובחכ' דתו' ה\"ז ג\"כ מהות בחי' העצמות, וכמ\"ש במ\"א בענין יערוף כמטר לקחי דבחי' אחורים ועורף דתו' ה\"ז בבחי' לקחי דאותי אתם לוקחים כו' וכמשי\"ת, ולהיות דהחכ' הוא בחי' או\"פ והיינו דע\"ה שהיא בחי' ביטול במציאות מ\"מ ה\"ז בבחי' ידיעה, והוא מה שע\"י הידיעה וההרגש פנימי נעשה בחי' הביטול במציאות כו' (ועמשנת\"ל פל\"ח). וי\"ל שז\"ע זה אלי ואנוהו, דפי' זה אלי הוא בחי' ידיעה שיודע את האלקות וכמו אשר יאמר עליו כי הוא זה דהיינו בבחי' ידיעה דוקא (כמדומה שכן פי' השל\"ה), ועי\"ז דוקא ואנוהו אני והוא בבחי' אחדות ממש כו' (ובמ\"א מבו' ענין אני והוא שהן ב' מדרי' שבכתר דאני אותיות אין זהו בחי' אין דכתר שבבחי' מקור לנאצלים כמו והחכ' מאין תמצא כו', והוא זהו בחי' עליונה שבכתר כו', ובאוא\"ס שלפה\"צ הו\"ע הוא ושמו דהוא זהו\nבחי' עצם האור שלמע' מבחי' התפשטות כו', ושמו הוא בחי' התפשטות האור כו' וכמ\"ש במ\"א, והיינו מה שבחכ' יש גם מבחי' פנימי' הכתר כו'. וי\"ל שזהו ע\"ד"],[3601330498,"ענין ידיעת ההפלאה דאוא\"ס כו', וידוע שיש בזה ב' ענינים ידיעת ענין ההפלאה וידיעת אופן ההפלאה כו', וכ\"ז אינו גילוי המהות ממש כו'. ועד\"ז י\"ל בבחי' החכ' בענין הידיעה גם בבחי' פנימי' הכתר כו'). וזהו דאופן הביטול שמבחי' חכ' הוא שהוא בבחי' ציור, לא כמו הביטול שמצד המקיף שמתבטל ממציאותו לגמרי מכל וכל כו', משא\"כ בהביטול דחכ' הגם שבטל במציאות לגמרי מ\"מ ה\"ה באיזה ציור כו', והיינו מצד שהביטול הוא ע\"י הידיעה והרגש פנימי כו', וכמו משה שהי' בבחי' ביטול במציאות ודיבר ה' אל משה פא\"פ כו', ומ\"מ הי' על עמדו גם בעת הנבואה כו', וזהו לפי שהי' בחי' חכ' כמ\"ש מן המים משיתיהו שהו\"ע ידיעה פנימי', וע\"כ בכל הגילוים שלו ובכל העליות הי' בבחי' ציור ע\"ה בבחי' העדר המציאות לגמרי כו' (והו\"ע מוח שליט על הלב גם על פנימי' הלב, התגברות בחי' גדלות המוחין להיות בבחי' התיישבות ובבחי' ציור, הגם שבאמת הוא לא בבחי' מציאות כלל כו'). (וי\"ל שזהו מ\"ש בסש\"ב פי\"ט בענין הביטול דכח החכ' שבנפש הגם שתהי' אין ואפס ותתבטל שם במציאות לגמרי ולא\nישאר ממנה מאומה ממהותה ומציאותה הראשון כו', דקדק לומר ממהותה ומציאותה הראשון לא שתהי' בבחי' העדר המציאות לגמרי כו', ואעפ\"כ תתבטל שם במציאות לגמרי כו'), וע\"כ להיות שהחכ' היא בבחי' ידיעה לכן בה וע\"י בא האור בבחי' הגבלה להיות בבחי' או\"פ בעולמות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכמו במשה שהי' בחי' חכ' כתי' ופני לא יראו, וכמו הנשמה דמשכנה והשראתה הוא במוח שבראש, ואינו מושג מהותה כלל, וזהו דאבא יונק ממזלא הנמשכים מפנימיות הכתר בבחי' יניקה בלבד, וי\"ל כמו פנימיות התורה שהיא בבחי' ידיעת המציאות לבד, ובפי' ספ\"ד דרדל\"א אינו משיג מהות העצמות שבתוכו, ולפ\"ז לעתיד יהי' התחדשות הידיעה בכל המדרי', ובחי' חיצוניות האור בחכ' הוא בחי' הארה, ובחכ' דתורה בחי' מהות העצמית, ולהיות שחכ' היא או\"פ ידיעה פנימיות זה אלי ועי\"ז אני והוא (ובמ\"א שהן ב' מדרי' שבכתר, והוא הוא בחי' פנימיות הכתר, וז\"ע הוא ושמו והיינו בחי' הפנימיות ששורה בחכ') ולכן הביטול דחכ' הוא בבחי' ציור, וכמו משה שהי' על עמדו (וי\"ל דז\"ש בסש\"ב ממהו\"ע הראשון), וע\"כ החכ' מגביל את האור.</span>\nקסד) <b>אמנם</b> בחי' חכ' דתו' היא בחי' החכ' שלמע' מאצי' והיא ממוצע להיות התהוות הנאצלים מאוא\"ס ב\"ה. דהנה אי' בע\"ח שער ס' אבי\"ע פ\"ג דמ\"ש כולם בחכ' עשית זהו בחי' החכ' שלמע' מאצי' והיינו בחי' חכ' דא\"ק כו', דאוא\"ס ע\"י התלבשותו בחכמה דא\"ק הוא מתלבש באצי' כו', וזהו בחי' החכ' דתו', דגבי תו' נא' כאשר יאמר משל הקדמוני שהוא משל לא\"ס קדמונו ש\"ע ומשל הוא לבוש כנודע, והיינו בחי' חכ' דא\"ק שהיא בחי' לבוש להאוא\"ס המלובש בא\"ק וזהו בחי' חכ' דתו' כו'. והענין דהנה ידוע דא\"ק הוא בחי' ממוצע בין אוא\"ס המאציל אל הנאצלים והנבראים כו', והיינו להיות דאוא\"ס הוא אינו בערך העולמות כלל כו', ובכדי שיתהוו העולמות מאוא\"ס צ\"ל ממוצע, וזהו בחי' א\"ק שהוא ממוצע בין אוא\"ס לעולמות כו'. וצ\"ל איך א\"ק הוא בבחי' ממוצע שהרי גם א\"ק הוא באין ערוך לגבי אוא\"ס ונק' אדם דברי' דכללות כו' כנודע. ולעיל פק\"ס וקס\"א נת' שהממוצע הוא האור הנמשך מאוא\"ס (הן בחי' הקו והן האור דאצי'"],[3601330499,"כו') שיש בו ב' ענינים שבא בבחי' גבול ומדה והוא בבחי' א\"ס להיותו דבוק במקורו כו', אבל בבחי' א\"ק לא יתכן לומר כן שה\"ה בבחי' פרצוף וברי' דבר מה שנתהווה כו' (וכמ\"ש במ\"א דהאור בכלל הוא בחי' אצי' וג' בחי' בי\"ע הן בבחי' הכלים כו', וכמבו' שם דבכלים יש ג' מדרי' ובהאור ד' מדרי' כו'), ואיך שייך לומר שהוא בבחי' ממוצע כו'. אך הענין דבאמת הרי התהוות העולמות מאוא\"ס הוא ע\"י הצמצום שהי' באוא\"ס כו', דמאוא\"ס עצמו (היינו מבחי' הגילוי דאוא\"ס כו') א\"א כלל שיהי' התהוות העולמות, רק ע\"י הצמצום שנתעלם האוא\"ס ונעשה התהוות שבאין ערוך כלל כו'. וזהו שגילה האריז\"ל ענין הצמצום שהמקובלים הקודמים לא ידעו מזה והיו מבארים הכל בדרך עו\"ע, וידוע דענין עו\"ע הוא שיש איזה ערך והשתוות ביניהם (וכמשנת\"ל פקמ\"ט דגם בעו\"ע שהן מהותים נבדלים מ\"מ יש בהם השתוות שהן שניהם רוחניים (היינו שהן מתדמין באופן הרוחני' שלהם) שע\"כ נעשה העלול באופן העילה כו'), וכמו מוחין ומדות שהמדות הן לפ\"ע המוחין, וזהו שיש הפרש במדות אם הן מבחי' המוחין שבמדות או\nמבחי' חיצוני' המוחין או פנימי' המוחין כו', וכ\"ה בכל עו\"ע שהעלול הוא בערך העילה כו'. וזהו שהרמ\"ק ז\"ל בפרד\"ס שער אם הא\"ס הוא הכתר החליט שהכתר אינו א\"ס ממש, ובפלח הרמון כ' משמו בס' אלימה שרחוק מה שהי' בין הכתר וא\"ס הרבה יותר ממה שהי' בינינו הנמצאים השפלים ובין הכתר כו', מ\"מ כ' בשער הגוונים פ\"ב בענין הכתר שנק' חשך שזהו במדרי' הכתר שמתייחד עם מאצילו ובבחי' זו לא יושג כלל לזולתו (שעש\"ז נק' חשך), יען שהוא בחי' משתווה המאציל בנאצל ע\"ה שיש כמה יתרונות כו', לפי שכ\"ה בענין עו\"ע שיש להם איזה השתוות כו'. ובאמת לא יתכן כלל לו' שום השתוות לגבי א\"ס ב\"ה (וכמ\"ש במ\"א דלשטה זו הגם שרחוק מאד ערך הכתר לגבי א\"ס יותר מרחוק העשי' לגבי הכתר, מ\"מ א\"א להשוות רחוק הכתר לגבי א\"ס כמו רחוק העשי' לגבי א\"ס, שהרי הכתר הוא מ\"מ עלול הראשון ועד העשי' יש כמה רבבות השתל' שעי\"ז נתרחק יותר כו', ובאמת הכתר עם העשי' שניהם שוין וכמ\"ש עושה פלא כו') (והנה גם לשיטת האריז\"ל הרי עתיק הוא בחי' תחתונה שבמאציל כו', ובביאור האדר\"ז דרפ\"ח כ'\nדעיקר עתיקא הוא הא\"ס שמתלבש ברדל\"א, ובפי' ספ\"ד מהאריז\"ל כ' ההוא רישא דלאו רישא אשר שם חביון עוז העצמות כו', והיינו בחי' עצמות א\"ס ממש כו', הרי לכאורה זהו ג\"כ ענין ערך והשתוות כו'. הענין הוא דהנה דעת האריז\"ל בענין הכתר אינו כדעת הפרד\"ס, דלדעת הפרד\"ס הכתר אינו א\"ס כ\"א בחי' מתהווה מהא\"ס, ודעת האריז\"ל בענין הכתר הוא שהכתר הוא א\"ס ואינו א\"ס, דבחי' עליונה שבו הוא א\"ס בחי' תחתונה שבמאציל, ובחי' התחתונה שבו אינו א\"ס והוא במנין הספי' כו', וכמ\"ש בע\"ח שער דרושי אבי\"ע פ\"ג. והיינו דבחי' עליונה שבכתר אינו בחי' מתהווה מהא\"ס ב\"ה בדרך עו\"ע כ\"א זהו בחי' הא\"ס במדרי' התחתונה שבו כו', וכפי מ\"ש בפי' סד\"צ זהו המדרי' המתלבשת ברדל\"א כו', וכ' שם דרדל\"א עצמו אינו משיג מה שיש בו כו' כנ\"ל פקס\"ג, וזהו מכח הא\"ס להיות עצמותו נמשך ונמצא גם במקום שאינו בערך כלל כו', וע\"ד צמצם שכינתו כו', ובד\"כ הכוונה היא על מדרי' הא\"ס שאחה\"צ והוא בבחי' הקו הנמשך מאוא\"ס כו'. אמנם נושא הכוונה ג\"כ על עצמות א\"ס דעתיק הוא ל' העתקה ממקום\nלמקום בחי' העתקת העצמות כו' וכמ\"ש במ\"א, אבל מה שנתהווה מא\"ס ב\"ה אינו שייך לומר בזה איזה השתוות כו'). וזה מובן רק"],[3601330500,"בענין הצמצום שחידש האריז\"ל שעי\"ז נתהווה התהוות שבאין ערוך כלל כו', דכמו\"כ גם התהוות פרצוף דא\"ק הוא ע\"י הצמצום כו'. אך לפ\"ז צ\"ל מהו\"ע אמצעית בחי' א\"ק מאחר שההתהוות הוא ע\"י הצמצום בדרך אין ערוך א\"כ מה צריכים לממוצע כו'. אך הענין הוא דענין הממוצע בזה אינו כמו להיות דבר אמצעי בין העליון אל התחתון דהיינו שיהי' בערך אל העליון וגם אל התחתון כו' (וכמשנת\"ל פק\"ס בענין שהאור דקו בכלל הוא בבחי' ממוצע וכן באו\"כ כו'), אלא ענין אמצעית דא\"ק הוא דלהיות ההתהוות מאוא\"ס ב\"ה הוא שנתהוו העולמות תחלה בבחי' כללות ואח\"כ בא בד\"פ כו'. והענין הוא דע\"ה שע\"י הצמצום נתהווה בחי' המציאות כו', וכמ\"ש בע\"ח בתחלתו שע\"י הצמצום נתגלה שרש הדין (היינו בחי' הרשימו כח הגבול שבא\"ס), וממנה נעשה המקום שהוא דוגמת הכלי כו' (וגם י\"ל דכמו התהוות בי\"ע הוא מהרוממות והסילוק דבחי' מל' שהו\"ע והים עומד עליהם מלמעלה שזהו בחי' ההשפעה בריחוק דבחי' מל' כו' וכמ\"ש במ\"א, כמו\"כ כללות כל ההתהוות שזהו מבחי' אוא\"ס הסוכ\"ע זהו ע\"י הסילוק והרוממות כו'),\nמ\"מ בכדי להיות ההתהוות בפועל ה\"ז דוקא מבחי' הגילוי דאוא\"ס דכל פעולה הוא ע\"י התגלות הפועל כו', והו\"ע הקו הנמשך מאוא\"ס שעי\"ז הוא ההתהוות בפועל דכל העולמות וההשתל' כו', ומאחר שזהו מבחי' הגילוי ע\"כ אא\"ל ההתהוות בבחי' יש ממש, כ\"א שיתהווה תחלה בבחי' כללות שא\"ז בבחי' מציאות עדיין כו'. וא\"כ ענין אמצעית א\"ק א\"ז מצד האוא\"ס שבבחי' אין ערוך, כ\"א אדרבה מצד המדרי' דאוא\"ס שבבחי' קירוב ובבחי' שייכות אל העולמות שבא בבחי' גילוי כו', דבד\"כ הוא בחי' או\"פ שהוא בחי' הקו כו', שההתהוות משו\"ז צ\"ל באופן הנ\"ל. וזהו כמ\"ש במ\"א דמש\"א אין ערוך לך היינו לגבי עצמות דוקא דכל ההתהוות היא באין ערוך לגמרי לגבי העצמות כו', אבל לגבי בחי' האור וכ\"ש לגבי בחי' האו\"פ שנמדד לפ\"ע העולמות אינו בבחי' אין ערוך לגמרי כו', וע\"כ בכדי שתהי' ההתהוות צ\"ל תחלה ההתהוות בד\"כ ואח\"כ בא בדרך פרט כו', וכמו מאמר סתום ומא' פתוח שזהו מא' כללי ופרטי דבראשית נמי מא' הוא והוא בחי' מא' כללי דבראשית כולל הכל, וכמו שפרש\"י דביום ראשון במא' בראשית נברא הכל\nואח\"כ נפרטו כאו\"א בפרט כו', וכמו ברוך שאמר והי' העולם, דבאמירה א' נבראו כל העולמות כו', וכמארז\"ל בע\"מ נבה\"ע והלא במא' א' יכול להבראות כו', דבאמת נבראו כל העולמות במא' א' רק שזהו בד\"כ ואח\"כ נפרטו בהט' מאמרות כו'.\n<b>וע\"פ</b> הנ\"ל יובן ענין מוצאיהם למסעיהם, דהנה ישראל עלו במח' והיינו בחי' מחה\"ק דא\"ק כו', ופי' עבמ\"ח היינו במדרי' עליונה שבמח' בחי' פנימי' א\"ק כו', דכשם שבס' השתל' יש הפרש בין שרש הנשמות לשרש המלאכים, דמלאכים שרשם מחיצוני' הכלים, ונשמות שרשם מפנימי' הכלים כו', כמו\"כ הוא בשרשם במחה\"ק דא\"ק דשרשם הוא מפנימי' א\"ק כו'. וזהו מוצאיהם שהוא מל' וכמוצא מים כו' דהיינו שרשם ומקורם כו', וענין מסעיהם זהו עליית הנשמות והוא שהנשמות כמו שהן למטה יעלו לשרשם ומקורם בבחי' פנימי' א\"ק כו', ובכדי שתהי' העלי' צ\"ל תחלה ההמשכה משרשם ומקורם שעי\"ז תהי' העלי' כו', וע\"ד העלי' דשבת שאז הוא עליית המל' כנודע, הרי צ\"ל תחלה המשכה מלמע' דז\"ע"],[3601330501,"לכה דודי לקראת כלה דהיינו המשכה מבחי' ז\"א להיות עי\"ז עליית המל' כו', וכמו\"כ בעליית הנשמות צ\"ל תחלה המשכה מלמע' כו'. וזהו מוצאיהם למסעיהם שהוא ההמשכה משרשם ומקורם להיות העלי' ועי\"ז מסעיהם למוצאיהם שמתעלים לשרשם כו'. ומ\"ש ויכתוב משה, הענין הוא דהנה בתו' יש ג\"כ כלל ופרט וכמשי\"ת, ונשמות מושרשים בתו' כידוע, ולכן עלייתם הוא ג\"כ ע\"י התורה כו', אך אומרו ויכתוב משה זהו התו' כמו שהיא בבחי' פרט דאז היא בבחי' אותי' הכתב, דתורה כמו שהיא בבחי' כלל ה\"ה בבחי' אותיות החקיקה וכמו האותיות שבלוחות כו' וכמ\"ש במ\"א וכמו שהוא בבחי' פרט ה\"ז בבחי' אותיות הכתב כו', ועי\"ז הוא העלי' כו', דלהיות דהתו' גם כמו שהיא בהתגלות בבחי' פרט ה\"ה מדרי' עצמי' כו', ע\"כ ע\"י התו' יכול להיות העלי' לשרשם ומקורם בבחי' פנימי' א\"ק כו'. וזהו אלה מסעי בנ\"י כו', דכללות ענין המסעות הוא העלי' דנשמות לשרשם ומקורם כו', ובכדי שתהי' העלי' צ\"ל תחלה המשכה מלמע' כו', וזהו מוצאיהם למסעיהם ועי\"ז מסעיהם למוצאיהם כו', והעלי' הוא ע\"י התו' כו', וזהו ויכתוב משה שע\"י התו' כמו שבאה בבחי' פרט עי\"ז הוא העלי' דנש\"י לשרשם ומקורם במחה\"ק דא\"ק כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם חכ' דתורה היא חכ' דא\"ק, משל הקדמוני, א\"ק לבוש לא\"ס, דהנה א\"ק הוא בחי' ממוצע, והלא הוא אדם דברי', הענין הוא דהתהוות העולמות הוא ע\"י הצמצום, וזהו שגילה האריז\"ל, דמקובלים הקודמים חשבו הכל בבחי' עו\"ע, ולכן הרמ\"ק אחר שמרחיק בחי' הכתר מערך הא\"ס כ' שעצם הכתר הוא בחי' משתווה המאציל והנאצל, ובאמת לא יתכן ענין ההשתוות כלל והיינו ע\"י הצמצום (ובענין הכתר הרמ\"ק סובר שהוא מציאות מתהווה, ולהאריז\"ל עתיק הוא בחי' א\"ס בהעתקה). וא\"כ מה\"ע האמצעי דא\"ק. הענין הוא להיות דההתהוות בפועל הוא ע\"י הגילוי ע\"כ צ\"ל תחלת ההתהוות בבחי' כללות וזהו בחי' א\"ק, ונמצא דאין זה לגבי אוא\"ס שמובדל מהעולמות כ\"א לגבי הגילוי. וז\"ע מוצאיהם למסעיהם, מקור נשמות בפנימיות א\"ק, ומסעיהם הוא העלי' ותחלה צ\"ל מוצאיהם למסעיהם.</span>"],[3601330502,"<h3>בס\"ד. ש\"פ דברים, תער\"ג</h3>\n<b>אלה</b> הדברים אשר דבר משה אל כל ישראל, וצ\"ל מה שמשנה תו' חלוק מהספרים הראשונים שהד' ספרים הראשונים נאמרו כשלישי המדבר דבכל התו' נא' וידבר ה' אל משה ויאמר ה' אל משה, ומי המספר זאת אם נא' שמשה הוא המספר הול\"ל וידבר ה' אלי, וכמו בנביאים שנא' ויהי דבר ה' אלי, ואם הוי' הוא המספר הול\"ל ודברתי אל משה, אלא זהו שלישי המדבר ומספר שדבר ה' אל משה כך וכך, ובמשנה תורה נא' כמשה המדבר מפי עצמו, וכמו ואתחנן אל הוי', ואתפלל אל ה' כו', ואתנפל לפני ה' כו', וכתיב וידבר ה' אלי כו', רק התחלת משנה תורה"],[3601330503,"נאמר ג\"כ כשלישי המדבר אלה הדברים אשר דבר ולא נא' מי הוא המספר כו', וצ\"ל מהו\"ע שלישי המדבר, ולמה הד' ספרים הראשונים נאמרו מפי שלישי המדבר ומשנה תו' נא' ממשה מפי עצמו, ומפני מה התחלת משנה תורה נא' ג\"כ מפי שלישי המדבר כו'. גם צ\"ל מהו\"ע אלה הדברים אשר דבר כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דא\"ק הוא ממוצע בין אוא\"ס לעולמות והקשה הלא א\"ק הוא בחי' אדם דברי' דכללות דבאין ערוך לגבי אוא\"ס ואיך שייך לומר שהוא בבחי' ממוצע כו'. ונת' דאמצעית דא\"ק אינו כמו הממוצע בין עליון ותחתון שיש בו השתוות אל העליון והשתוות אל התחתון כו', כ\"א ענין הממוצע דא\"ק הוא בענין ההתהוות לבד, דבכדי שמבחי' האור והגילוי דאוא\"ס יהי' התהוות העולמות צ\"ל ההתהוות תחלה בבחי' כלל ואח\"כ בא בדרך פרט כו', וזהו קורא הדורות מראש היינו מראש דא\"ק דבא\"ק נתהוו העולמות בבחי' כלל ואח\"כ נפרטו בד\"פ כו'.\nקסה) <b>ולהבין</b> זאת בתוס' ביאור, הנה ידוע דכללות ענין ההשתל' וכללות ענין הס' וההדרגה בעולמות הוא מצד האו\"פ כו', דמצד האו\"מ אינו שייך כלל כללות ענין ההשתל' וס' והדרגה כ\"א מצד או\"פ דוקא, וכדאי' בע\"ח ובמב\"ש מה שאחה\"צ הוצרך להיות המשכת הקו שבאם היו העולמות כמו שהן מצד האו\"מ לא הי' חילוקי מדרי' כלל בעולמות כ\"א היו כולם במדרי' א', ולא כן הי' כוונת המאציל כ\"א שיהי' ס' והדרגה בעולמות בבחי' ירידה מדרי' אחר מדרי' כו' (והכוונה בזה בכדי שיהי' מציאות יש שהו\"ע בירור הסיגים והפסולת כו'), וע\"ז הי' המשכת הקו שנמשך בחי' קו דק ומצומצם ואופן המשכתו הוא שבקצהו העליון נוגע ודבוק באוא\"ס ובקצהו התחתון אינו דבוק באוא\"ס הסובב, ועי\"ז יש בו מעומ\"ט שבקצהו העליון הוא בבחי' מע' וכל מה שמתרחק ממקורו הוא בבחי' מטה כו', ועי\"ז נעשה סדר והדרגה בהעולמות כו'. ועיקר ענין מעומ\"ט הוא בהאור וכמו\"כ עיקר ענין ההשתל' מדרי' אחר מדרי' בבחי' מיעוט האור בערך זל\"ז כו', הכל הוא בבחי' האור כו', אך עי\"ז נעשה ס' והדרגה בעולמות\nלהיות דהתהוות העולמות הוא מן האור ע\"כ לפי אופן האור כ\"ה העולם כו', וכמו עד\"מ אותי' המח' ואותי' הדבור שהן רחוקים בערכם זמ\"ז דמח' בלתי מורגש והדבור מורגש אל הזולת כו', ומ\"מ הן בס' והדרגה דלפי אופן אור השכל המאיר במח' כ\"ה האותי' דמח' ולפי אופן האור המאיר בדבור המה אותי' הדבור כו', וכמו\"כ הוא בעולמות דלפי אופן האור כ\"ה העולם כו', וההדרגה בזה הוא בבחי' המציאות דהעולם שנתהווה ממדרי' עליונה שבקו אינו בבחי' מציאות וכל מה שיורד למטה נעשה בבחי' מציאות יותר כו'. ובאמת המעומ\"ט שבהאור הוא ג\"כ בבחי' המציאות דבחי' עליונה של הקו הוא אינו בבחי' מציאות אור וכשמתרחק ממקורו נעשה בבחי' מציאות אור כו', רק שבכללות בחי' האור בכלל הוא בחי' אין והעולמות בכלל הן בבחי' מציאות, ויש בהאור בחי' המציאות ובעולמות יש ג\"כ בחי' העדר המציאות כו', ולפי אופן האור כ\"ה המציאות של העולמות כו'. ובפרטי' יש בזה ריבוי רבבות מדרי' מתחלת ההתהוות עד שנעשה בחי' המציאות כו', אך בד\"כ ה\"ז נכלל בג' מדרי', והוא שכל דבר שנתהווה הנה בתחלת\nהתהוותו הוא בבחי' חומר פשוט שאין בו שום צורה שז\"ע הפשיטות שאין בזה שום ציור כלל והיינו שאינו בבחי' מציאות עדיין, כי כל מציאות בהכרח שיהי' בזה ציור באיזה אופן הוא, וכמו"],[3601330504,"ביש גשמי הרי בהכרח הוא בעל קצוות אם בעל זוויות או עגול, אבל בעל קצוות הוא בהכרח שזהו הגבלתו ובזה הוא נתפס כו', וכן כל מציאות דבר בהכרח שיהי' בו ציור והחומר הפשוט משום צורה הוא שאינו בבחי' מציאות עדיין, רק שלגבי אין ואפס המוחלט נק' יש והיינו מפני שאינו אין לא שהוא יש, דלהיות אין ויש מובדלים בערך שאינו שייך ממוצע ביניהם ע\"כ מה שאינו אין ה\"ז יש, אבל לא שהוא בבחי' מציאות יש רק הוא בבחי' אפשרות המציאות, דהאין הוא בחי' אפיסת המציאות והעדרו והחומר הפשוט הוא שאפשר להיות בחי' המציאות כו' (וא\"ז רק מה שנותן מקום למציאות המבו' במ\"א). והצורה הוא בחי' התגלות החומר (היינו בחי' התגלות האפשרית המציאות שבהחומר לא התגלות עצם החומר כו') שבא לכלל צורה כו', אבל היא צורה כללית עדיין כו', ואח\"כ נעשה בבחי' מציאות ממש כו'. והן ג' מדרי' חומר צורה ותיקון, חומר הוא חומר הפשוט מכל צורה, וצורה הוא צורת והתגלות החומר והוא ג\"כ בבחי' פשיטות עדיין, ותיקון הוא שנעשה בבחי' מציאות ממש כו'. וכמו הד' יסודות בתחלה נברא חומר\nפשוט שאין בו שום ציור מהד' צורות רק מה שנושא בעצמו כל הצורות, ואח\"כ צורה הו\"ע התגלות הד' צורות יסוד האש ויסוד המים כו', והם ג\"כ יסודות פשוטים וכנודע דהאש היסודי אינו חם ואינו מאיר דהגדרת האש הוא חום ואור והאש היסודי מופשט עדיין מהגדרת האש, וכן המים היסודי מופשט מהגדרת המים כו', שהן רק כחות היולים שמופשטים עדיין מהגדרה כו', ותיקון הוא שנעשה בבחי' מציאות בגדר מיוחד ופרטי כו'. והן ג' מדרי' בי\"ע דברי' הוא ראשית ההתהוות בבחי' פשיטות עדיין ויצי' הוא בחי' צורה כו', ועשי' הו\"ע תיקון כו' וכמ\"ש במ\"א. וזהו ג\"כ ענין בי\"ע הכללים דהיינו בכללות ההתהוות דבחי' אדם דברי' דכללות זהו תחלת ההתהוות שאינו בבחי' מציאות עדיין כו', ובחי' אדם דיצי' הוא בחי' התגלות המציאות, ואדם דעשי' הוא שנעשה בבחי' מציאות כו'. אך לפ\"ז צ\"ל מה\"ע דא\"ק הוא בבחי' ממוצע מאחר שזהו רק בס' ההתהוות שהוא בס' והדרגה דתחלת ההתהוות הוא לא בבחי' המציאות עדיין כו', וא\"כ אינו שייך ע\"ז לו' שזהו בבחי' ממוצע כו' (דכמו\"כ אפ\"ל דבחינת אדם דיצי' ג\"כ\nבחי' ממוצע כו'). אך הענין דבחי' א\"ק מחולק בזה מהמדרי' שלמטה ממנו במה שהוא בבחי' כלל שכולל הכל, דזה אינו שייך במדרי' שלמטה מא\"ק דהגם שהוא בס' ההתהוות אינו בבחי' כלל, רק בחי' א\"ק הוא בבחי' כלל שכל מה שנתהווה מרכ\"ד עד סוכ\"ד בעולמות העליונים והתחתונים וכל מה שנעשה בשית אלפי שנין כו', הכל הוא כלול בבחי' א\"ק כו', באופן דבחי' א\"ק יש לו שייכות לעשי' כמו לאצי' דכשם שאצי' כלול בא\"ק כמו\"כ עשי' כלול בא\"ק, א\"כ הוא שייכות לכל העולמות בשוה לעשי' כמו לאצי' כו', משא\"כ בחי' העקודים הגם שמזה נשתלשל ונתהווה כל מה שנתהווה בעולמות כו', מ\"מ אינו בבחי' שייכות לכל העולמות לפי שאינו בבחי' כלל, ובד\"כ הוא בבחי' שייכות לעולם האצי' היינו התחלת ההשתל' דעולם האצי' כו', משא\"כ א\"ק הוא בחי' כלל הכולל הכל כו'. אך מה שכולל הכל אינו בבחי' מציאות כלל עד שכולם הם בו בהשוואה דאצי' ועשי' שוין ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע הנה סדר והדרגה הוא באו\"פ. וז\"ע הקו להיות מעומ\"ט בהאור ועי\"ז הוא המעומ\"ט בכלים ובעולמות, והוא בענין המציאות, ובכללות</span>"],[3601330505,"<b>הוא</b> בג' מדרי' חומר צורה ותיקון, דתחלת ההתהוות הוא חומר פשוט, והיינו שאינו במציאות עדיין, דכל מציאות הוא בציור, ולגבי אין ה\"ז יש, וביש הוא רק אפשרות המציאות, ואח\"כ התגלות הצורה והיא הגדרה מופשטת, וכמו אש היסודי שהוא פשוט, ואח\"כ בחי' המציאות, וזהו א\"ק אדם דברי', עקודים יצי', אצי' עשי', וא\"כ מה\"ע הממוצע דא\"ק. הענין הוא דא\"ק לבד שזהו התחלת ההתהוות ה\"ה כולל הכל ויש לו שייכות לעשי' כמו לאצי' משא\"כ עקודים.\nקסו) <b>וזהו</b> דא\"ק נק' בש' אדם שלא מצינו בשום פרצוף שיהי' נק' אדם כ\"א פרצוף דא\"ק, דאצי' נק' אדם לפי ששם שייך בחי' ציור אדם וכמ\"ש ועל הכסא דמות כמראה אדם שזה שייך רק בע\"ס דאצי' כו'. וגם נק' אדם ע\"ש אדמה לעליון כו' וכמ\"ש במ\"א, אבל להיות נק' בשם אדם הוא בחי' א\"ק לבד כו'. והיינו לפי שאדם מורה על התכללות דבזה חלוק האדם מכל הנבראים במה שכלול מהכל, והוא שיש בו ד' מדרי' דצח\"מ דבעצם הוא במדרי' מדבר ומצד החיות שבו הוא בבחי' חי, והשערות שבו הן בחי' צומח, וגם צומח מקטנות לגדלות כו', וגופו הוא בחי' דומם, משא\"כ גוף הבע\"ח הוא בחי' צומח וכנודע. וגם בכחותיו יש בחי' דצח\"מ וכמשנת\"ל פקמ\"ו וקמ\"ז, דבשכל יש דצח\"מ דשכל המעשי הוא בחי' דומם והשכל בענינים טבעים בחי' צומח ושכל שבדבור הוא בחי' חי, ושכל שמשכיל השכלות בחי' מדבר כו'. וגם האדם כלול מכל המיני כחות וכמ\"ש הרמב\"ם בח' פרקים שלו דכל הנמצאים יש להם פעל א' או ב' פעלים, והאדם משתנה ומתחלף לכמה פעולות שונות זמ\"ז כו', דכל ההפכים ישנם באדם דכל הכחות שאפ\"ל\nהכל נמצא באדם כו'. וכן יש בו מהמדרי' היותר נעלות והיותר תחתונות, דמצד נשמתו יכול להיות במדרי' היותר נעלות וכמא' מתי יגיעו מעשי למעשה אבותי אברהם יצחק ויעקב ומשה כו', דכאשר יתנהג בטהרה ופרישות ויעסוק בתו' ותפלה כדבעי יכול להיות במדרי' היותר גבוה, ולהיפך ח\"ו יכול להיות במדרי' היותר שפלה ר\"ל להיות גרוע מבע\"ח הטמאים ושקצים ורמשים כו', הרי האדם כלול מכל המדרי' כו'. וזהו מה שא\"ק נק' בשם אדם להורות ע\"ז שכל מה שנתהווה בעולמות מרכ\"ד עד סוכ\"ד הכל נמצא כלול בא\"ק כו'. אמנם איך כ\"ז כלול שם הכל הוא לא בבחי' מציאות כלל, וכמו חומר הראשון שנושא את הד' צורות שאינם שם בבחי' מציאות כלל כו', וכמו שהנפש נושא את כל הכחות כו', דהרי הכחות כמו שכלולים בנפש ה\"ה ג\"כ בבחי' הפשטה לגמרי מבחי' מציאות כו', ומ\"מ ה\"ה בבחי' כחות כו' (ונק' הגדרה מופשטת כו'), אבל הנפש שנושא את הכחות הרי אינם בבחי' כחות כלל כו', והנפש נק' נפש אחת שאין בה שום ריבוי כלל ח\"ו אף שהיא נושא כחות כו', כמו\"כ בחי' א\"ק הגם שכולל הכל ה\"ז לא בבחי'\nמציאות כלל עד שכולם הם בהשוואה ממש כו'. וזהו דא\"ק הוא בבחי' ממוצע לפי שכולל הכל והיינו שא\"ז רק התחלת ההתהוות כ\"א שכולל הכל כו', דהתחלת ההתהוות הוא רק בבחי' המציאות שזה התחלת המציאות, אבל לא שכל מה שמתהווה מזה נמצא כלול בו כו', וכמו בכלים הנה התחלת המציאות של הכלים א\"ז מחייב שכל הבחי' כלים שיתהוו נמצא כלול בזה כו'. דהנה ידוע דהתחלת גילוי הויות הכלים הוא בעקודים וכמ\"ש בע\"ח שער העקודים פ\"א, וה\"ז רק תחלת התהוות הכלים לא בחי' כוללת הכל היינו שכל מה שיתהווה בבחי' כלים כלולים בזה כ\"א שהוא תחלת ההתהוות, וכללות עולם"],[3601330506,"העקודים הוא עולם פרטי, משא\"כ א\"ק הוא עולם כללי, והיינו שזהו בחי' מחה\"ק שעלה באוא\"ס המאציל כל מה שיתהוו עולמות ונבראים וכל המאורעות וההנהגות שיהי' בהם הכל כאשר לכל עלה במח' וזהו בחי' א\"ק. דבא\"ק גופא יש בחי' א\"ק דא\"ק ואבי\"ע דא\"ק, וי\"ל שזהו בחי' נשמה וגוף ולבוש והיכל שבא\"ק המבואר בע\"ח שמ\"א פ\"ד שהן בחי' אבי\"ע שבא\"ק (אח\"כ ראיתי שכ\"כ בס' נה\"ש ושם דהשרש הוא בחי' א\"ק שבא\"ק), ונראה דגם הע\"ס דא\"ק כוללים כל העולמות וכמ\"ש בע\"ח שמ\"ז פ\"ג דאוא\"ס ע\"י התלבשות בבחי' דא\"ק מאיר באצי' ושם דבברי' הוא ע\"י התלבשות בבינה דאצי' וביצי' ע\"י התלבשות ז\"א דאצי' כו'. אמנם כמו\"כ הוא ע\"י התלבשות תחלה בבחי' בינה וז\"א ומל' דא\"ק, וכמ\"ש במ\"ח מס' הבריאה פ\"א מ\"ב ואוא\"ס שבא\"ק כו' נתלבש אף בבינתו וע\"י מסך דרך ג\"ר דאצי' מאיר בברי' כו', ובמס' היצי' פ\"א מ\"ג ואוא\"ס כו' ע\"י מסך ז\"א דא\"ק המתלבש אף בז\"א דאצי' ונכלל בז\"א דברי' כו', ובמס' העשי' פ\"א מ\"ב ואוא\"ס כו' ע\"י מסך מל' דא\"ק המתלבש אף במל' דאצי' ונכלל במל' דברי' ומאיר בה דרך מל'\nדיצי' כו', והיינו דשרש האצי' הוא מבחי' חכ' דא\"ק ושרש הברי' מבינה דא\"ק ויצי' מחג\"ת ועשי' ממל'. ואפשר דהד' מדרי' הנ\"ל נשמה גוף לבוש היכל הן הע\"ס דא\"ק דחכ' היא בחי' נשמה, ובינה בחי' גוף (ועמ\"ש בע\"ח שמ\"א פ\"ז דאפי' בינה שהיא נק' בית גופני לחכ' כו'), וחג\"ת בחי' לבוש ומל' בחי' בית והיכל כו' (וכתר דא\"ק הוא בחי' נשמה לנשמה בחי' השרש כו'), וכ\"נ ממ\"ש בע\"ח שמ\"א ספ\"ד שהן ד' אותיות הוי' (וכ\"ה מפורש בס' נה\"ש). ומ\"מ צריכים לומר שיש בחי' עצמו (שג\"ז הוא בבחי' ע\"ס) (וי\"ל דבבחי' זו הוא בחי' תחלת ההתהוות) ובחי' כוללת דהיינו שהוא בחי' מחה\"ק על כל העולמות כנ\"ל (וכמו במשל דהנפש שנושא הכחות שנת\"ל, הלא יש הנפש עצמו ומה שנושא את הכחות הגם שאין לחלק ביניהם כו'). והנה בהמשל דחומר וצורה שנת\"ל פקס\"ה הרי הצורה והתגלות החומר הוא התגלות כל הד' צורות ואח\"כ התיקון שלהם, וא\"כ בהדוגמא למעלה בחי' העקודים שזהו בחי' יצי' ה\"ז ג\"כ כולל כל המדרי' כו', הנה ודאי כן הוא שיש בו כל הד' מדרי' (והן בחי' חכ' בינה ת\"ת ומל' שבו דכן הוא גם\nבאצי' רק שבעקודים הן בבחי' צורה ובאצי' בבחי' תיקון, והן ג\"כ בחי' נשמה גוף כו', וגם שרש שיש בכל עולם כמ\"ש בע\"ח שם, ועמ\"ש במ\"ח מס' כללות העולמות פ\"ג מ\"ג). אך זהו בחי' עצמו לא בחי' כוללת דבעצם הוא עולם פרטי (וכל עולם כולל המדרי' שבהעולם שלמטה ממנו כו' וכמ\"ש במ\"א ואין זה בחי' כוללת כו'), ורק א\"ק הוא בחי' כוללת ועקודים הוא התגלות פרט א', וכמ\"ש בע\"ח שער העקודים פ\"א וז\"ל כי לבן הוא סוד לובן העליון אשר הוא קודם כל האצי' הזה (והיינו בחי' א\"ק) והוא הי' עושה כל הבחי' עקודים נקודים וברודים לצורך האצי' שיאצל אחרים כו' והתחיל בעקודים כו' עכ\"ל. והנה בהתגלות פרטי המדרי' מבחי' הכוללת דא\"ק י\"ל דעקודים הוא בחי' יסוד המים, וכמ\"ש באוצ\"ח בדרוש ענ\"ב דעקודים רומז לאברהם דהויות הכלים הוא רחמים ואברהם בגימט' רחם כו', וא\"כ זהו בחי' מים, ונקודים בחי' אש דתהו בחי' גבו', וברודים היינו אצי' בחי' רוח שזהו עיקר התיקון, וכמ\"ש במ\"א על מאה\"ז פ' לך דע\"ז א' לבתר אגלידו וקיימא ברוחא עילאה כו', ובי\"ע בחי' יסוד העפר כו', ועמ\"ש בע\"ח שער העקודים ספ\"ד ובמל' דעולם העקודים יש יו\"ד שרשים אל י\"ס דנקודים כו', היינו שרשי עולם"],[3601330507,"התחתון שנמצא כלול בעולם העליון ממנו כו', ועמשנת\"ל פקל\"ב בענין רושם דכלי העקודים כו' יעו\"ש, והיינו דהגשמת הכלי דאצי' הוא ע\"י הרושם דעקודים אבל שרש התהוותם הוא מכלים דא\"ק (וכמש\"ש די\"ל שהן בחי' מהות ממהות כו'), ולהיות דכלים דא\"ק אינם בחי' כלים כלל וכמ\"ש בע\"ח שער עיגולים ויושר ענף ד', ע\"כ בכדי שיהי' בחי' מציאות כלים דאצי' זהו ע\"י הרושם דעקודים כו'. ונמצא דעקודים זהו רק התחלת גילוי ההתהוות כו', משא\"כ א\"ק הוא בחי' כלל שהכל נמצא כלול בו כו', והכל נמצא בו לא בבחי' מציאות כלל כו', וזהו עילוי בבחי' א\"ק הא' מה שאינו רק התחלת ההתהוות כ\"א שהוא בבחי' כלל כו', והב' ההפלאה שע\"ה כולל הכל אינם בו בבחי' מציאות כלל עד שכולם הם בבחי' השוואה כו', וזהו שא\"ק נק' אור כללי לפי שהוא בחי' הכלל דכל העולמות וההשתל' והכל בו בבחי' השוואה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו דא\"ק נק' אדם, כי האדם הוא שכלול מכל ההפכים ומהיותר עליון ותחתון, וכמו\"כ א\"ק כולל הכל ובהשוואה ממש, וכמו הנפש שנושא כל הכחות והוא נפש א'. והתחלת ההתהוות אינו מוכרח שכולל הכל (ע' ברמב\"ן ע\"פ בראשית) וכמו עקודים ראשית גילוי ההתהוות והוא עולם פרטי, וא\"ק הוא תחלת ההתהוות ובחי' כוללת, וזהו העילוי דא\"ק שכולל הכל, והכל בהשוואה לא בבחי' מציאות.</span>\nקסז) <b>והנה</b> מה שא\"ק כולל כל העולמות זהו בחי' חיצוני' דא\"ק, אבל פנימי' א\"ק אינו שייך לו' בזה שהיא בחי' כוללת כו', ועמ\"ש בלק\"ת בהבי' דמוצאיהם בשם המ\"ח מס' כללות העולמות רפ\"ב דא\"ק הוא כדוגמת בחי' א\"א לגבי עולמות אבי\"ע, א\"כ זהו בחי' חיצוני' א\"ק וכמו א\"א שהוא חיצוני' הכתר כו', ובחי' הפנימי' דא\"ק הוא מ\"ש בע\"ח דלעילא מגולגלתא דילי' יש כדוגמת עתיק כו'. ולפ\"ז בחי' א\"ק הוא בבחי' ממוצע גם בענין הזה בין אוא\"ס לעולמות, וכמו הכתר שהוא ממוצע וכלול מב' בחי' עתיק ואריך דעתיק הוא בחי' תחתונה שבמאציל ואריך ראש ומקור לנאצלים כו', וכמ\"ש בע\"ח שמ\"א פ\"ג, כמו\"כ גם בבחי' א\"ק בהב' מדרי' שבו בחי' פנימי' וחיצוני' כו', ובלק\"ת בהבי' הנ\"ל דבחי' עתיק דא\"ק זהו בחי' ראשית הקו וא\"כ ה\"ז בחי' או\"פ כו', וכ\"ה הכוונה כאן דגם מה שא\"ק הוא בבחי' ממוצע בין אוא\"ס לעולמות ויש בו מבחי' א\"ס שלמע' מגדר שייכות לעולמות כ\"ז הוא מבחי' או\"פ כו'. וע\"ה דאו\"פ בכלל הוא מה שנמדד לפ\"ע העולמות כו', מ\"מ בחי' ראשית הקו הוא מה שלמע' מגדר\nשייכות אל העולמות כו', וכמו בחי' עתיק דאצי' שהוא מה שנעתק ונבדל מהנאצלים, ע\"ה דעתיק באמת הוא בחי' או\"פ וכנודע דפנימי' המקיף הוא בחי' פנימי דוקא כו', כמו\"כ בחי' ראשית הקו ע\"ה בכלל בחי' או\"פ ה\"ה למע' מע' מגדר שייכות אל העולמות כו', וכמ\"ש בלק\"ת שם בשם העה\"מ דחוט הא\"ס (שבעולם המלביש) הוא בחי' הי\"א שבקדושה, וכידוע דבקדושה הן ע\"ס עשר ולא תשע ולא י\"א, והיינו בהאור שבא בבחי' התלבשות בכלים שהאור מתייחד עמהם ואינו נחשב למדרי' בפ\"ע כו', אבל בחי' א\"ס שלמע' מבחי' ע\"ס ואינו נמנה עמהם והו\"ע אנת הוא חד ולא בחושבן כו', זהו בחי' הי\"א כו', וזהו ג\"כ ראשית הקו שאינו במנין ע\"ס אפי'"],[3601330508,"במדרי' היותר עליונה כו'. ונמצא דבחי' א\"ק הוא בחי' ממוצע בענין ההתהוות שנתהוו העולמות בבחי' כלל ומא\"ק יצאו ונתהוו בד\"פ כו', וגם בבחי' ממוצע שיש בזה מבחי' א\"ס שלמע' מבחי' גדר שייכות אל העולמות (שזהו בחי' האור שבחיצוני' א\"ק כו'), והוא ראשית הקו שזהו כדוגמת עתיק כו' (ויש בזה גם מבחי' אור הסובב דהיינו אור הבל\"ג לגמרי, וכמובן מהמשל דמראות גדולות וקטנות שהובא לעיל פ' קס\"ב וקאי על בחי' סובב כו'). וזהו מ\"ש בע\"ח דאוא\"ס ע\"י התלבשותו בחכ' דא\"ק מאיר באצי' נר' שזהו בחי' עתיק דא\"ק, שהרי בזהר הרקיע על מאה\"ז בריש הורמנותא דמלכא כ' דכשם שמל' דאצי' נעשית עתיק לברי' כמו\"כ בחי' מל' דאצי' דכללות נעשית בחי' עתיק לאדם דברי' דכללות כו', ובחי' עתיק דברי' זהו בחי' נקודת המל' דאצי' שבוקעת את המסך ויורדת בברי' ומתלבשת בג\"ר דברי' כו' וכמ\"ש בע\"ח שער ס' אבי\"ע פ\"א, וכמו\"כ בחי' עתיק דא\"ק זהו בחי' ראשית הקו שבוקע חשך הצמצום שעז\"נ אז יבקע כשחר אורך כו', ומתלבש בבחי' חכ' דא\"ק כו', וע\"י חכ' דא\"ק מתלבש בחכ' דאצי' בבחי'\nפנימי' החכ' כו'. וזהו שבקש משה הראני נא את כבודך, וידוע דכבוד הוא בחי' חכ' כבוד בגימט' ל\"ב שהן לבנ\"ח כו', ולכאו' א\"מ מה שבקש משה הראני נא את כבודך שהרי משה הוא בחי' החכ' וכמ\"ש כי מן המים משיתיהו כו'. אך הענין הוא שבקש בחי' החכ' כמו שמתלבש בזה בחי' פנימי' הכתר, וכמ\"ש הרמ\"ז במדבר דקי\"ח ע\"א בפי' הראני נא את כבודך שזהו כמו שהחכ' מלביש לבחי' הכתר, וזהו כבודך כבוד ך' (וע\"ה שכ' שם שמלביש לאריך הכוונה היא על המשכת בחי' הפנימי' ממש כו' יעו\"ש). וברע\"מ פנחס דרנ\"ה ע\"ב אי' בענין שיעור סוכה לא פחות מעשר דאיהי מל' כו' ולא למע' מעשרים דאיהי כ' כתר עליון דלא שלטא בי' עינא כבוד עילאה עלי' אמר משה הראני נא את כבודך כו', והיינו דבחי' הכתר לא שלטא בי' עינא שזהו למעלה מהשגה כו', ומ\"מ הרי עשרים אמה כשר ולא פסול רק למע' מעשרים, ומבו' במ\"א שזהו ב' המדרי' שבכתר, דעשרים אמה הוא בחי' חיצוני' הכתר ראש ומקור לנאצלים, ולמע' מעשרים זהו בחי' פנימי' הכתר כו'. וזהו שבקש משה הראני נא את כבודך בחי' פנימי' הכתר שבחכ' והו\"ע\nפנימי' אבא פנימי' עתיק כו', וזהו בחי' אור שלמע' מבחי' מים כו'. וכנודע דחכ' נק' מים ונק' אור, דמים הוא בחי' חיצוני' החכ' והוא בחי' הביטול דחכ' (כמו מיא דניידי כו'), שעי\"ז החכ' היא בחי' כלי לאוא\"ס כו', ואור הוא האוא\"ס השורה בחכ' שז\"ע פנימי' אבא פנימי' עתיק כו' והיינו בחי' ח\"ס, ובח\"ע דאצי' בחי' פנימי' ועצמי' החכ' כו'. וזהו שנאמר כבדך חסר ו', דהנה כבוד בוי\"ו בגימט' ל\"ב והן לבנ\"ח שהן המשכות וז\"ע וי\"ו כו', וזהו בבחי' חכ' דאצי' שיש לבנ\"ח, אבל מו\"ס לא אתפתחא לשבילין ונתיבות וכמ\"ש באד\"ר דקכ\"ח ע\"ב, ועמ\"ש ע\"ז בבה\"ז שזהו לפי שמו\"ס הוא בחי' פנימי' הכתר כו' (ובמ\"א מבו' דעיקר הממוצע הוא בחי' ח\"ס דלפעמים מתעלם ופעמים מתגלה והיינו ב' בחי' סתימות שבו, הא' מה שסתום מהמקבל והב' שסתום בעצם מצ\"ע כו', וז\"ע מתן בסתר כו' וכמ\"ש במ\"א וכמשי\"ת לקמן), וזהו כבדך חסר דלא אתפתח לנתיבות כו', וכ\"ה בחכ' בעצמו' ופנימי' החכ' כו'. וי\"ל שזהו הנתיב הל\"ב דחכ' הנק' שכל מופלא שהוא עצם החכ' כמ\"ש הפרד\"ס שער הנתיבות פ\"ו, ועמ\"ש במ\"א\nבענין שכל מופלא ושכל נעלם בהגהות לסי' ב\"ש, ועז\"נ נתיב לא ידעו עיט והוא בחי' מ\"ה דחכ' שזהו בחי' אין דכתר ממש (בחי'"],[3601330509,"פנימי' הכתר) שנמצא בין הנאצלים כו', (וזהו הנמשך בחו\"ב ע\"י בחי' ד\"ע המחליף מקום הכתר כו'), וכמ\"ש במ\"א. וזהו מה שא\"ס ע\"י התלבשותו בחכ' דא\"ק מתלבש בחכ' דאצי' והוא בחי' עצמי' האצי' שזהו מבחי' פנימי' ועצמי' א\"ס ב\"ה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וכ\"ז בחי' חיצוניות א\"ק אריך דעולמות, אבל פנימיות א\"ק בחי' ראשית הקו שהוא עתיק דא\"ק עם היותו או\"פ ה\"ה בבחי' העתקה מעולמות כמו עתיק דאצי', והיא בחי' הי\"א שבקדושה. ולפ\"ז א\"ק בחי' ממוצע גם מצד אוא\"ס, ובחי' הי\"א המתלבש בחכ' דא\"ק (דוגמת עתיק דברי' בג\"ר דברי') ומאיר בפנימיות חכ' דאצי', וזהו שבקש משה הראיני נא את כבודך, ך' כתר א\"א שיעור סוכה, ולמעלה מכ' עתיק, והוא בחכ' בחי' אור, כבדך חסר דלא אתפתחא לשבילין, וי\"ל שזהו נתיב הל\"ב שכל מופלא.</span>\nקסח) <b>וענין</b> הממוצע דא\"ק מה שהוא בבחי' כלל לגבי העולמות. הענין הוא דהנה כל מה שנתהווה בעולמות הוא תחת הזמן, דאא\"ל עולם בלא זמן ומקום שזהו מציאות העולם כו', ובעולמות עליונים היינו עולמות בי\"ע הרוחני' בחי' המקום שבהם אינו בבחי' גשם כמו המקום שלנו, וכמו שהסכימו כל החוקרים שלמע' מגלגל התשיעי לא יש שום מקום כלל, והיינו שאין שם מקום גשמי כ\"א מקום רוחני כו'. ואפשר שיובן ע\"ד מ\"ש בלק\"ת בהביאור דשוש אשיש שמצינו באדם כמה כחות שהן במקום אחד כמו השכל והרצון והמח' והכל במוח (נר' דהכוונה שם על הרצון שהוא פנימי' המדות שיכול להיות גם היפך המדות שבלב הטבעים רק מפני חיוב השכל כו', וכמו להושיט רגלו במים חמים ביותר לצורך רפואה כו', או שמצטער מדבר תענוג מפני ידיעתו שאצ\"ל כן כו', וכן להתענג בדבר צער כמו בתענית וסיגופים שהם תיקון לנפשו כו', שכ\"ז הוא מן הרצון שע\"פ השכל והוא חיות המדות כו', וכמ\"ש בלק\"ת ד\"ה בהעלותך הא' ומבו' במ\"א), וכן בכתיבת איזה שכל יש בזה ד' מיני כחות שונות כו' כמש\"ש, והרי כל כח יש\nלו מקום רק שאינו נתפס בגשם וע\"כ יכולים להיות כולם במקום א' כו'. ועיקר ענין המקום הוא במע' ומדרי' דמעלת הדבר זהו מקומה של הדבר, וכמו אין לך דבר שאין לו מקום והיינו שיש לו תפיסא ואינו דבר בטל (בל\"א עס איז עפעס אזאך און האט א ביטרעף וזהו מקומו כו'). ויובן זה יותר מהעדר תפיסת מקום וכמו בהעדר תפיסת מקום דקטן לגבי הגדול שאינו תופס מקום לעצמו (ער פאר לירט זיך ער האט ביי זיך קיין ווערט און קיין ביטרעף), דזהו מפני שאינו מוצא בעצמו שום מעלה וערך לגבי הגדול ע\"כ אינו תופס מקום לעצמו כו', וכמו\"כ הוא בתפיסת מקום שהוא מעלת הדבר (דער ביטרעף) שזהו התפיסת מקום שלו כו', ואין הכוונה בזה בתפיסת מקום לגבי הזולת (שזהו ממילא שתופס מקום גבי זולתו), רק הכוונה שתופס מקום בעצמו מצד מעלתו שזהו המקום שלו כו', וזהו\"ע המקום שהו\"ע המע' ומקומו של כל דבר (דער ביטרעף פון יעדער זאך) הוא לפי מעלתו של הדבר כו'. ובגשמי' ג\"כ ענין המקום הוא שמתאר את הדבר והוא הגבלת והגדרת הדבר, וכמו גדר הדומם וגדר הצומח כו', שזהו\"ע תואר הדבר\nשהוא הגדר כו', והיינו מעלתו מעלת הדומם ומעלת הצומח לא עצם מציאות הדומם כ\"א מעלתו והוא גדרו ותארו כו'. וכמו"],[3601330510,"בפרטי הדברים הרי התואר הוא המעלה, וכמו בדומם שיש אבנים פשוטים ואבנים טובות המאירים שהכל הוא דומם רק שמחולקים במעלתם והוא התואר שלהם כו', וכמו\"כ בכללו' גדר הדומם היינו מע' הדומם וגדר הצומח מע' הצומח וכן גדר החי כו'. וגדרו ומעלתו של הדבר זהו מקומו היינו תפיסתו שנתפס לדבר מה והוא המתאר אותו כו', רק שבגשמי' הרי התפיסה היא בהגשמה ממש ותופס מקום גשמי, וכן התואר והציור שלו הוא בגשמי שיש בו אורך ורוחב כו' (ובאמת לא זהו מקומו האמיתי כ\"א המעלה והגדר שלו זהו מקומו האמיתי כו' כנ\"ל). ולמע' ברוחני' בעולמות עליונים כמו המלאכים וכדומה התפיסה שלהם אינו בגשמי כ\"א תפיסה רוחני' בערכם ומעלתם כו', וכמ\"ש במ\"א דהתחלקות המלאכים במה שמחולקים זמ\"ז הוא בהשגתם ובאופן העבודה שלהם, וכמו מחנה מיכאל באהבה שיש בזה ק\"פ אלף מחנות והיינו שהן מחולקים באופן השגתם ועבודתם וזהו ערכם ומעלתם, וזהו בחי' המקום שלהם כו'. ומ\"מ צ\"ל דבעולמות בי\"ע גם בחי' המקום הרוחני הוא בחי' מקום שנתפס באורך ורוחב, וכמארז\"ל מן הארץ לרקיע מהלך ת\"ק שנה\nעובי כל רקיע כו' בין כל רקיע כו', רגלי החיות כנגד כולם שוקי החיות כו', וע\"ה שכ\"ז ענינים רוחני' וכמ\"ש במ\"א בענין ורגליהם רגל ישרה ת\"ק י\"ה כו', מ\"מ צ\"ל שיש בזה ג\"כ תפיסה בגשם וכמו מלאך בשליש עולם עומד הרי שהוא נתפס בגדר העולם, איך שנפרש אם הפי' שהמלאך הוא שליש מהעולם או שהפי' הוא שהעולם הוא שליש מהמלאך הרי מ\"מ הוא נתפס בעולם כו', וכן מובן ממשארז\"ל ברכות ד\"ד מיכאל באחת וגבריאל בשתים כו', והיינו לפי שהעולם תופס איזה מקום לגבי המלאכים לכן מיכאל די לו בטיסה א' וגבריאל בשתים כו', ואלי' שהי' גופו תחלה גשמי מד\"י שבארץ ונהפך לרוחני צריך ארבע טיסות כו', וזהו לפי שהמלאכים הם בגדר מקום מצד הגוף שלהם ע\"כ העולם תופס מקום לגביהם כו'. והתחלת ענין המקום הוא מבחי' מל' והיינו דמבחי' המל' נתהווה בחי' המקום בבי\"ע כו', ולמע' מבחי' המל' לא יש בחי' המקום כו', ומ\"מ יש בחי' מקום גם באצי' רק ששם זהו רק במעלה ומדרי' לא באיזה תפיסה בגדר מקום חומרי ח\"ו. וכמו מעלת החו\"ב זהו מקומם ובזה הם למע' מבחי' ז\"א כו', וכן מע'\nהחסד על הגבו' זהו מקומו כו', והיינו בבחי' הכלים דע\"ס שבזה ניכר מעלת ומדרי' כאו\"א מהספי' וזהו מקומם כו'. והנה כמו שהן בבחי' מקום כמו\"כ הן בבחי' זמן, דכל מה שנתהווה ה\"ז בבחי' זמן דלבד זאת שנתהוו מן ההעדר להוי' הרי הי' זמן שלא היו ונתהוו ונתחדשו כו', א\"כ ה\"ה תחת הזמן כו'. הנה זהו בחי' הזמן בכלל מה שיש לעולם זמן והיינו מה שהעולם וכל מה שנתהווה בעולם ה\"ה הווים ונפסדים כו', וזהו\"ע הזמן מה שנתחדשו הרי לא היו מקודם כו', ומה שיתבטלו אח\"כ וכמ\"ש שמים כעשן כו' וה\"ז ענין הזמן בכלל, אבל משו\"ז אין לומר זמן פרטי כמו שית אלפי שנין כו', דזמן הכללי הוא שהעולמות הן זמניים ולא נצחי' אבל לא יחוייב עדיין משו\"ז התחלקות הזמן הפרטי דשית אלפי שנין כו' (ובענין האור כבד לומר ענין הזמן באופן כזה דע\"ה שהאור ג\"כ קדמו ההעדר ואינו בבחי' גילוי ההעלם כו' וכמ\"ש במ\"א, מ\"מ הרי כשנתהווה האור ה\"ה בבחי' דבקות במקורו וקיומו הוא בבחי' קיום עצמי ויכול להיות שיתבטל ח\"ו, מ\"מ בעת קיומו הוא בבחי' קיום עצמי כו' וכמ\"ש במ\"א), רק ענין\nהתחלקות הזמן העיקר הוא בהאור והחיות שבהנבראים כו'. וכנודע בענין והחיות רצו\"ש דקאי על האור והחיות האלקי שבנבראים שהוא בבחי' רצו\"ש כו', והטעם הוא הא' מפני שהוא"],[3601330511,"הארה לבד ע\"כ הוא בבחי' רצוא תמיד למקורו ובבחי' שוב אח\"כ מפני רצון העצמו' להיות בחי' הגילוי כו', והב' מצד שהתחברות החיות עם מציאות הנברא הוא בבחי' רצו\"ש, כי אא\"ל שיהי' בבחי' התיישבות ממש כ\"א בבחי' רצו\"ש שהוא הסתלקות והתפשטות כו', וגם דהתחדשות החיות הוא בבחי' רצו\"ש כו'. וכנודע דהחיות צ\"ל בבחי' דביקות דוקא, אך האור שבבחי' דביקות ממש אינו בגדר התלבשות בנבראים כו', כ\"א הדביקות הוא ע\"י הרצו\"ש שבזה נתחדש ממקורו כו' וכמ\"ש במ\"א, ומזה נעשה בחי' הזמן דהרי הסתלקות והתפשטות ה\"ז התחלקות בהאור שנמשך ונפסק המשכתו בההסתלקות שלו וחוזר ונמשך כו', מזה הוא שנתהווה ענין הזמן בעולם כו'. וז\"ע עולם ושנה דעולם הוא בחי' עצם המציאות של העולמות והנבראים כו', ושנה הוא בחי' הזמן שלהם דהיינו בחי' הרצו\"ש שבהאור והחיות המתלבש בתוכם כו', ועיקר ענין הזמן הוא בבי\"ע וכן בבחי' המל' מלך מלך ימלוך כו', ובמד\"ר אי' מלמד שהי' סדר זמנים קודם לכן, והיינו בחי' הזמן שבאצי' והו\"ע הקדימה ואיחור שבהע\"ס דבתחלה נאצלה בחי' הכתר ונפסק\nהמשכתו ונאצלה ספי' החכ' כו' (וכמשנת\"ל פ' קנ\"ח) דיש ס' והדרגה באצי' הספי' כו', וכמ\"ש במ\"א שזהו בחי' הזמן כו', ובד\"כ הוא ג\"כ בחי' הרצו\"ש שבהאור וכמ\"ש בס\"י ודברו בהם ברצו\"ש כו' וכמ\"ש במ\"א, שמזה הו\"ע הזמן כו', הרי שכל העולמות הן בבחי' זמן ומקום כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה הממוצע דא\"ק בענין ההתהוות, דהנה כל מה שנתהווה הוא בבחי' מקום, והרוחני אינו בבחי' מקום ה\"ז כמו כמה כחות שהן במוח, ועיקר ענין מקום הוא מעלת הדבר שיש לו תפיסא (א ביטרעף), ובגשמי הוא תואר הדבר, גדר הדומם גדר הצומח, ובנבראים הרוחנים הוא תפיסת מקום שלהם במעלתם בהשגתם ועבודתם, ומ\"מ במלאכים יש מקום דמלאך בשליש עולם עומד, ובאצי' הוא רק במעלה, וכמו\"כ הן בזמן. ולבד מה שקדמם ההעדר ונתחדשו, שזהו שאינם נצחיים (והאור הוא כמו נצחי) הנה התחלקות הזמן מהרצו\"ש שבהחיות, מפני שהוא הארה, ואופן התחברותם הוא ברו\"ש דוקא, וגם דבקותו והתחדשותו ממקורו הוא ברו\"ש, ובאצי' הוא בחי' סדר זמנים בקדימה ואיחור, ודברו בהם ברו\"ש.</span>\nקסט) <b>וכ\"ז</b> שייך בעולמות שהן בבחי' מציאות דבר וע\"כ שייך בהם בחי' המקום כו', וכן שייך בהם בחי' הזמן להיות שהאור הוא שבא בבחי' המשכה ובבחי' התלבשות כו'. אבל עצמות המאציל הוא למע' מגדר זמן ומקום וכמא' מי איכא זקנה קמי' קוב\"ה כו', והיינו שגם בראשית המשכת הקו כמו שהוא למע' מבחי' התלבשות גם בפרצוף דא\"ק ה\"ה למע' מגדר זמן כו', ועמ\"ש בדרוש יו\"ט של ר\"ה רס\"ו באורך איך שבחי' הכתר הוא למע' מבחי' הזמן, משום דהרצו\"ש דשם הוא בבחי' מטי ולא מטי שא\"ז ענין הסתלקות והתפשטות שבבחי' התחלקות כו' יעו\"ש, וכ\"ש שהוא כן בבחי' עתיק דלעילא מגולגלתא דא\"ק כו' (וי\"ל דכללות ענין רצו\"ש והיינו גם בחי' מטול\"מ שייך רק בבחי' חיצוני' הכתר שזהו בבחי' שייכות אל העולמות וההמשכה בזה הוא בבחי' המשכה אל העולמות (דהיינו בחי' הארה לבד כו', דרק בהארה שייך ענין רצו\"ש או מטולמ\"ט דלהיותה רק הארה ה\"ה בבחי' רצוא לגבי מקורה ואח\"כ היא בבחי' שוב כו', ובמדרי' הכתר ה\"ז בבחי' מטולמ\"ט אבל כ\"ז הוא להיותו הארה לבד כו'), וזהו\"ע דרצון שהוא בבחי' מרוצה"],[3601330512,"עכ\"פ ושייך בזה בחי' מטי שהוא בבחי' התפשטות ובחי' לא מטי כו', אבל בבחי' עתיק שזהו בחי' עצמו' שההמשכה בזה א\"ז המשכה אל העולמות כו' (והוא בחי' העתקת העצמות כו', ויובן כן בראשית הקו שבא בבחי' בקיעה שזהו כדוגמת נקודת המל' שבקעה את הפרסא וכמשנת\"ל), י\"ל דבזה אינו שייך כלל ענין מטולמ\"ט כו', ועמ\"ש בד\"ה יו\"ט של ר\"ה הנ\"ל דבעצמו' שייך רק בחי' שוב כו' (והוא בחי' העתקת העצמו' כו'), ועפ\"ז י\"ל דבראשית הקו אינו שייך גם בחי' מטולמ\"ט וממילא א\"ז גם בבחי' גדר מקור לבחי' הזמן כו'). ובכדי שיהי' התהוות האצי' שהוא בחי' ס' זמן מא\"ס ב\"ה שלמע' מגדר זמן, ה\"ז ע\"י שנאצל תחלה בחי' א' ממוצעת בין שני הפכים אלו, והוא בחי' א\"ק ונק' קדמון מפני שקדם לכל האצי' דאבי\"ע (ור\"ל בחי' קדימת המע' שקדם במעלתו ומדריגתו לכל העולמות שאינו בבחי' מציאות דבר כלל עדיין כו', וכמ\"ש בע\"ח דא\"ק נק' א\"ס בהשאלה כו', ומ\"מ יש לו שייכות אל העולמות ורק שקדם להם כו', דענין קדם הוא שכבר ישנו להדבר ומוכן להתגלות רק שלא נתגלה עדיין כו', והיינו שלמע' עדיין\nמהתגלו' אבל יש לזה שייכות אל הגילוי כו'). דהנה ידוע דא\"ק נק' מחה\"ק ועז\"נ צופה ומביט עד סוף כה\"ד וכולם נסקרים בסקירה א', דכל מה שנתהווה בעולמות הכל עלה במח' זו רק שהן שם בבחי' בלתי מציאות ניכרת כלל, וזהו שנק' מח' שמורה ע\"ז שאינו בבחי' מציאות, וכמ\"ש הפרד\"ס בשעה\"כ ערך מחשבה דמח' מורה על הדקות כי אין בגשם יותר דק ממח', ועש\"ז נק' אצי' נקודה מחשבית להראות על הדקות כו', וכמו\"כ בחי' א\"ק נק' מחה\"ק שהוא מח' כללית על כל מה שנתהווה כו'. ובמ\"א מבו' דא\"ק הוא בחי' הסכם שלמע' גם ממח' כו' וכמשנת\"ל פס\"ו, וא\"כ בחי' א\"ק ה\"ז למע' מבחי' זמן ומקום שהרי נתהווה שם הכל בבחי' בלתי מציאו' ניכרת כלל כו', ועמ\"ש בדרוש יו\"ט של ר\"ה הנ\"ל דהספי' כמו שהן בא\"ק (וכן כל מה שנמצא בבחי' א\"ק) אינו גם בבחי' הגדרה מופשטת כו', וע\"כ שם הכל בבחי' השוואה לגמרי כו' וגם לא יש שם קדימה"],[3601330513,"ואיחור כלל כו'. וע\"כ ה\"ז בחי' ממוצעת בין למע' מהזמן והזמן, שהרי בבחי' א\"ק לא יש שם גם בחי' ס' זמנים ומ\"מ בבחי' א\"ק שייך עכ\"פ לו' שיהיו נסקרים בסקירה א' שהיא בחי' מח' א' כו', דע\"ה דמח' א' ה\"ז הוראה דהמח' היא ג\"כ לא בבחי' מח' עדיין כו' (דבד\"כ ענין היחידות שולל ענין המציאות דכל שהוא במציאות אינו בחי' יחידות כו', והיינו שהוא בעצמו אינו בבחי' היחידות דמאחר שהוא בבחי' המציאות ה\"ה בבחי' ריבוי בעצם מהותו כו', וכמו יש לי רב דהיינו בחי' המציאות בעצם ע\"כ אמר יש לי רב כו', וכמו כי רבה כי גדלה דהיינו ריבוי התפשטות הישות כו', דכל שהוא בבחי' מציאות דבר ה\"ה בבחי' ריבוי והתפשטות כו' והיחידות שולל זה כו', הרי דיחידות ומציאות המה הפכים זמ\"ז כו', וגם כל דבר שהוא במציאות הרי יכול להיות עוד דבר שכמוהו מאחר שהוא ג\"כ בבחי' מציאות דבר כו', וכמו היחיד בדורו בהכרח שיש בו דבר שבזה הוא מובדל מכולם וע\"כ הוא יחיד כו'. וא\"כ מה שנק' מח' א' ה\"ז הוראה שאינו בבחי' המציאות כו', והגם דנק' אחת ולא יחיד כו', ה\"ז עכ\"פ כמו\nהעקודים שעקוד בכלי אחד, דמבו' הפי' בזה שהכלי היא בבחי' אחד כו', וכ\"ש שהוא כן בבחי' א\"ק כו'), ומ\"מ ה\"ז בבחי' מח' וסקירה א' כו'. הרי שבא\"ק יש בו הענין דזמן ובלי זמן, שהרי א\"א שאינו בבחי' זמן כלל שה\"ה מ\"מ בחי' סקירה א', וגם אינו בבחי' הזמן שהרי ההתכללות שבו הוא שהן שם בבחי' בלתי מציאות לגמרי ואינו שייך שם קדימה ואיחור כו'. וזהו מה שא\"ק הוא תחלת ההתהוות דנת\"ל שיש בא\"ק ב' ענינים שהוא תחלת ההתהוות ובחי' כוללת כו', והיינו שאינו רק תחלת ההתהוות לבד כ\"א הוא בחי' כוללת שכל מה שיתהווה הכל הוא כלול בא\"ק כו', ואופן ההתכללות בו הוא בבחי' בלתי מציאות לגמרי והיינו שהוא כמו תחלת התהוות דבר שהוא דבר אחד ופשוט כו', וכמו חומר הראשון הנושא הד' צורות כו' וכנ\"ל. ונמצא דבא\"ק יש בו ב' הענינים ע\"כ הוא בבחי' ממוצע כו', דהרי עצמות אוא\"ס ה\"ה למע' מגדר הזמן לגמרי והעולמות הן בבחי' זמן כו', ובחי' א\"ק להיות בו ב' הענינים הנ\"ל ע\"כ זהו מדרי' ממוצעת שע\"י מדרי' זו יהי' מא\"ס ב\"ה שלמע' מגדר זמן לגמרי התהוות בחי' סדר זמנים כו'.\n<b>וע\"פ</b> הנ\"ל יובן מה שהד' ספרים נאמרו מפי שלישי המדבר כו', דהנה לכאו' א\"מ מפני מה אין מבטלין ת\"ת מפני מצוה שאפשר לעשותה ע\"י אחרים, וכמו בהפרשת תרומה שאפשר להיות ע\"י שליח כו', ואיך יעסוק הוא בפי' וביאור המצוה ולא יעסוק בהמצוה עצמה כו', ובפרט שיש מצות שכשנעשים ע\"י אחרים ולא על ידו אין לו המצוה ואיך אין מבטלין כו', ובהכרח לו' שיש מעלה בתורה על המצות. דהנה המצות הן תחת הזמן וכמו מצות מצה בפסח שהוא בזה הזמן דאז נמשכים כל ההמשכות כו', וכן מצות שבת וכה\"ג הכל הוא בזמן דברגע קודם או אחריו לא יש המצוה כ\"א בזה הזמן דוקא כו', וכ\"ה במקום וכמו קרבנות שצ\"ל במקום ההקרבה דוקא ומחשבת חוץ למקומה או חוץ לזמנה פוסל כו'. משא\"כ התורה אינו תחת הזמן שהרי כל העוסק בתו' עולה כאלו כו' גם שאינו זמן ומקום ההקרבה כו', וכן הלומד הל' פסח בסוכות כו', רק שדבר בעתו מה טוב, אבל מ\"מ ישנה לההמשכה כו'. והיינו לפי שהתו' היא בחי' חכ' הקדומה דא\"ק שלמע' מבחי' הזמן ע\"כ גם התורה היא למעלה מהזמן כו', משא\"כ מצות ה\"ה בחי'\nהתגלות שבאו בבחי' התגלות פרטיות ע\"כ הן בבחי' הזמן כו', והגם שבתורה יש ג\"כ בחי' כלל ופרט וכמשי\"ת, מ\"מ כללות התורה היא בבחי' א\"ק כו'. וזהו מה שתורה נאמרה משלישי המדבר דהיינו בחי' א\"ק שזהו בחי' שלישי המדבר ומגלה כו', אבל משנה תורה משה מפי עצמו אמרו, דהנה משנה תורה הוא בחי' התגלות, שהרי כל הענינים שבהד' ספרים הראשונים נאמרו ונשנו במשנה תורה כו', ולהיות שזהו בחי' התגלות ע\"כ נאמרה ממשה מפי עצמו כו', רק התחלת התורה נאמ' אלה הדברים כו', מפי שלישי המדבר כו', וזהו כמו בעשרת הדברות דכתיב וידבר אלקים את כל הדברים האלה, דהיינו שכל התו' היא בכלל העשה\"ד כו', דהיינו דכל מה שנפרט בתושב\"כ וגם בתושבע\"פ הכל כלול בעשה\"ד כו', וזהו כל הדברים האלה כו'. וכמו\"כ כאן נא' אלה הדברים כו' להורות שכל הדברים דמש\"ת ע\"ה שהן בחי' התגלות מ\"מ הכל הי' כלול בבחי' הכלל דא\"ק כו', וע\"כ נא' ג\"כ ההתחלה מפי שלישי המדבר שזהו בחי' הכלל דמחה\"ק דא\"ק כו', גם י\"ל להיות שהתו' הרי גם הפרטים המה עצמי' כו'. וזהו אלה הדברים דמשנה תורה ע\"ה\nשהוא בחי' התגלות ה\"ה אותן הדברים ממש שבבחי' הכלל דא\"ק כו', ע\"כ נא' ההתחלה מפי שלישי המדבר להורות שזהו בחי' הכלל כו', וכל משנה תורה נא' מפי"],[3601330514,"משה להורות שזהו בחי' התגלות כו', רק שההתגלו' הוא כמו העצם כו'. וזהו אלה הדברים אשר דבר משה כו', שהד' ספרים נא' מפי שלישי המדבר שזהו בחי' א\"ק, ומשנה תורה נא' מפי"],[3601330515,"משה להיות שזהו בחי' התגלו' והתחלת משנה תורה נאמר מפי שלישי המדבר, להורות שכ\"ז הי' כלול בהכלל דא\"ק, וכמו שהיו בבחי' הכלל דא\"ק באופן כזה נתגלו מן הכלל אל הפרט כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם בחי' עצמות המאציל עתיק דא\"ק למעלה מגדר זמן, דבכתר הוא מטול\"מ שאינו התחלקות, וי\"ל דזהו באריך, ועתיק להיותו העתקת העצמות אינו שייך גם מטול\"מ, ובכדי שיהי' בחי' הזמן נאצל בחי' א\"ק שכולל הכל בפרטיות ובסקירה א', וזהו שנק' מח' והיא מח' אחת שאינו במציאות, גם לא בהגדרה מופשטת (דיחידות שולל ענין המציאות), וא\"כ הוא זמן ולא זמן, וז\"ע הממוצע. וזהו אלה הדברים שלישי המדבר, מצות תחת הזמן, ותורה עם היותה פרטים ה\"ה למעלה מהזמן.</span>"],[3601330516,"<h3>בס\"ד. ש\"פ ואתחנן, תער\"ג</h3>\n<b>ואתחנן</b> אל הוי' כו' אתה החלות להראות את עבדך את גדלך כו' אעברה נא ואראה כו', וצ\"ל מהו\"ע ואראה את הארץ שע\"ז היו כל הבקשות של משה, וכידוע שלא בקש לישב בארץ כ\"א לראות את הארץ, ומהו\"ע ראיית הארץ שהרבה כ\"כ בקשות ע\"ז דתקט\"ו תפלות התפלל משה כו', ומהו\"ע אעברה נא כו'. גם מהו\"ע שמקדים לזה את גדלך כו' מהו אריכות ההקדמה כו', ומהו\"ע אתה החלות כו'. גם מש\"א להראות את עבדך צ\"ל דלא מצינו כן בשארי תפלות של משה שיהיו בדרך שפלות כ\"כ, והגם שהי' ענו מאד כו' מ\"מ התפלות שלו היו בדרך תביעה כו', וכאן או' בדרך שפלות כו'. גם מ\"ש ואתחנן ולא א' ואתפלל כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דא\"ק הוא בחי' ממוצע בין אוא\"ס להעולמות כו', וענין הממוצע הוא בשני דברים, הא' שהוא ממוצע בב' מדרי' שבו בחי' פנימי' א\"ק וחיצוני' א\"ק, דבחי' פנימי' שבו הוא ראשית הקו שכדוגמת עתיק כו', דע\"ה שזהו בחי' או\"פ מ\"מ ה\"ה בבחי' הבדלה לגמרי מן העולמות כו', ובחי' חיצוני' א\"ק הוא בבחי' כלל אל העולמות כו', הב' שהוא ממוצע בענין ההתהוות כו', דהתהוות\nהעולמות הוא בבחי' כלל ופרט כו' ובחי' א\"ק הוא בחי' הכלל של העולמות כו', והיינו שאינו רק ראשית ההתהוות שהוא ראשית המציאות כו', כ\"א הוא בחי' כלל שכולל כל מה שיתהווה אח\"כ כו', אך הכל כלול בו שלא בבחי' מציאות כלל כו', ובזה הוא בבחי' ממוצע כו'. ונת' בענין הזמן דכל מה שנתהווה הכל הוא תחת הזמן כו', ובא\"ק לא יש בחי' הזמן מאחר שאינם בו בבחי' מציאות כו', ומ\"מ אינו למע' מהזמן לגמרי שה\"ה עכ\"פ בחי' מח' א' כו', ונמצא שהוא בבחי' זמן ולא בבחי' זמן כו', ע\"כ הוא בחי' ממוצע בין האוא\"ס שלמע' מגדר זמן לגמרי ובין התהוות העולמות בבחי' ס' זמנים וזמן כו'.\nקע) <b>ועפ\"ז</b> יובן מ\"ש בזהר קוב\"ה אסתכל באורייתא וברא עלמא, אורייתא היא בחי' חכ' דא\"ק כו', דעל התו' כתי' כאשר יאמר משל הקדמוני שהיא"],[3601330517,"משל לא\"ס קדמונו של עולם, דכמו המשל הוא לבוש אל הנמשל כמו\"כ בחי' חכ' דא\"ק הוא בחי' לבוש לאוא\"ס ב\"ה כו'. ומה שנק' בשם משל הוא להורות דהאוא\"ס המתלבש בחכ' דא\"ק א\"ז רק הארה לבד כ\"א הוא בחי' אור עצמי כו'. וכמו המשל שמהות הנמשל מתלבש בו רק שמתעלם בתוכו אבל מ\"מ הוא מהות הנמשל כו', וכמ\"ש בתו\"א ד\"ה פתח אליהו ההפרש בין צמצום לפרסא, דצמצום הוא בחי' סילוק האור וממילא האור הנמשך עי\"ז ה\"ז רק הארה לבד כו', אבל פרסא הוא שמהות האור מתעלם בו כו', וכמו המשל שמהות הנמשל מתלבש כו'. וכמו\"כ הוא בחי' חכ' דא\"ק שמתלבש בזה בחי' עצמו' א\"ס כו' (ועמשנת\"ל פקל\"ז). וזהו קוב\"ה אסתכל באורייתא דקוב\"ה הוא בחי' עצמו' א\"ס בחי' כדוגמת עתיק כו' שלמע' מע' מבחי' הכלל דא\"ק, והוא אסתכל באורייתא שהוא בחי' א\"ק אור כללי ועי\"ז ברא עלמא כו'. והענין הוא דהנה גם בתורה יש בחי' כלל ופרט, דהרי כל הפרשיות שבתורה ה\"ה ע\"פ הדבור דוקא וכמ\"ש בכל פרשה וידבר ה' אל משה כו', והדבור הוא בחי' פרט וכידוע בענין מחו\"ד דמח' הוא כלל ודבור פרט כו', ופרטי\nהדבור דתו' הוא ההמשכה פרטי' בע\"ס דאצי' כו'. וזהו שברוב הפרשיות נא' וידבר ה' אל משה דבר אל בנ\"י לאמר, וידבר הוא ל' הנהגה והמשכה כמו ידבר עמים כו', הוי' הוא חכ' דאצי' הכולל ע\"ס דאצי' וכמ\"ש והוי' בחכ' כו', דעיקר ש' הוי' הוא בחכ' כו', דאצי' בכלל הוא ש' הוי', דזהו ההפרש בין אצי' לבי\"ע דאצי' ש' הוי' ובי\"ע ש' אד' וש' אלקים כו', ובאצי' גופא ש' הוי' הוא בחכ' מפני שחכ' כוללת כל הע\"ס וכל ההשפעות שבאצי' הוא ע\"י החכ' כו', ע\"כ נק' החכ' ש' הוי' היינו שהיא עיקר האצי' כו' וכמ\"ש במ\"א ועמשנ\"ת לעיל פרק הנ\"ל. אל משה הוא יסוד אבא דאצי' (דההשפעה הוא מבחי' היסוד כו', וענין ההמשכה מש' הוי' אל משה, דלכאו' מאחר דמשה הוא בחי' יסוד אבא א\"כ מהו ההמשכה מהחכ' אל היסוד כו', י\"ל דהנה ידוע דיסוד שבשכל שרשו מבחי' קדמות השכל וכמ\"ש אשרי משכיל אל דל, דל הוא בחי' יסוד כנודע, ושרשו הוא מבחי' משכיל דוקא כו', משום דההשפעה אל הזולת הוא מכח עליון דוקא כו'. דהנה ידוע דבכדי להשפיע אל הזולת צ\"ל השכל אצלו בבחי' התיישבות ובבחי' תפיסה\nבכלי מוחו ביותר, שזהו דוקא ע\"י העומק ופנימי' הענין דכאשר יודע את השכל בעומקו ופנימיותו אז הוא אצלו בבחי' התיישבות היטב כו', גם צריך להמציא ענינים והסברים במה להסביר הענין אל הזולת, וכמו\"כ צריך לשנות את השכל שיהי' לפ\"ע המקבל כו', כי השכל כמו שהוא אצלו ה\"ה למע' עדיין משכל המקבל ולא יבין אותו ע\"כ צריך לשנותו שיבא השכל באופן אחר מכמו שהוא אצלו ויהיה לפ\"ע המקבל כו', ובכדי לשנות הענין ולהמציא ענינים הנ\"ל צריך ג\"כ לידע עומק ופנימיות הענין, ועוד צריך לבא לעומקו יותר מבכדי התיישבות הנ\"ל, והעיקר שצ\"ל בזה התעצמות הענין והוא שהענין שכלי יתעצם אצלו ואז יכול לעשות עמו מה שירצה ולשנותו בכמה אופנים שונים כו'. ובאמת בכדי לשנות הענין ובפרט בכדי להמציא ענינים זהו מכח המשכיל דוקא, שמשם נמשך השכל גלוי ומשם נמשך ג\"כ המצאת הענינים במה להביא את האור שכל אל הזולת, דדוקא מי שביכולתו להמציא שכל חדש ביכולתו ג\"כ להמציא ענינים במה להביא כו', ובכח המשכיל גופא זה בא מעומק כח המשכיל יותר, כי יותר בנקל להמציא שכל חדש\nמלהמציא ענינים לאור שכל שכבר בא בגילוי כנראה בחוש, והיינו שזה בא מעומק ופנימי' כח המשכיל יותר כו'. הרי"],[3601330518,"שבכדי להשפיע שכל אל הזולת צריך להגיע בשכל זה בעומקו ביותר, וגם צריך להמשיך לזה שכל חדש מכח המשכיל מעומקו ופנימיותו כו', וזהו דאי' בע\"ח דנה\"י החדשים נמשכים מן הכתר כו', והיינו בהגדלת ז\"א דנה\"י נעשה חג\"ת וחג\"ת נעשה חב\"ד כו' נמשכים נה\"י חדשים מהכתר שזהו מבחי' פנימי' הכתר כו'. ועד\"ז י\"ל כאן דענין וידבר הוי' אל משה זהו ההמשכה מבחי' פנימי' ועצמי' ח\"ע בבחי' יסוד אבא כו', וי\"ל שזהו בכדי שיהי' ההמשכה בבחי' מל' שהוא בחי' תושבע\"פ כו' וכמ\"ש במ\"א בהביאור דחגרה בעוז מתני' כו'). דבר אל בנ\"י הן בחי' נו\"ה דאצי' כי ישראל הוא ז\"א דאצי' ובני ישראל הן נו\"ה כו', ובמאו\"א אות ב' סנ\"ב כ' בנ\"י נ\"ה בני הת\"ת הנק' ישראל. לאמר אל בחי' מל' דאצי' מקור דבי\"ע כו', וזהו מ\"ש בכל פרשה וידבר ה' אל משה כו' שזהו ההמשכה דבאוא\"ס כמו שנמשך ומשתלשל בפרטי הע\"ס דאצי' עד בחי' מל' דאצי' וע\"י המל' נמשך גם בבי\"ע כו', והענין המבו' בהפרשה זהו האוא\"ס הנמשך ומתגלה כו', והיא המצוה פרטי' המבוארת בהפרשה או הספור דברים שבה, שכ\"ז הוא המשכה\nמאוא\"ס ב\"ה ונמשך בפרטי המדרי' דאצי' וע\"י מל' דאצי' נמשך גם בבי\"ע כו', שעי\"ז נעשה בנין ותיקון העולמות לפי אופן פרטי ההמשכה שבאותה הפרשה כו'. דמתחלה הרי התהוות העולמות הוא ע\"י התו' ואח\"כ ממשיכים תוס' אורות בעולמות, וכידוע דתכלית הכוונה בבריאת והתהוות העולמות הוא להמשיך אוא\"ס בעולמות שזהו ע\"י התורה, וכמארז\"ל תנאי התנה הקב\"ה במע\"ב אם יקיימו ישראל את תורתי כו' והיינו שע\"י התו' נשלמה הכוונה בהמשכת תוס' אורות כו', וזהו שת\"ח נק' בנאים שהם בונים את העולם היינו שממשיכים תוס' אור בעולמות כו', ולא דברו חכמים אלא בהוה שע\"י דבור התו' נעשה ההתהוות וכן התוס' אורות כו', וזהו\"ע הדבור דתו' היינו מה שבאה בהתגלות בבחי' פרט באבי\"ע כו'. וגם הרי התו' נמשך ונדבר בבחי' זמן פרטי דפ' ומצוה זו נא' בזמן פלוני ופ' זו בזמן אחר, וכמ\"ש ויכתוב משה את כל דברי ה' ופרש\"י מבראשית עד מ\"ת ומצות שנצטוו במרה, ובהרבה פרשיות נא' בתו' גופא הזמן וכמו בשנה השנית בחדש הראשון, בחדש השני כו', וכמו\"כ כל הפרשיות נא' בזמן מיוחד כו', ובד\"כ\nפ' נח נכתבה ונאמרה על זמן המבול ונח, ופ' לך לך כו' על הזמן דאברהם כו', וכן כל הפרשיות של מצות הרי נא' בחילוקי זמנים ובפרט ספורי מעשיות שבה שהיו רק לפי הזמן כמו פ' קרח ופ' בלק וכיוצא בזה, ונת\"ל פ' קס\"ח דבחי' הזמן הוא בעולמות בי\"ע ובאצי' הוא בחי' ס' זמנים, וא\"כ דבור העליון דתו' הוא שבא ונשתלשל בבחי' זמן וס' זמנים כו'. אכן זהו ההמשכה דרך פרט, אבל שרשה הוא בחי' מחה\"ק שהוא בחי' א\"ק בחי' אור כללי ונכללו כל פרשיות התורה יחד, אע\"פ שלמטה ניתנו בזמנים חולפים כו' מ\"מ שם נכלל הכל יחד, שהרי שם נכלל כל הזמן דשית אלפי שני דהוה עלמא וימוהמ\"ש ותחה\"מ הכל בסקירה א' כנ\"ל פ' קס\"ט, וע\"כ גם התו' כמו שהיא שם נכלל הכל יחד כו', ומשם נסעה התורה ונמשכה באבי\"ע בבחי' המשכה דרך פרט כו'. וזהו שיש ב' דעות בגמ' אם תו' חתומה ניתנה או מגילה מגילה ניתנה, דשניהם אמת, דמ\"ד תורה חתומה ניתנה היינו כמו שהתו' היא בשרשה בחכה\"ק דא\"ק שהיא שם בבחי' כלל ונק' מא' סתום שלמע' מבחי' הגילוי וזהו חתומה ניתנה כו', ומ\"ד מגילה מגילה ניתנה זהו\nכמו שהתו' באה בהתגלות באבי\"ע שכל פרשה ופרשה נאמרה בזמן מיוחד והוא המשכה מיוחדת כו', וזהו מגילה מגילה ניתנה כו'."],[3601330519,"<span data-k=\"ks\"><b>קיצור.</b> וזהו קוב\"ה עצמות א\"ס עתיק דא\"ק, אסתכל באורייתא חכ' דא\"ק חכ' דתורה, משל הקדמוני שעצם הנמשל מלובש בזה, דבתורה יש כלל ופרט, פרט הוא הדבור דתורה, וידבר המשכה, הוי' חכ' אצי' שבאצי', אל משה יסוד אבא. וי\"ל שזה\"ע משכיל אל דל, יסוד שבשכל להשפיע ולשנות הענין שזהו ע\"י שהענין מתעצם אצלו, ולהמציא ענינים זהו מעומק השכל ומכח המשכיל, ולמעלה מהמצאת השכל בתחלה. אל בנ\"י נו\"ה, לאמר מל' שיהי' הגילוי בבי\"ע, והדבור וההמשכה הוא האוא\"ס שבפרשה, שכך יהי' בנין ותיקון העולם, ת\"ח בנאים, והכל נא' בזמן, ובמחה\"ק שבא\"ק היא בבחי' כלל, וזהו תורה מגילה ניתנה פרט, חתומה ניתנה חכ' הק' בחי' כלל.</span>\nקעא) <b>ולהבין</b> ב' המדרי' שבתורה, הנה כתיב זמירות היו לי חוקיך, וארז\"ל דוד זמירות קרית להו, שנענש ע\"ז כו', וידוע הענין דדוד הי' משבח את התו' במה שכל חיות וקיום העולם תלוי בדקדוק א' מדקדוקי התו' שהרי תנאי התנה הקב\"ה במע\"ב אם יקיימו ישראל את תורתו כו', הרי כל חיות וקיום העולם תלוי בקיום התורה כו'. וגם שעי\"ז נמשכים תוס' אורות וגילוים בעולמות, וכמו שע\"י קרבנות נעשה עליות העולמות דרזא דקורבנא עולה עד רזא דא\"ס, דקרבן הוא ל' קירוב והו\"ע קירוב הכחות והשמות כו' כמ\"ש הבחיי, ועי\"ז נמשך תוס' אור וחיות בעולמות וכמ\"ש ריח ניחוח להוי' שנמשך תוס' אור בש' הוי' ובכל העולמות כו'. וזהו שבזמן בהמ\"ק הי' מאיר גילוי אלקות וכמו העשרה נסים שהיו בבהמ\"ק כו', וכמארז\"ל כשם שבא ליראות כך בא לראות כו', ובפרט בקה\"ק שהי' מאיר גילוי אוא\"ס ממש, דמקום הארון אינו מן המדה כו', דכ\"ז הוא ע\"י הקרבנות כו'. וכ\"ז הוא דוקא כשהקרבן נעשה כתיקונו, אבל אם יש בו איזה פסול הרי בטלה כל ההעלאה וההמשכה כו'. וכ\"ה במצות תפילין שעי\"ז\nנמשכים מוחין לז\"א, דד' בתים הן ד' מוחין כנודע, דהנה ז\"א הו\"ע מדות עליונות השייכים לעולמות כו', ומוחין הן גילוי לעצמו כו', והגילוי לעצמו וגילוי לזולתו ה\"ה רחוקים מאד זמ\"ז כו', הרי שע\"י התפילין נמשך תוס' אורות בעולמות, אך זהו דוקא כשהתפילין הם כתיקונם ע\"פ התו' בהקלף ודיו ובהכתיבה ובעשייתן כו', משא\"כ כשיש בהם איזה פסול הרי בטל כל ההמשכה כו', וכ\"ה בכל המצות שע\"י נמשך תוס' אור וחיות בעולמות ודוקא כשנעשו כתיקונם כו'. ובזה הי' דוד משמח נפשו בעת צרתו שהי' לא טוב לו בגשמי' דמאחר שכל העולמות תלוים בדקדוק א' דתו' הרי אינם תופסים מקום כלל לגבי התו' כו', וע\"כ גם אצלו לא היו הענינים תופסים מקום כלל ע\"י אור התו' שהאיר בנפשו כו' ואדרבה הי' בשמחה מהאור דתו' כו'. ובילקוט שה\"ש ע\"פ עת הזמיר הגיע אי' בשם המכילתא הגיע זמנה של ערלה ליזמר, הגיע זמן שתעשו לי זמירה שנא' עזי וזמרת י\"ה, הגיע זמנה של תו' להנתן דכתי' בה זמירות היו לי חוקיך, וכ\"ה במד\"ר שה\"ש ע\"פ הנ\"ל, וא\"כ י\"ל זמירות מל' לזמר עריצים וכמו הגיע זמנה של\nערלה כו', והיינו שע\"י הזמירות בעסק התו' עי\"ז זומר העריצים ומכרית הקלי' המסתירים כו', וע\"ד רוממות אל בגרונם ועי\"ז וחרב פפיות כו', שצ\"ל חרב של שתי פיות כו'. והענין הוא דהנה נודע דיניקת החיצונים יכול להיות על ב' אופנים או שמגביהים עצמן לקבל מבחי' מקיף עליון וכמ\"ש אם תגביהי כנשר כו' וכתי' דרך הנשר בשמים, דמבחי' חיצוני' המקיף יכולים לקבל משום דשם"],[3601330520,"כחשיכה כאורה שהכל יכולים לקבל כו', או שמקבלים מריבוי הצמצום והיינו בסוף כל ההשתל' בריבוי הצמצום ביותר שיכולים ג\"כ לקבל כו', דמבחי' גילוי אור א\"א להם לקבל דהרי אין אני והוא יכולים לדור כו', וידוע ג\"כ דבבחי' גילוי אור צ\"ל כלים אל האור וממילא אינם שייכים שאינם בגדר כלים כלל כו', רק מריבוי הצמצום שאין שם גילוי אור יכולים לקבל כו', וגם יכולים מבחי' מקיף עליון יכולים לקבל, וג\"ז לא מבחי' גילוי המקיף וכנודע דמקיף בכלל הוא בבחי' העלם כו'. וע\"כ צ\"ל חרב של שתי פיות להכרית יניקתם מב' האופנים וכמ\"ש ואשמיד את פריו ממעל ואת שרשיו מתחת, ואשמיד את פריו ממעל הוא שלא יקבלו מהמקיף עליון ואת שרשיו מתחת שלא ינקו מריבוי הצמצומים כו', וכ\"ז נעשה ע\"י נש\"י. דהנה כתי' יעקב חבל נחלתו ועד\"מ החבל שקצהו העליון קשור למע' וקצהו התחתון למטה הרי כשמנענעים קצהו התחתון מתנענע גם קצהו העליון כו', וכמו\"כ נש\"י ע\"י עבודתם למטה פועלים באופן כזה למע' כו', וכמו ע\"י התפלה שמוסרים פנימי' רצונם וחפצם לאלקות כו', והוא ע\"י השגה\nוהתבוננות אלקי גם בהתבוננות בענינים שע\"פ טו\"ד, והיינו כשמתבונן ומשיג את הענין האלקי עד שיונח אצלו הענין היטב במוחו (עס לייגט זעך א(דער ענין זייער גוט במוח) וגם נרגש בלבו (עס ווערט גוט דערהערט בלב), ה\"ה מתקרב מאד לאלקות (ער ווערט זייער צו גיצויגין) שכל חפצו ורצונו הוא באלקות כו', וזהו מפני שע\"י השגת הענין האלקי נרגש אצלו העילוי והיוקר דאלקות כו', ועי\"ז נעשה הרצון שכל רצונו הוא באלקות כו' (ויש בזה חילוקי מדרי' דיש מי שהרגש העילוי והטוב בא לאחר ההשגה, והוא כאשר בההתבוננות בהשגת הענין עם היות שהיא השגה טובה הנה בשעת ההתבוננות אצלו התגברות ההשגה עצמה יותר מהרגש האלקות מה שמשיג (דהיינו ההרגש שהוא משיג בזה ענין אלקי כו'), ואז הרגש העילוי דאלקות בא אח\"כ, והיינו שאחר ההשגה בא הרגש העילוי והעיקר בזה ההרגש איך שקרבת אלקים לי טוב כו', והוא הרגש הבכן הבא לאחר ההשגה כו', ובמדרי' העליונה יותר הוא שבעת ההשגה נרגש אצלו האלקות שמשיג ומתבונן כו', ואז בעת ההשגה נרגש העילוי והטוב דאלקות ונעשה הרצון לאלקות\nכו' ועמשית\"ל פקע\"ז), ובפרט כשהעבודה היא בבחי' פנימי' הלב שזהו ג\"כ עבודה שע\"פ טו\"ד רק שזהו בחי' פנימי' המוחין ופנימי' המדות כו', וביותר בבחי' התגלות רעו\"ד שז\"ע רוממות אל בגרונם דהיינו ההתבוננות בההפלאה והרוממות דאוא\"ס ב\"ה דמזה הוא התגלות בחי' רעו\"ד כו', שעי\"ז נעשה פנימי' הרצון שלו לאלקות כו'. וזה פועל למע' דבחי' פנימי' הרצון דהיינו פנימי' המקיף יומשך בבחי' פנימי כו', וממילא גם חיצוני' המקיף נמשך בפנימי' וכידוע דהחיצוני' נגרר אחר הפנימי' כו', וממילא א\"א להם לקבל מבחי' המקיף מאחר שנמשך בפנימי' כו', ועי\"ז גופא א\"א להם לקבל גם מריבוי הצמצומים, דכאשר המקיף מאיר בפנימי ה\"ז גילוי אור רב שמאיר בכל מדרי' הפנימי' גם במדרי' התחתונות כו', דהאו\"פ הרי מתצמצם ומתמעט ממדרי' למדרי' עד שבבחי' מל' אינו מאיר גילוי אור ע\"כ בריבוי הצמצומים המשתלשלים מבחי' מל' יכול להיות יניקה (ועמשנת\"ל פקמ\"ג), אבל האו\"מ הרי נמשך בכ\"מ, וכאשר המקיף מאיר בפנימי ה\"ה מאיר בכל המדרי' גם במדרי' התחתונות, וע\"כ א\"א להיות יניקה גם\nבמדרי' התחתונות. גם י\"ל שע\"י גילוי המקיף בהפנימי מאיר האו\"פ גם במדרי' התחתונות כו', וי\"ל שז\"ע שהמקיף נותן כח בפנימי והיינו שהאו\"פ יהי'"],[3601330521,"בבחי' תוקף הגילוי בתחלת המשכתו היינו במדרי' העליונות, וע\"כ מאיר גילוי האור גם במדרי' התחתונות כו'. ובעבודה ענין גילוי האו\"מ י\"ל שז\"ע תמים במעשיו שגם העשי' היא בבחי' תמימות כו' ועמשנת\"ל פ' פ\"ב, וענין גילוי האו\"פ הוא כענין בכל דרכיך דעהו, שזהו ע\"י שבמוחין הוא גילוי אור עליון יותר כו', גם י\"ל כענין ומקדשי תיראו בלק\"ת ד\"ה את שבתותי תשמרו, ועמשי\"ת בפרק שאח\"ז. ולכן עי\"ז נכרת יניקתם מב' האופנים שאין יכולים לקבל מהמקיף וגם לא בסוף ההשתל' כו', וכ\"ז הוא ע\"י נש\"י כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והענין דהנה כתי' זמירות היו לי חקיך, שכל חיות העולמות והגילוים בהם תלוי בדקדוק א' דתורה, ובזה משמח נפשו בעת צרתו, ובילקוט מפ' ל' כריתה, והיינו כריתת החיצונים, דיניקתם היא מחיצוניות המקיף ומריבוי הצמצומים, וצ\"ל חרב של שתי פיות, והוא ע\"י שנש\"י פנימיות רצונם באלקות, ע\"י התבוננות והנחה טובה שנרגש העילוי עם בהבכן או בההתבוננות, ובבחי' פנימיות הלב וכ\"ש בבחי' רעו\"ד, נמשך המקיף בפנימי, ומאיר גם במדרי' התחתונות, וכמו תמים במעשיו, גם האו\"פ מאיר בכ\"מ וכמו בכל דרכיך דעהו.</span>\nקעב) <b>והנה</b> גם זאת מה שיכולים לקבל מב' האופנים הנ\"ל ה\"ז ג\"כ תלוי בנש\"י, דהנה ע\"י ההתנשאות והגיאות וע\"י התגברות הישות עי\"ז נעשה למע' שהקלי' מנשאים עצמן לקבל מהמקיף עליון כו', וע\"י הירידה וההשפלה שמשפיל את חלק הרע שבגופו באהבות זרות ותאוות רעות ה\"ז גורם למע' הירידה כבי' בהאור האלקי בריבוי הצמצום וריבוי העלמות והסתרים כו', וכמ\"ש וישח אדם וישפל איש דע\"י וישח אדם למטה שמשפיל חלק הרע שבגוף כו', עי\"ז וישפל איש כבי' הירידה והשפלות דהאור האלקי בריבוי צמצומים והעלמו' כו'. והגם שע\"פ ס' השתל' ע\"פ מא' קו המדה נמשך להם ג\"כ יניקה מריבוי הצמצומים דז\"ש ואתה מחי' את כולם גם לקלי' וסט\"א כו', הנה לבד זאת שנמשך להם תוס' יניקה כו', וכמובן ממ\"ש בע\"ח שער מיעוט הירח ההפרש בין המיעוט הנעשה ע\"י קטרוג הלבנה וע\"י חטא עה\"ד, דע\"ה דבשניהם נשארה בחי' המל' רק נקודה א' שהיא הנקודה השרשית כו', הנה בעת הקטרוג נסתלקו הט\"ס ועלו למע', וע\"י חטא עה\"ד ירדו הט\"ס במקום הקלי' כו', הרי שע\"י החטא נמשך תוס' יניקה כו'. הנה יש\nבזה ענין גרוע יותר שעי\"ז פועלים למע' שהצמצומים נעשים כמו הכרחי כבי', דהנה הצמצומים שע\"פ ס' השתל' הרי כ\"ז הוא צמצום רצוני שא\"ז צמצום, וכנודע דהגבלה רצונית אינו הגבלה וכמו\"כ צמצום רצוני אינו צמצום כו' וכמ\"ש במ\"א, הרי בכל הצמצומים שמצמצם עצמו איך שמצמצם עצמו ובכל מקום שמצמצם את עצמו כבי' אפי' במדרי' היותר תחתונות הרי א\"ז הכרחי ח\"ו כ\"א רצוני כו', אבל ע\"י החטא גורמים שהצמצום יהי' כבי' כמו הכרחי, הגם דענין הכרחי אינו שייך למע', מ\"מ מצד ההתקשרות שנתקשר בנש\"י (וואס מיא האט זיך פארבונדן כבי') הנה כפי אופן הפעולות דנש\"י למטה פועלים למע' כו', וה\"ז ח\"ו כמו שמכריחים כו', וכמארז\"ל לא דיין לרשעים כו' אלא שמטריחין אותו ומחתימין אותו בע\"כ, ופרש\"י גזירה היא מלפני כו' והיינו מצד ההתקשרו' כו'. וענין ההכרחי ה\"ז גרוע מאד, דז\"ע מלך עלוב וכמ\"ש בסש\"ב ס\"פ כ\"ד וכמ\"ש והוא אסור בזיקים כו', דעל ענין ההכרחי ח\"ו ע\"ז צ\"ל מרירות הנפש ביותר דהיינו בזמני המרירות כמו בתיקון"],[3601330522,"חצות צ\"ל ע\"ז מרירות יתירה והו\"ע גלות השכינה כו', דהרי הצמצום שע\"פ ס' השתל' הגם שנמשך חיות לסט\"א א\"ז ענין הגלות לפי שאינו הכרחי כו', וענין הגלות הו\"ע ההכרחי ח\"ו שגורמים למע' והו\"ע נתנני בידי לא אוכל קום כו'. שע\"ז צ\"ל מרירות הנפש ביותר שיעשה חשבון בנפשו ויתבונן בזה היטב (גוט איבער רעכענען זעך) ויתמרמר בנפשו שעי\"ז הוא היציאה דהאור האלקי, וכמו בתשו' שהוא ל' השבה דהאור האלקי שירד במקום הקלי' ה\"ה משיב אותו שמוציאו מהקלי' ומעלהו כו', וכמו\"כ ע\"י שמתבונן היטב בזה ומתמרמר בנפשו שהענין נוגע לו בפנימי' נפשו ה\"ה מוציא את האור האלקי כו', ואח\"כ בתפלה שמאיר אצלו גילוי אור בנפשו שכל פנימי' רצונו וחפצו באלקו' עי\"ז פועל הכריתה שלהם בב' האופנים כו' כנ\"ל, וכ\"ז הוא ע\"י התפלה, וכ\"ש שנעשה כן ע\"י התו' דלהיות שהתו' היא בחי' חכ' עי\"ז נמשך המקיף בפנימי כו'. דז\"ש אם תגביהי כנשר משם אורידך נאום הוי' דהוי' בחכ' כו', דכאשר המקיף נמשך בהפנימי א\"א להם לקבל מהמקיף כו', וכמו\"כ א\"א לינק מריבוי הצמצומים כו' וכמשנת\"ל פקע\"א.\n<b>וזהו</b> שמ\"ת הי' באל\"ף אנכי הוי' אלקיך כו', דברה\"ע הי' בבי\"ת, ואי' בזהר הטעם משום דא' ר\"ת ארור ויכול גם ארור כנען לקבל כו', וע\"כ הי' ברה\"ע בב' ר\"ת ברכה כו', ומ\"ת הי' באל\"ף להיות כי ע\"י התו' גם הא' נמשך בבחי' פנימי ע\"כ א\"א להם לקבל כו', ובתו' גופא הכריתה מב' האופנים הוא ע\"י מ\"ע ומל\"ת, דע\"י שמירת מל\"ת נכרת יניקתם מריבוי הצמצומי' וע\"י מ\"ע נמשך המקיף בפנימי כו', וכ\"ה ע\"י התו' בכלל כו'. וזהו דדוד בעת צרתו בגשמי' אמר זמירות היו לי חוקיך כו', דהנה סיבת הלא טוב בגשמי' זהו ג\"כ מצד הקלי' וסט\"א כו', דכאשר מאיר גילוי אור האלקי אז נמשך ריבוי השפעה בגשמי' ג\"כ, וכמו בזמן ביהמ\"ק שהי' מאיר גילוי אלקו' הי' ריבוי השפעה בגשמי' ג\"כ שהי' איש תחת גפנו ואיש תחת תאנתו כו', והלא טוב בגשמי' זהו מחמת ריבוי ההעלמות וההסתרים שמצד הקלי' כו', וז\"ש דוד זמירות היו לי חוקיך דלבד זאת שלגבי התו' אין דבר בעולם תופס מקום כלל כו', הרי ע\"י התור' הוא כורת ומזמר את הקלי' והחיצונים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> גם את העולם נתן בלבו של אדם, שע\"י הגיאות וע\"י השפלות באהבות זרות גורמים ב' היניקות, בתוס' יניקה, וגם שהצמצומים מצ\"ע הוא צמצום רצוני דבאמת אין זה צמצום והגבלה, ובהשפלות הנ\"ל גורמים כאלו הוא הכרחי ח\"ו, והו\"ע מלך עלוב, וצ\"ל מרירות הנפש, ומסירת הרצון בתפלה, וכן ע\"י התורה נמשך המקיף בפנימי, ובד\"פ השתי פיות הוא מ\"ע ומל\"ת.</span>\nקעג) <b>והנה</b> אמרז\"ל דוד זמירות קרית להו כו', דהנה מה שכל חיות העולמו' תלוי בתו' זהו בחי' חיצוני' התו', והיינו כמו שהתו' באה בד\"פ באצי' שבה וע\"י הוא בנין ותיקון העולם כו', דלגבי מדרי' זו תופס מקום האור והחיות של העולמו' כו', אבל עומקה ופנימיותה היא מיוחדת לגמרי באוא\"ס המלובש בה בתכלית היחוד ולגבי אוא\"ס ב\"ה הרי כל העולמו' כלא ממש כו', כמו\"כ הוא לגבי פנימי' התו' כו'. וכדאי' במד\"ר ע\"פ לכל תכלה ראיתי קץ לכל יש סיקוסים היינו גבול ומדה, אבל התו' אין לה סיקוס כו', דכל בחי' תענוג שבעולם הכל הוא בבחי' הגבלה לפי שזהו הארה לבד וע\"כ יש לה קץ וגבול כו' (וכמו כל אור הרי יש הגבלה להתפשטותו וגם אור אבוקה יש לה קץ כמה שמגיע וגם באור השמש יש חילוקים"],[3601330523,"אם בקירוב או בריחוק כו', וכמו\"כ הוא הדוגמא למע' דכל הארה ה\"ה מוגבלת בהמשכתה שיש בה חילוקי מדרי' באופן הגילוי ומסתיים המשכתה כו'), אבל התענוג שבתו' אין לה קץ וגבול להיותה בבחי' תענוג עצמי כו'. וע\"ה שהתו' הוא או\"פ מ\"מ אין בה הגבלה כלל לפי שהוא תענוג עצמי כו' (דבאמת יש בחי' תענוג העצמי גם בהתו' שירדה למטה כו', רק שבתו' שלמטה א\"ז מאיר בגילוי כו'), וע\"כ כל בחי' חיות ועונג שבעולם הוא כלא ממש לגבי התו' בפנימיותה שהוא בחי' התענוג שבה כו' (אבל לגבי התו' כמו שהיא למטה דהיינו חיצוני' התו' הגם שיש בה ג\"כ התענוג העצמי, מ\"מ א\"ז מאיר בגילוי וע\"כ האור והחיות של העולמו' תופס מקום כו', והתגלו' בחי' תענוג העצמי בתו' למטה הוא ע\"י הבירורים דוקא כו', והעיקר הוא בהבירורים שבתו' עצמה כו'. דהנה יש בירורים שמבררים בכח התו' וכמו ר\"י כולהו תנויי בנזיקין הוה שזהו לברר בירורי' כו' כנודע, אך זהו מה שהתו' מבררת בירורים בעולם כו' (וזה ג\"כ למע' הרבה מהבירורי' דתפלה כמ\"ש במ\"א), ויש בירור שהתו' מתבררת בזה והו\"ע מאן דדייק\nבמלין דחוכמתא כו', והו\"ע הקושיות ותירוצים שזהו הבירור דתו' עצמה כו', דאופן הלימוד בזה הוא לאמת אמיתי' התו' כו', והיינו שא\"ז בכדי להמשיך אור בנפשו כ\"א לאמת כו', וכמ\"ש מזה באורך בד\"ה יו\"ט של ר\"ה, רס\"ו, ועי\"ז מאיר בגילוי בחי' התענוג העצמי כו', אבל בלא זה אינו מאיר התענוג העצמי בתו' שלמטה כו'). והענין הוא דהנה אי' בב\"ר פי\"ז ג' נובלות הן כו' נובלות חכ' שלמע' תורה, וכמו פירות הנובלות מן האילן שהוא להיותם מותרות חיצוני' הפירות כו', כמו\"כ הוא למע' דבחי' ח\"ע דאצי' חכים ולא בחכ' ידיעא שהיא למע' מהשגה כו', ומה שנמשך מבחי' ח\"ע להתהוות אותי' התורה (שהרי מה שנתגלה מהתו' הן רק אותי' התו' כמשי\"ת בסמוך, הרי האותי' וגם האור המתלבש בהאותי') אינו אלא מבחי' אחורים וחיצוני' החכ' שהיא בחי' נובלות חכ' כו'. דהנה יש בתו' טעמים נקודות תגין אותי', שהאותי' הן בבחי' מל' ושרשן מבחי' ח\"ע דאבא יסד ברתא דיסוד אותי' התו' הן מבחי' חכ' כו', אבל זהו רק מבחי' אחורים וחיצוני' החכ' כו', וזהו מה שנמשך מתושב\"כ לתושבע\"פ דמל' פה\nתושבע\"פ קרינן לה כו', וכנודע דתושבע\"פ הוא פי' וביאור המצות שבתושב\"כ, ומה שבא בגילוי בתושבע\"פ הוא רק בחי' אחורים וחיצוני' מבחי' החכ', והיינו רק גוף המצוה והיינו בחי' החכ' המלובשת באותי' התו', וכמו מ\"ט אמר קרא דכל דרשות התו' הן מבחי' האותי' כו', אבל מבחי' טנ\"ת לא בא בגילוי בתושבע\"פ רק מעט מזעיר וכמו רע\"ק הי' דורש על כל קוץ וקוץ כו', וכמו יש אם למקרא שזהו בנקודות כו', וכן כל מה שנתגלה בס' הקבלה מבחי' טעמי תומ\"צ ה\"ז רק מעט מזעיר כו'. ובאמת גם תושב\"כ והתו' כמו שהיא למע' באצי' ה\"ז בחי' נובלות לגבי בחי' חכ' שלמע' שהיא בחי' חכ' שבכתר וחכ' דא\"ק כו', וז\"ע או\"א במזלא אתכלילן ובי' תליין כו', וכמו השערות שבאין בדרך דילוג מהמוחין, כמו\"כ בחי' ח\"ע יונק מבחי' שערות דח\"ס שבא בדרך דילוג והו\"ע בחי' נובלות כו'. וע\"ד מ\"ש במ\"א בענין צאן לבן דצאן הו\"ע היציאה מגדר ההשתל' וההדרגה מבחי' לובן העליון כמו פרט ועוללות כו', דלובן העליון זהו בחי' א\"ק שהוא הכלל הראשון הכולל כל העולמות כו' (לא רק ראשית ההתהוות, דהיינו\nראשית המציאו' כו'), ומשם יצאו בחי' אורות עליוני' שלא בהדרגה כמו פרט הנושרים מן האילן כו', דלהיות ששרש המשכתם הוא ממדרי' גבוה מאד אא\"ל"],[3601330524,"ההמשכה בס' והדרגה כו', וגם בעולמו' לא היו יכולים לקבל כשהי' האור בבחי' הדרגה כו', כ\"א אור שבא בדרך נובלות ונשירה כו', אמנם גם מה שנובל ונושר הוא אור נעלה מאד כו' (וכמ\"ש במ\"א בענין השערות שיונקים ממותרי מוחין ה\"ז למע' מהמוחין, דמה שא\"א להתלבש בכלי המוחין ה\"ז בוקע ויוצא בהשערות כו', וזהו שהשערה באה בבחי' בקיעה שזהו מבחי' התגברו' האור כו', וע\"ה שהבקיעה הוא שנמשך הארה לבד, מ\"מ מבחי' הגבוה ביותר גם הארה מזה שלא בהדרגה ה\"ז נעלה מאד מההמשכה שבהדרגה ממדרי' תחתונה כו', ומובן דהמשכות אלו באור דתו' ה\"ז למע' הרבה מבהאור השייך לעולמו' כו', ובמ\"א מבו' בענין נובלות שזהו ע\"ד שיחת חולין של ת\"ח שיש בהם הרבה חכ' מעצם חכמתו כו', וחכם גדול מלביש בשיחת חולין שלו חכ' עמוקה יותר מהתגלו' החכ' שלו כו'). וזה הי' עבודת יעקב בבית לבן שבירר בחי' האורות הנ\"ל, וידוע דכללו' ענין הבירור דיעקב אצל לבן הוא שבירר בחי' האורות והאותי' דתו' כו', וכמ\"ש במ\"א בשם האו\"ת מהמגיד ז\"ל. וזהו בחי' נובלות חש\"מ תו' שהיא מה שנובל מבחי'\nחכ' העליונה בחי' חכ' הקדומה דא\"ק כו', ולכן לגבי מדרי' זו להיות שזהו מה שבא רק בבחי' נובלות בחי' שערות לבד כו', הנה האור והחיות דעולמו' תופס מקום לגבי זה כו'. וז\"ע זמירות היו לי חוקיך, דהנה ידוע ההפרש בין מזמור לשיר דזמרה במאנא ושיר בפה, וכמ\"ש בלק\"ת ד\"ה מזמור שיר חנוכת הא' ההפרש בין שירת המלאכים שהשירה שלהם נק' זמרה מצד שהוא הזמר המלובש בהכלי כו', ומלאכים להיות שיש להם גופים והביטול שלהם הוא בחי' ביטול היש לבד ה\"ז בחי' זמרה כו', והנשמו' שאין להם גוף והביטול שלהם הוא בבחי' ביטול בתכלית כו' נק' השירה שלהם בש' שיר כו', ועמ\"ש בסי' בפי' אהללה ה' בחיי שזהו בחי' האורות, ואזמרה לאלקי בעודי הוא בחי' הכלים כו'. ובענין התו' י\"ל ע\"פ מ\"ש בזהר בהעלותך דקנ\"ב ע\"א שיש מה שנק' לבושא דאורייתא והן הסיפורי מעשיות שבתו' שיש בהן רזין עילאין כו', וגופא דאורייתא והן גופי המצות דרמ\"ח פקודין רמ\"ח אברים דמלכא שזהו מה שמבו' בתו' באותי' התו' כו', ויש בתו' בחי' נשמתא ונשמתא לנשמתא כו', ועמ\"ש בבה\"ז פ' תולדות. ועפ\"ז י\"ל\nדמ\"ש דוד זמירות היו לי חוקיך היינו בחי' גופא דאורייתא והיא המדברת בפרטי ההמשכות שבעולמו' כו', ונענש ע\"ז דעיקר התו' הוא בחי' האור דתו' בחי' נשמה ונשמה לנשמה שזהו בחי' השעשועים דתו' והיינו התו' כמו שהיא בבחי' חכה\"ק דא\"ק כו', וז\"ע טעמים דתו' בחי' שיר דתו' וכמ\"ש ובלילה שירה עמי שירו כתי' שירו של הקב\"ה בחי' שעשועי המלך בעצמותו כו', והוא בחי' עומקה ופנימיותה דתו' המיוחדת באוא\"ס המלובש בתו' בבחי' יחוד גמור, וכמ\"ש באגה\"ק בקו\"א ד\"ה דוד זמירות קרית להו דהתו' בבחי' פנימיותה אינה שמחת לבב אנוש ושעשועיו אלא כביכול שמחת לב ושעשוע המלך הקב\"ה שמשתעשע בה כי אלקי' הבין דרכה כו', וזש\"ה ואהי' אצלו שעשועים (דמ\"ש ואהי' שעשועים קאי עמ\"ש קודם ואהי' אצלו) אצלו דוקא כו', ועז\"א ואהי' אצלו אמון א\"ת אמון אלא אומן.\n<span data-k=\"ks\"><b>קיצור.</b> וכ\"ז הוא כמו שהתורה באה באצי' שהיא תיקון העולם, אבל פנימיות התורה הוא תענוג העצמי והוא שהתו' אין לה סיקוס, ואין חיות העולם תופס מקום (והתגלות תענוג העצמי הוא ע\"י הבירורים בכח התורה, ובתורה עצמה</span>"],[3601330525,"<b>דדייק</b> במילין דחוכמתא), דהנה נובלות חכ' תורה, והן אותיות התורה שנתגלו ונמשכים מתושב\"כ לתושבע\"פ, וטנ\"ת לא נתגלו, וכן תורה דאצי' נובלות מחכ' דא\"ק, אבא יונק ממזלא, וזהו שבירר יעקב אצל לבן אותיות התורה, צאן לבן כמו פרט הנושר מלובן העליון א\"ק, ומ\"מ ה\"ז מדרי' גבוה, ובמ\"א כמו שיחת חולין שבהם עומק החכ', ולהיותה נובלות תופס מקום חיות העולמות, וזהו זמירות, זמרה כלי, שיר אור, ובתורה הו\"ע גופא דאורייתא ובחי' נשמתא ונשמתא לנשמתא התענוג שבתורה שהיא שעשועי המלך בעצמותו.\nקעד) <b>ולכאו'</b> צ\"ל מאחר דהתו' בבחי' זו היא רק שמחת לב ושעשוע המלך כו' והו\"ע שעשוע המלך בעצמותו כו' ולא ידע אנוש ערכה כו', א\"כ מה נענש דוד בזה שהי' משבח את התו' ומשמח בה בבחי' שמחת לבב אנוש ושעשועיו כו'. וי\"ל דכמו בענין המצות הרי יש בזה ב' ענינים כוונת המצות בבחי' המשכה פרטי' שבכל מצוה בפרט כו', שלזה צ\"ל הקדמה באהוי\"ר כו', והיינו שבתחלה צריך לידע הכוונה והוא הסוד ה' שבכל מצוה וצ\"ל התעוררות אהבה לאלקות ועי\"ז הוא קיום המצוה כדבעי למהוי כו', וכמ\"ש בסש\"ב והמקיימן באמת הוא האוהב ש' הוי' וחפץ לדבקה בו כו', ועי\"ז ממשיך האור בנפשו וגם בעולם כו', ועי\"ז הוא השמחה והעונג שלו בקיום המצוה כו', והביטול בזה הוא רק בהגילוים דאוא\"ס דבד\"כ הוא בבחי' הרצון דהיינו בבחי' הרצונות פרטי' שבכל מצוה ומצוה בפרט שבזה הוא הביטול שלו (דערצו איז זיין אוועק לייג לבחי' רצה\"ע כו'), ובזה הוא שמחת נפשו בגילוי אור הרצון כו'. והאופן הב' הוא קיום המצוה בבחי' עבודת עבד לקיים רצונו ית' לבד לא בשביל להמשיך גילוי אור\nבנפשו ובעולם רק לקיים רצונו ית' כו', והביטול בזה הוא לא\"ס בעהר\"צ לעשות כל מה שהוא רצונו ית', ואינו נוגע לו כלל מה היא המצוה דגם אם היו אומרים לו לחטוב עצים ג\"כ טוב כו', להיותו בבחי' ביטול לא\"ס בעהר\"צ לעשות כל מה שהוא רצונו ית' כו'. ויש בזה ג\"כ שמחה של מצוה, והשמחה בזה הוא השמחה והעונג מה שמקיים רצה\"ע לא מה שלו טוב האור והגילוי כ\"א במה שמקיים רצונו ית' ושנעשה מזה נח\"ר למע' וכמא' נח\"ר לפני כו', והנה בזה גופא יש חילוקי מדרי' אם השמחה הוא בזה שהוא קיים רצה\"ע והוא פעל את הנח\"ר כו', והיינו מה שזכה לקיים רצה\"ע ולעשות נח\"ר למע' כו', שזהו ג\"כ עבודת עבד רק שהעונג הוא מה שהוא זכה לזה כו', וכמו עד\"מ איש פשוט שהמלך מצוה אותו לעשות דבר והוא משמש אותו בזה הרי השמחה גדולה מאד מה שזכה לשמש את המלך כו', וכמו\"כ הוא בדוגמא בקיום המצוה שהשמחה והעונג הוא מה שזכה לקיים רצונו ולעשות נח\"ר כו', ולמע' מזה הוא שהשמחה והעונג שלו הוא בזה שנשלם רצה\"ע ושנעשה נח\"ר למע' כו', ולא ממה שהוא פעל ועשה כו', כ\"א מה שע\"י המצוה\nהרי נשלם רצה\"ע ונעשה נח\"ר למע' ה\"ה שמח ומתענג בזה כו', ובזה גופא המדרי' היותר העליונה בזה הוא שהשמחה והעונג שלמע' זה עצמו הוא השמחה והעונג שלו כו', והיינו לא רק שהוא שמח ומתענג בהשמחה והעונג שנעשה למע' כ\"א שהשמחה והעונג שלמע' זהו השמחה והעונג שלו כו'. והענין בזה הוא דהנה באופן הא' ה\"ז שמחה ועונג שלו, ובמה הוא העונג בזה שיש נח\"ר למע' וה\"ז רק מהבכן של המצוה לא מהמצוה עצמה כ\"א מהבכן היינו מהנח\"ר שנעשה כו' (ומובן שזה למע' הרבה מענין הבכן המבו' במ\"א (דכאן"],[3601330526,"גם הבכן הוא העצם כו') רק שזהו בדוגמא כענין הבכן כו'), אבל באופן הב' הרי העונג הוא העונג שלמע' כו', ובמה הוא העונג בעצם המצוה שיש לו תענוג בעצם המצוה (ער האט אגישמאק אין דער עצם מצוה אין דעם איז ער זעך שמח ומתענג), הגם שאינו יודע כלל מה היא המצוה ומה הוא התענוג בזה, מ\"מ ה\"ה מתענג בעצם המצוה וזהו רק מפני שהתענוג והנח\"ר שלמע' הוא העונג שלו כו'. והמשל בזה הוא כמו העבד העושה מלאכה להאדון כמו כלי וכה\"ג שמהדר בהמלאכה שתהי' בתכלית הנוי והיופי ויהי' תפארת להאדון כו', והנה ההידור בנוי ויופי הדבר ה\"ה ע\"י התענוג ודוקא ע\"י התענוג בעצם הדבר כו' (וכמו עד\"מ אומן הטוב שעושה כלי ומהדר במלאכתו שתהי' בתכלית הנוי והיופי ביותר שזהו רק מצד העונג היינו הגישמאק שיש לו בעצם הדבר, לא רק מזה שתהי' נאה ויהי' בזה תפארתו לפני בנ\"א, דבזה לבד אם אין לו גישמאק בעצם הדבר לא יהי' ההידור בפועל, כ\"א ע\"י הטוב טעם והגישמאק שיש לו בעצם המלאכה עי\"ז הוא ההידור והתפארת בא ממילא כו', וכמו\"כ הוא בהעבד שההידור שלו אינו רק מהתפארת\nשיהי' להאדון כ\"א מפני הטוב טעם והחיות שיש לו בעצם המלאכה להדר בה בכל היכולת שתהי' ביופי ביותר כו'), וגבי העבד זהו רק מפני שהעונג והחיות של האדון הוא העונג שלו כו', שהרי העבד מצ\"ע אינו בערך שיהי' לו חיות ותענוג במלאכה גם כשתהי' בתכלית ההכשר, כי חושיו אינם דקים כ\"כ ואינם חושים מופשטים שידע וירגיש העונג שבזה כמו האדון שהחושים שלו דקים ומופשטים ויודע מעלת הדבר איך שהוא דבר עונג בעצם כו', אבל העבד אינו שייך לזה שידע וירגיש הדבר, כ\"א מה שהתענוג של האדון הוא התענוג שלו כו', וזהו מפני הנחת עצמותו שאינו מציאות לעצמו כלל וכל מציאותו הוא רק מציאות האדון ע\"כ התענוג של האדון זהו עצמו התענוג שלו וזהו חיותו כו' (און דאס מאנט בא עם אויף חוש ההידור בנוי ויופי המלאכה כו'). וכמו\"כ הוא במצות שהתענוג שלמע' זהו התענוג שלו שיש לו חיות ועונג בעצם המצוה הגם שאינו יודע כלל מע' וערך המצוה, אך מצד הביטול העצמי שלו לעצמות א\"ס שאינו מציאות לעצמו כו', משו\"ז יש לו חיות ועונג בעצם בהמצוה שזהו התענוג שלמע' כו', והוא חי\nבזה בבחי' חיות עצמי לא רק בבחי' חיות המתפשט כ\"א בבחי' חיות עצמי ממש כו'. וי\"ל דכמו\"כ הוא גם בתו' דע\"ה שאינה בעשי' בפועל רק בבחי' ידיעה והשגה כו', הרי ידיעת התו' היא גופא מצוה וכמ\"ש באגה\"ק בקו\"א ד\"ה להבין מ\"ש בפע\"ח, ע\"כ יכול להיות בזה בחי' התענוג העצמי בבחי' שעשועי המלך בעצמותו שמתענג עם התו' כו'. וי\"ל שז\"ע ג' שעות הראשונות שהקב\"ה עוסק בתו' שזהו בבחי' המשכה מצ\"ע, למע' ממה שכל הקורא כו' הקב\"ה יושב ועוסק כו' שזהו מה שבאתעדל\"ת אתעדל\"ע כו', והגם דתו' בכלל היא בבחי' המשכה מלמע', וכידוע ההפרש בין תו' לתפלה, דתפלה הוא בבחי' העלאה מלמטלמ\"ע דהיינו שבאתעדל\"ת אתעדל\"ע ותו' היא בבחי' המשכה מלמעלמ\"ט שזהו אתעדל\"ע מצ\"ע כו', מ\"מ בתו' גופא מה שהקב\"ה קורא ושונה כנגדו זהו ההמשכה שע\"י אתעדל\"ת דעסק התו' למטה כו', וג' שעות ראשונות שהקב\"ה יושב ועוסק בתו' הוא ההמשכה שמצ\"ע כו'. וזהו התו' כמו שהיא בג\"ר דעתיק ובשרשה בג\"ר דא\"ק כו', דיש בחי' זו גם בעסק התורה שבכאו\"א ע\"י הביטול בעצם בבחי' עצמות א\"ס שמתענג בעסק תורתו בבחי' התענוג שלמע' כו', ומדרי' זו בתו' הוא שהתו' נק' בש' מתנה כו'. דהנה ידוע דלפעמים נק' התו' בשם"],[3601330527,"ירושה וכמ\"ש תורה צוה לנו משה מורשה כו', ופעמים ארז\"ל התקן עצמך ללמוד תורה שאינה ירושה לך כו', ופעמים נק' בשם מתנה, וכמ\"ש בברכת התו' אשר נתן לנו תו' אמת נותן התורה כו' ונק' מתן תו' כו'. דענין התקן עצמך היינו מה שבא בבחי' יגיעה דבאתעדל\"ת אתעדל\"ע כו', וענין הירושה הוא ע\"י הבירורים דתו' שעי\"ז יורשים אורות דתהו כו', וענין מתנה דתו' זהו בחי' אתעדל\"ע מצ\"ע והו\"ע פנימי' התו' בחי' שעשועים העצמי' כו', אך מתנה אינם נותנים כ\"א להראוי והיינו ע\"י הביטול עצמי כו', דגם הביטול העצמי הוא בבחי' המשכה מלמעלה כו', ועי\"ז מגיע לבחי' טל תו' בחי' שעשועים העצמי' כו', דאז הוא בעצם למע' מכל בחי' חיות ועונג שבעולם ובדוגמא שלמעלה ממש כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ואתחנן אל ה' כו' אעברה נא ואראה את הארץ כו', דהבקשה ואראה את הארץ הוא שרצה לפעול בכללות נש\"י בחי' ההמשכה מלמעלמ\"ט כו', וזהו\"ע אעברה נא שהו\"ע ההמשכה מלמע' באתעדל\"ע מצ\"ע כו', וז\"ע הראי' שהיא המשכה מלמעלמ\"ט כנודע, וגם ראי' מורה על הביטול העצמי דהרי ראי' היא מקרוב וכאשר הוא מקרוב אינו שייך ענין התשוקה כו', דכל רצון ותשוקה שייך רק כשהוא מרחוק אבל לא כשהוא מקרוב כו', וכמו העומד לפני המלך אינו שייך הריצה אל המלך כ\"א הביטול שמתבטל בעצם מהותו כו'. וזהו\"ע ואראה שמורה על ב' הענינים על בחי' ההמשכה מלמעלמ\"ט ועל הביטול העצמי שהוא הכלי לזה כו', ומשה עצמו הי' במדרי' זו, וכמ\"ש ונחנו מה שהי' בבחי' ביטול והי' מאיר בו גילוי בחי' עצמות א\"ס וכמ\"ש וירא ראשית לו בחי' ראי' כו', וע\"כ הי' ביכולתו לפעול זאת בכללות נש\"י כו', וזהו אתה החלות להראות את עבדך בחי' ראי' שזה הי' מדרי' משה כו'. וענין אתה החלות הו\"ע ואני המתחיל כו' דבמ\"ת עמד ובטל הגזרה ואני המתחיל וירד ה' על ה\"ס כו', דבמ\"ת הי'\nבבחי' המשכה מלמעלמ\"ט כו'. וזהו ג\"כ אמרו את גדלך ואת ידך החזקה בחי' תגבורת העצמות להיות בבחי' המשכה כו', אשר מי יעשה כמעשיך וכגבורותיך והו\"ע ההפלאה שזה דבר נפלא מאד להיות המשכת העצמות, דע\"ה שמובדל בערך מהעולמות ומ\"מ ה\"ה נמשך כו', שזה רק בכח העצמות כו', וזה רצה לפעול בכללות נש\"י כו'. וזהו ג\"כ אומרו להראות את עבדך בדרך שפלות שהו\"ע הביטול עצמי בבחי' עבד כו' כנ\"ל שזהו הכלי להמשכת העצמות כו', ואלו הי' משה מכניס לארץ לא הי' בזה שינוים שלא הי' חורבן בהמ\"ק כו', והי' הגילוי לכל ישראל בשוה כו', כי בהמשכה מלמעלמ\"ט לא יש חילוקי מדרי' כו', וכמו שיהי' לעתיד כו'. וזהו ג\"כ ואתחנן אל ה' מל' מתנת חנם וכ\"ה במד\"ר כאן שא' מתנת חנם אני מבקש מאתך וכנ\"ל דמדרי' זו בתו' היא בבחי' מתנה כו', וכ\"ז הי' בשביל ישראל לא בשביל עצמו וכדאי' בילקוט ע\"פ תפלה למשה א\"ל הקב\"ה מה אתה מבקש א\"ל איני מבקש בשבילי אלא בשביל ישראל שיהי' בחי' המשכה הנ\"ל, וזהו ואתחנן אל הוי' בחי' מתנת חנם כו' אתה החלות דואני המתחיל שזהו ההמשכה מלמעלמ\"ט\nכו' אעברה נא ואראה כו' לפעול המשכה זו בכללות נש\"י כו', ומשה לפי שהי' בעצמו במדרי' זו הי' ביכולתו וזה הי' כל בקשתו לפעול ההמשכה מלמעלמ\"ט בכללות נש\"י כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וצ\"ל מאחר שזהו רק שעשועי המלך מפני מה נענש ע\"ז, יקדים שיש במצות כוונת המצות שהביטול וההמשכה היא בגילוי הרצון, והב' קיום</span>"],[3601330528,"<b>המצוה</b> בעבודת עבד שהוא הביטול לבעהר\"צ, ויש בזה שמחה מה שמקיים רצה\"ע וגורם נח\"ר, ולמעלה מזה שהשמחה היא מהנח\"ר שלמעלה, ובפנימיות הוא שהשמחה והעונג שלמעלה הוא השמחה והעונג שלו, והיינו שאין זה עונג שלו כלל כ\"א העונג שלמעלה, והשמחה היא בעצם המצוה, הגם שאינו יודע מה היא המצוה והתענוג בזה, והוא מצד הביטול והנחת עצמותו, וכמו העבד שמהדר ביופי המלאכה מפני התענוג, והוא התענוג של האדון, וי\"ל דכמו\"כ בתורה התענוג בשעשועי המלך, וי\"ל שז\"ע ג\"ש הראשונים יושב ועוסק בתורה, והוא שהתורה היא בבחי' מתנה. ובזה יובן מ\"ש ואתחנן מתנת חנם, להראות את עבדך ביטול עצמי."],[3601330529,"<h3>בס\"ד. ש\"פ עקב, תער\"ג</h3>\n<b>והי'</b> עקב תשמעון את המשפטים האלה ושמרתם ועשיתם כו', ושמר ה' אלקיך לך את הברית כו', וצ\"ל אחר שאו' והי' עקב תשמעון מהו עוד ושמרתם ועשיתם אותם, הלא כל לימוד התו' הוא בשביל העשי' כו', שהרי אין הכוונה השמיעה לבד כ\"א העשי' דוקא, וא\"כ מהו אומרו עוד ושמרתם ועשיתם כו'. גם צ\"ל מ\"ש ושמר ה\"א לך את הברית ואת החסד אשר נשבע כו', דחשיב כאן ג' ענינים ברית וחסד ושבועה שכל אלו הענינים אינם באים על התנאי, דענין הברית הוא כמו שני אוהבים שכורתים ברית ביניהם, הרי ענין הכר\"ב הוא שאפי' אם יהי' דבר המפריד ומפסיק את האה' מ\"מ לא יגרע מאהבתם כלל כו', דכמו\"כ הוא למע' ענין הכר\"ב דגם אם ח\"ו לא אכשיר דרא מ\"מ לא יהי' שינוים כלל כו', וכמו ענין החסד הרי א\"ז להשפיע להראוי דוקא כ\"א להשפיע לכל גם למי שאינו ראוי כו', וכן ענין השבועה הוא שמכריח א\"ע כו', הרי שכל אלו הענינים אינם באים על התנאי כו', וא\"כ מהו\"ע ושמר ה\"א לך את הברית כו' אחר אומרו והי' עקב תשמעון כו' דמשמע דדוקא כאשר תשמעון ואז ושמר ה\"א לך כו'. גם צ\"ל מהו\"ע\nהשמירה כו'. גם מהו\"ע אומרו והי' עקב תשמעון דהול\"ל אם תשמעון כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דבתו' יש כלל ופרט דהפרט שבתו' זהו כמו שהתו' ירדה לאבי\"ע שכל פרשה הוא המשכה פרטי' מאוא\"ס ב\"ה ונמשכת בפרטי המדרי' דאבי\"ע ועי\"ז הוא בנין ותיקון העולם כו', והכלל דתו' זהו התו' כמו שהי' בחכ' הקדומה דא\"ק דכל הפרשיות וכל הענינים המה שם בבחי' כלל כו'. ונת' דזהו ב' המדרי' שבתו' בחי' זמירות היו לי חוקיך כו', ובחי' שעשועים העצמי' כו', דזמירות היו לי חוקיך זהו התו' כמו שהיא בהתגלות דנובלות חכ' שלמע' תו' כו', דלגבי מדרי' זו תופס מקום האור והחיות של העולמות כו', ובזה הי' דוד משמח א\"ע בעת שהי' לא טוב לו בגשמי' כו', שהרי כל חיות העולמות תלוי בדקדוק א' של תורה כו', וגם שע\"י התו' נכרת היניקה שלהם כו', ובחי' שעשועים העצמי' שבתורה זהו התו' כמו שמיוחדת בעצמות אוא\"ס כו', דכשם שלגבי עצמות אוא\"ס אינו תופס מקום כל הגילוים שבעולמות כו', כמו\"כ אינם תופסים מקום לגבי התו' כו'. נמצא שלגבי התו' כמו"],[3601330530,"שהיא בהתגלות תופס מקום האור דס' השתל' כו', ולגבי התורה כמו שמיוחדת בעצמות אוא\"ס והיינו התורה כמו שהיא למעלה מסדר השתל', כל הגילוים דסדר השתל' אינם תופסים מקום כלל כמו דכולא קמי' כל\"ח כו'.\nקעה) <b>והנה</b> באגה\"ק הנ\"ל ד\"ה זמירות היו לי חוקיך מבו' דבחי' התו' כמו שהיא בבחי' שעשועים העצמים עז\"נ ואהי' אצלו אמון א\"ת אמון אלא אומן כו', וצ\"ל איך התו' במדרי' זו נק' בש' אומן מאחר שזהו למע' לגמרי מהעולמות כו', דהנה בחי' חיצוניות התו' שבה וע\"י הוא תיקון העולם שייך לקרוא בשם אומן כו', אבל בחי' פנימי' התו' שכל האור והגילוי דעולמות אינו תופס מקום כלל לגבי מדרי' זו איך שייך לקרוא בש' אומן כו'. וי\"ל להיות דכללות ענין התו' הוא להיות התחברות אוא\"ס עם עולמות בכלל ועם נש\"י בפרט, דלא יש דבר שתוכל לקבל בחי' עצמות א\"ס או שיוכל העצמות להתלבש בו כ\"א התורה שבה דוקא יכול להיות התלבשות העצמות והיא יכולה לקבל כו', וזהו לפי שהתו' היא בחי' עצמות כו', דבאמת התו' גופא הוא בחי' עצמות א\"ס כו', ואיך שנא' בענין התו' אם היא בחי' חכ' או בחי' תענוג ה\"ה בחי' עצמות כו' וכמשי\"ת, וע\"כ ביכולתה לקבל בחי' העצמות כו'. וע\"י התו' יש בכח נש\"י לקבל בחי' עצמות א\"ס כו', וכמ\"ש בסש\"ב פל\"ו שהתו' נק' עוז שהיא הנותנת כח\nלצדיקים לקבל שכרם לע\"ל שלא יתבטלו במציאותם לגמרי כו', דבהגילוי דלעתיד דבחי' עצמות א\"ס יאיר בגילוי בפנימי' בנש\"י שמצד זה יהיו בבחי' ביטול במציאות כו', הנה בכדי שלא יתבטלו במציאותם לגמרי להיות אין ואפס כו', זהו בכח התו' כו', מפני שהתו' ביכולתה לקבל בחי' עצמות א\"ס כו', וכבר הי' לעולמים במ\"ת דכתי' אתה הראת לדעת כי ה' הוא האלקים שראו בחי' אחדות ה' בבחי' ראי' חושית ממש (דהיינו כמו בחי' ראיית העין ולא רק ראיית עין השכל כו', וכמו לעתיד שיהי' בחי' ראי' חושי' ממש וכמ\"ש כי עין בעין יראו כו', וכתי' וראו כל בשר יחדו כי פי ה' דבר כו', וכן במ\"ת הי' בבחי' ראי' חושי' כו'), וע\"כ עכדו\"ד פרחה נשמתן כו', והחזירן בטל תחי' שהוא בחי' טל תו' כו'. והיינו לפי שהתורה הוא כלי לקבל בחי' עצמות א\"ס ב\"ה ועש\"ז נק' אמון אומן, לפי שע\"י התו' הוא ההתחברות דעצמות א\"ס עם העולמות בכלל ונש\"י בפרט כו'. והענין הוא דהנה נת\"ל פקס\"ב דהאמצעי דתו' הוא בב' ענינים בהתהוות העולמות ובההתחברות דאוא\"ס עם העולמות כו', וזהו בהב' מדרי' שבתו',\nדתו' כמו שהיא בהתגלות ה\"ה ממוצע שע\"י הוא התהוות העולמות כו', דג\"ז הוא בחי' תוס' אור בעולמות וכמשי\"ת, והתו' כמו שהיא בבחי' שעשועים העצמי' עי\"ז נעשה ההתחברות דאוא\"ס עם נש\"י כו', שזהו תכלית הכוונה פנימי' להיות התחברות דאוא\"ס עם נש\"י ועש\"ז נק' התו' אומן כו', ואו' ע\"ז ואהי' אצלו אמון שזהו התו' כמו שהיא אצלו דוקא בבחי' שעשועים העצמי' דאורייתא וקוב\"ה כולא חד כו'. וביאור הענין הוא, דהנה ידוע מאה\"ז תלת קשרין מתקשרין דא בדא קוב\"ה אורייתא וישראל, והנה התקשרות שייך בשני דברים שהם נבדלים זמ\"ז דאם הם דבר א' אינו שייך התקשרות, וכמו אור ומאור אינו שייך בזה התקשרות מפני שהאור אינו דבר אחר מהמאור בבחי' מהות דבר בפ\"ע רק גילוי מן העצם, ע\"כ אינו שייך בזה התקשרות כ\"א דבקות שהוא דבוק ומיוחד בהעצם כו' (וזהו בכללות בחי' האור כו', דבפרטי מדרי' באור יש שההתקשרות אינו"],[3601330531,"בבחי' דבקות כ\"א בבחי' התחדשות ממקורו כו' וכמ\"ש במ\"א, רק כללות האור בבחי' דבקות כו'), רק בשני דברים נבדלים שייך התקשרות כו' (ולפ\"ז דבקות הוא למע' מהתקשרות, ובבה\"ז פ' תרומה אי' דהתקשרות הוא יותר מדבקות כו', דדבקות הוא בבחי' מקיף והתקשרות בבחי' פנימי כו', וי\"ל דשם מדבר בדבקות שמצד העליון דהיינו בבחי' מקיף לבד, וכמו כאשר ידבק האזור כו' כן הדבקתי אתכם כו', שז\"ע וימינו תחבקני שהוא בבחי' מקיף, וכמו המחבק את חברו שמקיפו כו', והתקשרות הוא בבחי' פנימי כמ\"ש ונפשו קשורה בנפשו כו', אבל מלמטלמ\"ע הדבקות הוא בבחי' התאחדות יותר מהתקשרות, דדבקות הוא בדבר שאינו מהות בפ\"ע והתקשרות הוא בדבר שהוא מהות בפ\"ע כשמתחבר כו'). וזהו שישראל מתקשראין באורייתא, דהנה הנשמה כמו שירדה לבי\"ע ה\"ה בבחי' יש ומציאות דבר, דע\"ה ששרשה הוא באצי' וכמש\"א נשמה שנתת בי טהורה היא כו', וגם כמו שירדה לבי\"ע ה\"ה אלקות בעצם מהותה, ומ\"מ הרי נעשית בבחי' יש עד שביכולתה להתחבר עם הגוף ונה\"ב ונתפסת בגשם דאז ה\"ה נעשית יותר בהגשמה כו' כנודע\nוכמשנת\"ל בתחלת הדרוש, והתורה היא חכ' אלקית חכמתו ורצונו ית' כו', ומ\"מ הרי בשעת עסקו בתו' שמשים כל שכלו ורוח בינתו בעסק זה הרי כל כחות נפשו מתאחדים ומתכללים באותה דבר הלכה שעוסק בה, וכמ\"ש בסש\"ב ח\"א פ\"ה שבעסק התו' נעשה מוקף ומקיף שמלבד ששכלו מוקף מהדבר הלכה הרי גם שכלו מקיף את הדבר הלכה שמבין אותה ומשיגה כו', והוא יחוד נפלא שאין יחוד כמוהו ולא כערכו נמצא כלל בגשמי' להיות לאחדים ומיוחדים ממש מכל צד ופינה כו'. והגם שנפשו היתה בבחי' יש נפרד לעצמה קודם עסקה בתו', אך בעסקו בתו' מתאחדת ומתקשרת בד\"ת, וה\"ז כמו שצוררין דבר בדבר וקושרין אותן יחד עד שמתאחדין כו', כך הנפש צרורה בצרור החיים ומתאחדת בד\"ת שעוסק בה בכל כח שכלו ורוח בינתו כו', וזהו הנק' קשר ויחוד שמחברים דבר נפרד כמו הנפש שמתאחדת בתו' כו', וזהו לפי שהנפש הוא אלקות בעצם ע\"כ הוא מתאחד בעסקו בתו' בבחי' התאחדות ממש כו'. והנה בכל קשר צ\"ל ב' קשרים זה עג\"ז וא\"ל אינו קשר של קיימא, והיינו שצ\"ל לזה עבודה בבחי' אהוי\"ר דאורייתא בלא דחילו ורחימו לא\nפרחת לעילא ולא נקרא קשר כלל, כ\"א צ\"ל אהוי\"ר ועי\"ז בעסק התו' מתקשר נפשו בתו' ומתאחד בה כו'. וכמו\"כ הוא בהקשר דאורייתא וקוב\"ה, דהנה כמו שאין ערוך לנפש בע\"ג עם התו' שהיא חכ' האלקית, כך יותר אין ערוך לתו' עם עצמות אלקות כי עצמות אוא\"ס הרי חכים ולא בחכ' ידיעא ונבדל בערך מן החכ' עד שהחכ' נק' לגבי' עשי' וכמ\"ש כולם בחכ' עשית כו' (וי\"ל ע\"פ משנת\"ל פמ\"ט בההפרש בין הרצון לכחות הנפש דהרצון אינו דבר לעצמו חוץ לעצמות הנפש, אבל הכחות כמו כח השכל ה\"ה כח לעצמו חוץ להעצמות של הנפש כו', וכמו\"כ הוא בדוגמא כזאת בבחי' חכ' למע' והיא בחי' חכ' דתו' שזהו בבחי' דבר מה היינו בבחי' חכ' כו', דעצמות אוא\"ס אינו בגדר חכ' כו'), וכמ\"ש והחכ' מאין תמצא שנמצאת מאין בבחי' מציאות יש כו', וכמא' אבא יונק ממזלא בחי' מזלות ושערות לבד כו', וז\"ע לבנ\"ח דהחכ' היא בבחי' נתיב כו'. וידוע ההפרש בין נתיב לדרך, דדרך הוא דבר רחב שהולכים בו בהתגלות כו', ונתיב הוא קצר ומצומצם שההולך בו הולך יחידי ובהעלם כו', וכ\"ה למע' שהולכת והובאת אוא\"ס בבחי' צמצום והעלם נק' בש' נתיב כו', וכ\"ה המשכת בחי' העצמות לבאר הרצון דמצות"],[3601330532,"והיא החכ' דתו' שהיא בחי' נתיב מצומצם ונעלם כו', הרי שהחכ' דתו' היא באין ערוך לגבי עצמות כו'. וזהו מה שהתו' נק' תושב\"כ דאותיות הכתב ה\"ה דבר נוסף על העצם כו', וכידוע ההפרש בין אותי' החקיקה לאותי' הכתיבה, דאותיות החקיקה הם מהות אחד שאינם דבר נוסף כו', משא\"כ אותי' הכתיבה ה\"ה דבר נוסף כו', והיינו דאותיות התו' וגם החכ' המלובשת בהאותיות ה\"ז בבחי' דבר נוסף על העצם כו', הרי שהם נבדלים זמ\"ז כו'. אך כמו שהנפש מתאחדת ומתקשרת בתו' כנ\"ל, כך התו' הגם שהיא דבר בפ\"ע מן העצמות ומ\"מ נכללת ומתאחדת בעצמות כמו שצוררין דבר בדבר כדמיון קשר הנפש בתו' כו', והתקשרות זאת דתו' בהקב\"ה נעשה עי\"ז שישראל מתקשראין באורייתא וכמארז\"ל דכל הקורא בתו' הקב\"ה קורא ושונה כנגדו שע\"י לימוד התו' כדבעי למהוי דהיינו בהקדמת אהוי\"ר ובהתקשרות שכלו ומחשבתו בתורה כו', עי\"ז ממשיך המשכת אוא\"ס בתו' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה מבו' באגה\"ק דהתורה בבחי' שעשועים העצמיים הו\"ע אמון אומן, וי\"ל דהיינו התחברות העצמות עם נש\"י ע\"י התורה, דהתורה להיותה עצמית ה\"ה כלי לעצמות א\"ס, וע\"י יכול להתקבל בנש\"י, וכמו במ\"ת אתה הראת בראי' ממש ע\"י התורה, דלהיות שזהו עיקר הכוונה ע\"כ נק' אומן, והענין דהנה תלת קשרין מתקשראין ישראל אורייתא וקוב\"ה, התקשרות הוא בשני דברים, משא\"כ אור ומאור הו\"ע דבקות (ובבה\"ז דדביקות מקיף והתקשרות פנימי י\"ל שזהו מלמעלה, ומלמטלמ\"ע דביקות התאחדות יותר), וזהו שהנשמה אם שנתהווה בבחי' יש ותורה היא חכמת אלקית ה\"ה מתקשרים זע\"ז, מקיף ומוקף, וצ\"ל ב' קשרים זהו הקדמת אהוי\"ר, וכן התורה שהיא חכ' כבי' כח שחוץ להעצמות, ואבא רק יונק ממזלא וז\"ע נתיבות החכ' נתיב צמצום, וזהו תושב\"כ דהאותיות והאור כמו דבר נוסף, וה\"ה מתקשרת בעצמות, והוא ע\"י התקשרות נש\"י בתורה שממשיכים בזה עצמות א\"ס בתורה.</span>\nקעו) <b>והנה</b> המשכה זו הו\"ע לימוד התורה לשמה לשם התורה כו', דבעסק התורה יש ב' אופנים, דהנה ארז\"ל מעיקרא כי עביד אינש אדעתי' דנפשי' עביד והוא לקשר נפשו ע\"י התו', וזהו כפי' הפשוט דישראל מתקשראין באורייתא ואורייתא בקוב\"ה שע\"י התו' מתקשרת הנשמה באלקות כו', והו\"ע לימוד התורה שקודם התפלה שזה מסייע לעבודה דתפלה דבכדי שיהי' התעוררות אהוי\"ר בתפלה ה\"ז ע\"י הקדמת התורה כו', ועסק התורה אז הוא לקבל מאור התורה והיינו להאיר נפשו באור התורה להיות התגלות הכחות דנה\"א כו'. דהנה אופן התלבשות הנשמה בגוף ונה\"ב הוא שהכחות דנה\"א מתעלמים בהכחות דנה\"ב, ואינו דומה לתומ\"צ דאופן הירידה שלהם הוא בבחי' התגלות אלקות גם כמו שירדו למטה ונתלבשו בדברים גשמי' כו', וכמו המצות שנתלבשו בדברים גשמי' (שהרצה\"ע בהם בלי הסתר פנים כו' כמ\"ש בסש\"ב), וכן התורה שירדה למטה ונתלבשה בענינים גשמי' כו', הרי מ\"מ הם בבחי' התגלות אלקות כו', דכן הי' במ\"ת שהי' גילוי אוא\"ס ממש למטה וכמ\"ש וירד ה' על ה\"ס, ומש\"נ במ\"ת הרי נאמרו ענינים פשוטים\nוגשמי' כו', וכמו\"כ הוא כללות התורה המלובשת בענינים גשמי' מאיר בהם גילוי אוא\"ס כו', הרי התו' ירדה למטה בבחי' התגלות אלקות כו', משא\"כ הנשמות אופן ירידתם למטה הוא בבחי' התעלמות הכחות שלה כו'. והיינו לפי שהכוונה בירידת הנשמה למטה הוא בכדי לברר ולתקן את הגוף ונה\"ב, ואופן הבירור הוא בדרך מלמטלמ\"ע שזהו דוקא ע\"י התעלמות הכחות"],[3601330533,"דנה\"א בנה\"ב כו', וכידוע המשל מכלי ההגבהה הנק' ליווער שצריכים להעמידו תחת המשא דוקא ואז מגביה את המשא, וכמו\"כ בכדי לפעול הבירור בהנה\"ב זהו דוקא ע\"י התעלמות הכחות דנה\"א בנה\"ב שעי\"ז הוא הבירור כו', והיינו שע\"י היציאה היינו ההתגלות דכחות הנה\"א עי\"ז גופא פועל הבירור בהנה\"ב כו', וגם לאחר שנתגלו הכחות דנה\"א אופן הבירור הוא בדרך התלבשות בהנה\"ב וכידוע הענין, וזהו ע\"י ההתעלמות שהי' בתחלה דהיינו דאופן ההתלבשות שלו הוא בבחי' התעלמות ע\"כ העבודה אח\"כ היא ג\"כ בבחי' התלבשות כו', ולכן בתחלת העבודה שהכחות הם בהתעלמות דכ\"ה בכ\"י דבתחלת היום הכחות דנה\"א הם בהעלם כו', וכמו בגשמיות בעת השינה הרי כחות הנפש הם בהתעלמות ומה שבהתגלות הוא הגוף, דבעת שהוא ער הרי ההתגלות דכחות הנפש הם יותר מהגוף (אדרבה אז נראה ביטול הגוף אל הנפש כו'), משא\"כ בעת השינה הגוף הוא בהתגלות והכחות הן בהעלם כו'. וכמו\"כ הוא בהעבודה הן בכל יום והן בתחלת העבודה שהכחות דנה\"א הן בהעלם כו', והתגלות הכחות דנה\"א הוא ע\"י התו' כו', וכידוע שהתו' נק'\nעוז ותושי' שמתשת כח הנה\"ב ונותנת כח ועוז לנה\"א כו', וע\"כ בתחלת עבודה בכ\"י צ\"ל תחלה עסק התו' שמתשת את הנה\"ב ומסירה ההעלמות וההסתרים וגם נותנת כח בנה\"א להיות התגלות כחותיו בהשגה והתבוננות ובהתעוררות אהוי\"ר כו'. וכאשר התפלה היא כדבעי בהתגלות הנה\"א ובהתקשרות באלקות, אזי העסק התו' שאחר התפלה הוא בהתקשרות נפשו בתו' בחכ' ורצונו ית' וממשיך המשכת אוא\"ס בתו' כו', והיינו דעסק התו' שאחר התפלה אינה בכדי להאיר נפשו כ\"א בכדי לקשר נפשו בהאוא\"ס המאיר בתו' כו', וזהו שאחר ואהבת אומרים והיו הדברים האלה בד\"ת הכתוב מדבר שממשיך אוא\"ס בתו' ומאיר האור בנפשו כו', והיינו דע\"י ההקדמה דאה' דובכל מאדך ממשיך המשכת אוא\"ס בתו' ומקשר נפשו בהאוא\"ס שבתורה שז\"ע והיו הדברים האלה כו'. אך לכאורה צ\"ל מהו ההתחדשות בההתקשרות שבתו' שהרי גם בתפלה הוא קירוב והתקשרות נפשו באלקות כו', וזה גופא מה שנמשך אוא\"ס בתו' זהו שמעוררים וממשיכים ע\"י התפלה כו', וא\"כ מהו ההתחדשות בהתקשרות זאת. וי\"ל בב' אופנים הא' דבתפלה הגם שנעשה בבחי' קירוב\nלאלקות, מ\"מ אין האור מאיר בנפשו בגילוי ממש כ\"א ע\"י התורה דותורה אור והוא בבחי' או\"פ כו', ובפרטיות הרי התפלה היא בבחי' רצוא ע\"כ הגם שנעשה קירוב נפשו לאלקות בתפלה א\"ז בבחי' גילוי בבחי' התיישבות בנפשו כו', והשוב הוא בתו' כו', והגילוי שע\"י התו' אחר התפלה הוא בבחי' תוס' אור בתו' כו' (והיינו דמה שמאיר לו מאור התו' דקודם התפלה שהיא לדעתי' דנפשי' לבד ה\"ז רק הארה לבד ובהתו' שאחר התפלה מאיר אור עצמי כו'), וזה גופא מעורר וממשיך ע\"י התפלה רק שבתפלה א\"ז בבחי' גילוי עדיין והגילוי הוא בתו' כו'. והאופן הב' י\"ל דקירוב נפשו בתפלה הוא בבחי' אלקות השייכות אל העולמות כו', דההתבוננות בד\"כ באיזה מדרי' באלקות שתהי' ההתבוננות ה\"ה בד\"כ באלקות השייך לעולמות דהיינו בבחי' הארה לבד כו', אבל בעצמות אינו שייך התבוננות כו', דגם ההתבוננות ברוממות והפלאת אוא\"ס (הנק' עצמות אוא\"ס כו') הכל הוא רק בהאוא\"ס השייך לעולמות כו', אבל בעצמות אוא\"ס אינו שייך גם ההתבוננות ההפלאה כו' וכמ\"ש במ\"א. והנה בפסוד\"ז או' וירם קרן לעמו, קרן הוא המשכה עצמי' כו' כנודע, זהו רק מה שמחלק בין ההמשכה שבעולמות לההמשכה של נש\"י, דלנש\"י ע\"י התו'"],[3601330534,"נמשך המשכה עצמי' כו', אבל לא בזה הוא עסק ההתבוננות שלו, דהתבוננות הוא במ\"ש קודם כי נשגב שמו לבדו הודו על ארץ ושמים כו' שזהו בחי' הארה לבד, איך שנפרש אם שהפי' דגם בחי' נשגב דהיינו גם בחי' הסובב הוא רק שמו לבד כו', או שהפי' הוא שגם שמו הוא נשגב לבדו כו', ורק הודו הוא על או\"ש כו', ה\"ז רק הארה לבד שבזה הוא עסק ההתבוננות שלו כו'. אבל מ\"ש וירם קרן לעמו זהו רק מה שע\"י תומ\"צ נמשך בחי' העצמות כו', שעי\"ז הוא שנעשה החיות והיוקר בהמצות כו', שהרי גם ע\"י ההתבוננות נעשה חיות ויוקר בקיום המצות וכמ\"ש בסש\"ב והמקיימן באמת הוא האוהב כו', וכאן הוא שהיוקר הוא מצד המשכת העצמות שבתו' וכן במצות כו'. אבל לא בזה הוא עסק ההתבוננות כ\"א בהאור השייך אל העולמות כו', הרי בחי' גילוי האור שמאיר בתפלה הוא רק האור השייך אל העולמות כו', וע\"י התו' נמשך בחי' עצמות א\"ס כו'. וגם הביטול בזה הוא באופן אחר וכמ\"ש בסש\"ב פל\"ה דנשמת האדם אפי' צדיק גמור עובד ה' ביראה ואה' בתענוגים אעפ\"כ אינה בטלה במציאות לגמרי כו'. והנה כשהאדם עוסק\nבתו' אזי נשמתו כו' נכללות באוא\"ס ב\"ה ומיוחדות בו ביחוד גמור כו', וע\"כ ע\"י עסק התו' הוא ממשיך גילוי אוא\"ס בתורה כו', שא\"ז להאיר נפשו כו' (והיינו גם לא בחי' המשכת האור המתעורר ע\"י התפלה או כעין קבלת שכר כו'), כ\"א ע\"י עסק התו' והתקשרותו באור התו' נמשך המשכת אוא\"ס בתו' כו', והיינו דעסק התו' שלו אינה בכדי לרוות צמאונו כמו באופן הא' הנ\"ל שהכוונה בעסק התו' הוא לרוות צמאון הרצוא שבתפלה כו', דהגם שבתפלה הי' בבחי' קירוב כו', הרי א\"ז בבחי' גילוי ממש כנ\"ל, והגילוי הוא ע\"י עסק התו' שאח\"כ כו', הרי דענין עסק התו' בזה הוא לרוות צמאונו כו'. משא\"כ באופן הזה אינו בכדי לרוות צמאונו רק להמשיך גילוי עצמות אוא\"ס למטה כו', וא\"ז האור שמעורר בתפלה (ע\"ה שזהו ג\"כ ע\"י הקדמת התפלה דוקא, רק שהקירוב והדבקות דתפלה אפי' בבחי' אה' בתענוגים כו' אינו בבחי' האור העצמי הזה, לפי שבזה אינו שייך התבוננות והשגת השכל איזה שיהי' כו', כ\"א שע\"י הקדמת העבודה האמיתית דתפלה נותנים זה בדרך מתנה בתו' כו', וכמו שנת\"ל פקע\"ד ועמשית\"ל פ'),\nוכל ענינו בעסק התו' הוא להמשיך המשכת העצמות למטה כו', וכן משמע בר\"מ פ' פנחס דרכ\"ב ע\"ב בענין שדוד הי' מחבר תו' שלמע' בהקב\"ה והיינו שהמשיך תוס' אור בתו', וקאמר שם שז\"ע איזה חסיד המתחסד עם קונו כו', דמבו' בסש\"ב פ\"י שז\"ע לייחדא קוב\"ה ושכינתי' בתחתונים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והו\"ע לימוד התורה לשמה, דמעיקרא אדעתי' דנפשו עביד לקשר נפשו באלקות ע\"י התורה, דהנה הנה\"א מתעלם בהנה\"ב (לא כמו תומ\"צ בגשמיות שהן בלי הסתר פנים), מפני שהכוונה היא שיהי' הבירור בדרך מלמטלמ\"ע, וההתגלות הוא ע\"י התורה, עוז ותושי' וז\"ע לימוד התורה שקודם התפלה, ואחר התפלה הוא לימוד התורה לשמה שממשיך אוא\"ס בתור' ומתקשר ומתייחד בזה, והתחדשות ההתקשרות בתורה על התפלה הוא שבתפלה אינו בבחי' גילוי והתיישבות כ\"א בתורה שאח\"כ, וגם י\"ל שהקירוב שבתפלה הוא בהאלקות השייך להעולמות דבזה שייך התבוננות והשגה, וזהו כי נשגב שמו הודו על או\"ש שזהו התבוננות, וירם קרן הוא המשכת העצמות בתורה (שלמע' מההמשכה</span>"],[3601330535,"<b>שבתפלה)</b>, והוא ביטול ויחוד גמור משא\"כ בתפלה, וזהו ההתקשרות בתורה, ולא לרוות צמאונו כ\"א להמשיך גילוי אוא\"ס למטה, והו\"ע המתחסד עם קונו.\nקעז) <b>וביאור</b> הענין הוא, דהנה בענין ההתקשרות הגם שזהו בדבר שהוא נפרד בפ\"ע, מ\"מ ע\"י ההתקשרות יש בזה יתרון מע' מההתאחדות הקודמת והיינו שע\"י ההתקשרות באים למדרי' גבוה יותר כו', ויובן זה בהתקשרות הנשמה באלקות ובתו' שע\"י ירידתה בבי\"ע שנעשית כדבר בפ\"ע הנה ע\"י ההתקשרות שלה נעשה בה יתרון מעלה כו'. והענין הוא דהנה כתי' שחורה אני ונאוה בנות ירושלים, פי' בנות ירושלים קאי על הנשמה כמו שהיא בשרשה באצי' וכמא' נשמה שנתת בי טהורה היא, דטהורה היינו בעולם האצי' בבחי' פנימי' הכלים כו' כנודע, ומה שנק' בנות ירושלים זהו הנשמות כמו שהן בבחי' עיבור במל' דאצי', וי\"ל משום דכשהנשמה היא בבחי' מל' אז הוא בבחי' מציאות דבר דשייך בה ענין היראה כו'. וכמ\"ש במ\"א בענין אהוי\"ר למעלה דאינו שייך לכאורה בע\"ס דאצי' מאחר שהן אלקות ממש כו', ומ\"מ בבחי' מל' כתי' למען יזמרך כבוד ולא ידום דנהו\"ת קארי תדיר כו', שהוא בחי' רצוא שז\"ע האה' כו', והיינו לפי שהמל' היא בחי' הגילוי שבאצי' שאינו בחי' העצמות דאצי' וע\"כ עיקר הכלים הן\nבחי' מל' כו', ולכן בבחי' מל' שייך ענין הרצוא כו' (וגם בהע\"ס בכלל שייך ענין אהוי\"ר רצו\"ש והו\"ע מטולמ\"ט כו' וכמ\"ש במ\"א). וכמו\"כ הוא בנשמות כמו שהן בבחי' מל' אז שייך בהם ענין היראה שיהיו נקראים בנות ירושלים כו'. גם י\"ל דהכוונה היא על הנשמות דב\"ן וכידוע שיש נשמות דמ\"ה ונשמות דב\"ן, דהנשמות שהן מבחי' מ\"ה היינו שעיקרם הוא מבחי' ז\"א דאצי' והן בבחי' אין בעצם, וכמו שירדו למטה אינן נתפסים בגשם והן בבחי' עובדי ה' בנשמתן כו' (והן הנשמות שנק' בנים למקום, ויש בזה מדרי' גבוהות יותר הנק' אחים ורעים כו', וכמ\"ש בלק\"ת בהבי' דיונתי), ונשמות דב\"ן היינו שהן מבחי' מל' והן בבחי' יש כו', וכמו שהן בעיבור בבחי' מל' הביטול שלהם הוא בבחי' ביטול היש כו', וכמו שירדו למטה עיקר עבודתם הוא בביטול חומר גופם כו' (ואליהו שהי' בעיבור י\"ב חדש הי' למטה ביטול גופו ביותר עד שעלה בסערה כו', רק שנשמת אליהו הי' מבחי' ב\"ן דמ\"ה כו' וכמ\"ש במ\"א), ונשמות אלו הן נתפסים בגשם, וזהו עיקר עבודתם למטה בביטול גופם כו'. וזהו דבנות ירושלים הן\nהנשמות כמו שהן בבחי' מל' דבאלו הנשמות שייך לו' אח\"כ בירידתן בגוף שחורה אני ונאוה כו' (דבנשמות דמ\"ה אינו שייך ענין שחורה אני מאחר שגם בירידתן למטה הן בבחי' אין בעצם כו', רק בנשמות דב\"ן שייך לומר שחורה אני ונאוה כו'). והנה הנשמות כמו שהן למע' ה\"ה בתכלית הביטול ובבחי' אחדות באלקות, וזהו שנק' בנות ירושלים, פי' ירושלים יראה שלם שלמות היראה כו', דבנבראים דבי\"ע לא יש בהם שלמות היראה להיות בהם הביטול בתכלית שז\"ע היראה כו', דגם במלאכים שיש בהם בחי' ביטול הרי כתי' ובמלאכיו ישים תהלה כו', וכמארז\"ל אפקוהו למט\"ט כו', והיינו מפני שאין הביטול שלהם בתכלית וכמ\"ש במ\"א. אך בחי' מל' להיותה אלקות ממש ה\"ה נק' ירושלים שהיא בבחי' שלמות היראה והביטול כו' (דע\"ה שהמל' הוא בחי' יש לא כמו החכמה שהיא בחי' ביטול בעצם, ולכן הי' דוד בר נפלי כו', וכמשנת\"ל פקס\"א, מ\"מ ה\"ה בביטול בתכלית דהיינו בבחי' ביטול הישות לגמרי כו'), וע\"כ הנשמות כמו שכלולים במל' נק' בנות ירושלים שהי' בהם שלימות היראה והביטול כו', ובמדרי' זו הנשמה היא בבחי' טהורה מכל בחי' ישות כו', וכמ\"ש"],[3601330536,"בלק\"ת ד\"ה ושמתי כדכד הב'. אך בירידתה למטה נא' אתה בראתה אתה יצרתה כו' שנעשית בבחי' יש ובבחי' מציאות נפרד ממקורה כו', וכנודע דהנשמות בשרשן הן בבחי' עדאת\"כ שמיוחדים במקורם וכמו דגים שבים כו', ובירידתם למטה ה\"ה בבחי' נבראים דעדאת\"ג שהם נפרדים ממקורם כו'. ועל זמן ירידת הנשמה למטה עז\"נ שחורה אני שאומרת הנשמה שלמטה אל הנשמה כמו שהיא למע' קודם התלבשותה בגוף, הגם דשחורה אני בבחי' שחרות והתעלמות אור כו', ומה גם ע\"י הגוף ונה\"ב שמתעלם אורה ומתרחקת ממקורה עד שצריכה יגיעה עצומה בכדי לבא ליראה, והיגיעה היא בב' ענינים, הא' בההתבוננות לפעול את היראה להיות כי היראה באמת אינה באה רק ע\"י השגת הענין לבד, כמו האה' שבאה רק ע\"י השגת הענין האלקי שמרגיש את העילוי דאלקות כו' (אם שהשגת הענין והרגש העילוי והיוקר באים כאחד או שבא אח\"כ, וכמשנת\"ל פקע\"א, דההפרש בזה הוא אם שההתגברות היא מהרגש הענין האלקי שמשיג על ההשגה עצמה אז הרגש העילוי והיוקר הוא בעת ההתבוננות, ואם ההשגה היא בהתגברות אז בא הרגש העילוי אח\"כ כו',\nועיקר ההפרש בזה הוא אם ההשגה היא בבחי' פנימי' השגה או בבחינת חיצוני' לבד כו', דבהשגה פנימי' התגברות הרגש האלקי יותר ובחיצוני' השגה התגברות ההשגה יותר כו', אמנם גם בחיצוני' השגה יש בזה הפרש בין דקות השגה לגסות השגה, דבדקות ההשגה נרגש הענין האלקי מה שמשיג ובהשגה מגושמת נרגש ההשגה ביותר כו', ובזה שייך זיכוך לבא לידי דקות ההשגה כו', אך בד\"כ בחיצוני' ההשגה התגברות ההשגה יותר כו'. ובכללות יותר ההפרש הוא בטוב האלקות בעצם שזה בא בעת ההשגה וההתבוננות כו', או שההרגש הוא מה שקרבת אלקים לו טוב שזה בא אחר ההשגה וההתבוננות כו', וזה גופא תלוי אם הוא בבחי' פנימי' השגה או בחיצוני' כו', דבפנימי' ההשגה ההרגש הוא בטוב דאלקות בעצם כו'. אמנם גם בענין קרבת אלקים לי טוב יש הפרש הנ\"ל שבאם ההתגברות היא מהרגש הענין האלקי ה\"ז בא בדרך ממילא, וכאשר ההתגברות היא ההשגה ה\"ז בא אח\"כ כו', ואיך שיהי' הוא שע\"י השגת הענין נרגש העילוי והיוקר דאלקות כו'), ועי\"ז מתעורר באהבה ותשוקה לאלקות כו'. אבל ביראה אינו מספיק ההשגה לבד\nכ\"א צ\"ל הרגש הענין יותר וכמו ענין ההכרה, והיינו שיהי' הענין אצלו בבחי' קירוב המהות במקצת עכ\"פ ועי\"ז דוקא יתעורר ביראה כו', והיינו לפי שהיראה ביסודה היא בחי' ביטול המהות (דאה' היא בבחי' יש מי שאוהב כו', וביראה הגם שיש בזה אופן שהוא בבחי' יש מי שירא כו' וכמ\"ש במ\"א, מ\"מ בד\"כ היראה היא ביטול המהות כו'), שבא דוקא ע\"י הקירוב במהות הדבר הנורא בבחי' הכרה קצת עכ\"פ כו' (ומובן דהן באה' והן ביראה כשהן באים מבחי' הראי' ה\"ה גבוהים במעלתם באין ערוך, וכאן אין הכוונה בזה בבחי' ראי' וגם לא בבחי' הכרה באמת, רק שבאה' מספיק הקירוב דהענין האלקי שמתקרב אליו ע\"י השגה לבד, וביראה צ\"ל בההשגה גופא קצת הכרה והרגש דעצם הדבר כו'), וע\"ז צריכים יגיעה יתירה שיהי' לו קצת הכרה כו'. והב' שצ\"ל היגיעה בזיכוך החומרי להיות בו בחי' היראה והביטול כו' (וגם להיות בחי' ההכרה הנ\"ל צריכים לזה ג\"כ זיכוך החומרי' כו') וכמארז\"ל יגעת ביראה שהיראה צריכה יגיעה גדולה ועצומה כו', וגם אחר שבא לבחי' יראה אינה בערך כלל להיראה דמלאכים ג\"כ וכ\"ש לגבי היראה דנשמות כמו שהן למע' כו'."],[3601330537,"<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע דהנה התקשרות הגם שזהו בדבר נבדל יש בזה יתרון, דהנה כתי' שחורה אני ונאוה בנות ירושלים, בני\"ר הן נשמות שהן באצי' בעיבור בבחי' מל', דבמל' שייך ענין הרצוא, ובנשמות דשם הו\"ע היראה, או שהן נשמות דב\"ן שהן בבחי' ביטול הישות, ושם הוא שלימות היראה, משא\"כ בבי\"ע גם במלאכים, ובירידתה למטה צריכה יגיעה וביותר על היראה, והוא היגיעה בההתבוננות, כי לאהבה מספיק ההשגה והרגש העילוי (ויבאר בקצרה משנת\"ל פקע\"א), וליראה צ\"ל עכ\"פ קצת הכרת הענין, מפני שהוא ביטול, וגם היגיעה בזיכוך החומרי להיות בו היראה וההכרה.</span>\nקעח) <b>וזהו</b> שאומרת הנשמה למטה דהגם דשחורה אני ומ\"מ ונאוה שע\"י ירידתה למטה נעשה בה יתרון מע', כי ע\"י שנעשית בבחי' מציאות דבר לעצמה ומתקשרת באלקות הנה ההתקשרות שלה הוא בבחי' צמאון ובבחי' תשוקה נפלאה ביותר כו', וזהו מה שהנשמה למטה נק' בש' כלה שהוא ל' כליון וכמו כלתה נפשי כו', דדוקא למטה האה' והרצוא הוא בבחי' כליון בבחי' רשפי אש התשוקה והצמאון ביותר, דכמו שהיא למע' שאינה נפרדת ממקורה ואדרבה היא מיוחדת תמיד במקורה לא יש בה בחי' הכליון כלל כ\"א דוקא בירידתה למטה כו'. וזהו שבשה\"ש נא' כ\"פ אחותי כלה דבנש\"י יש ב' המדרי' דאחותי וכלה, כי יש מעלה באחותי דאח ואחות הן כדבר א' ואהבתם היא תמידית, אך האה' היא בקרירות ואין בזה התחדשות כו', וכלה ה\"ז כדבר נפרד והאה' אינה תמידית ויכול להיות הפסק ח\"ו, וכמו בזה\"ג שנדונו בשלוחין וגרושין כו', אך יש בזה מע' שהאה' היא ברשפי אש שזהו בהתגלות פנימי' הנפש יותר ומגיע למע' במדרי' גבוה יותר ונמשך עי\"ז אור חדש כו', דבד\"כ בחי' אחותי הוא בחי' יחוד חיצוני דאו\"א וכלה\nהוא בחי' יחוד פנימי דאו\"א כו' וכמ\"ש במ\"א. והנה לכאורה היתרון הזה שבנשמה בירידתה למטה הוא בבחי' אה' אבל ביראה היתרון יותר בהנשמה כמו שהיא למע', והיינו כנ\"ל שהיראה עיקרה הוא בבחי' הכרת המהות כו', ובחי' זו הוא בהנשמה כמו שהיא למע' דמזלייהו חזי כו'. אמנם י\"ל דכאשר ע\"י יגיעה בא לבחי' יראה יש בזה ג\"כ יתרון למטה שהביטול הוא בבחי' הנחת עצמותו, שזה שייך יותר בהנשמה כמו שהיא בבחי' מציאות בפ\"ע כו', וע\"ד המבו' במ\"א בענין אין עוד וכולא קמי' כל\"ח דהביטול שבבחי' אור הוא בבחי' כלא כו', והביטול דאין עוד הוא בבחי' יש דוקא כו', וכמו\"כ י\"ל כאן דהנשמה למע' הגם שהיא בבחי' ביטול, עיקר הביטול הוא בבחי' כל\"ח כו', ובירידתה למטה שנעשית בבחי' מציאות דבר הביטול הוא בבחי' הנחת עצמותו כו'. ונמצא דבהתקשרות הנשמה למטה באלקות יש בה יתרון לגבי כמו שהיא למע', הגם דשם היא בבחי' התאחדות כו', וכמו\"כ בנשמות לגבי התו', דהרי נשמות מושרשים בתו' דז\"ע ישראל עבמ\"ח דהיינו בתו' דאותי' התו' הן אותי' המח' כו' כמ\"ש במ\"א, ובשרשם ה\"ה\nמיוחדים ממש בתו' כו', ומ\"מ יש בהם יתרון בירידתם למטה, דהרי בשרשם כמו שהן מושרשים ומיוחדים בתורה הרי כ\"ז הוא באותי' התו' לבד, וזהו דישראל ר\"ת יש ס\"ר אותיות לתורה דהיינו רק בחי' אותיות כו', ובירידתה למטה ומתקשרת בתו' ה\"ה מתקשרת באור התו' היינו בבחי' החכ' המלובשת באותי' התו', וע\"י הקדמת העבודה בבחי' כלה כנ\"ל שממשיכים אור חדש כו', הרי המשכה זו היא בהתקשרותה אח\"כ בתו' שנמשך גילוי אור חדש"],[3601330538,"שלמע' מהחכ' כו'. וכשם שבנשמה יש יתרון מעלה בבחי' ההתקשרות שלה למטה, כמו\"כ הוא גם בזה דאורייתא מתקשראה בקוב\"ה כו'. דהנה התו' בירידתה למטה ה\"ה בבחי' נובלות לבד מבחי' חשמ\"ע כו', ונת\"ל פקע\"ג דגם בחי' חשמ\"ע הוא בחי' נובלות לגבי בחי' החכ' כמו שהיא למעלה מאצי' דהיינו בחי' חכ' שבכתר כו', ומובן הענין ע\"פ הנ\"ל דתו' כמו שהיא בחכ' דאצי' ה\"ה בבחי' אותי' הכתב שזהו כמו דבר נוסף כו', אבל כמו שהיא בחכ' שבכתר הרי שם הוא בחי' אותי' החקיקה שהן מיני' ובי' שזהו דבר א' כו', וע\"כ התו' גם כמו שהיא למע' היא בבחי' נובלות כו', ועמ\"ש בתו\"א והוספות בהבי' הב' דהשמים כסאי, וע\"י ירידתה למטה נמשך מבחי' עצמות א\"ס גילוי או\"ח ממש כו'. אך היתרון הזה דהתקשרות התו' בא\"ס למטה נעשה ע\"י נש\"י, שע\"י שנש\"י מתקשראין באלקות ובתו' עי\"ז ממשיכים גילוי אור חדש בתו' כו', וז\"ע לעשות את כל דברי התורה שנש\"י עושין את התו' שממשיכים המשכת אוא\"ס בתו' כו', ומובן שהיתרון הנעשה בתו' למטה הוא גם לגבי כמו שהוא למע' מושרשת באוא\"ס ב\"ה כו' וכמשי\"ת. וז\"ע\nחכמות בחוץ תרונה שנמשך מבחי' התענוג שלמע' מהחכ' כו', וזה נעשה ע\"י ישראל שע\"י התקשרותם באלקות ותו' כו', עי\"ז נעשה התקשרות והתאחדות התו' בבחי' עצמות אוא\"ס ב\"ה כו'. נמצא שיש יתרון בההתקשרות למטה הן בהתקשרות הנשמות באלקות ובתו' שזהו בבחי' כליון בעצמות אוא\"ס ב\"ה ובהגילוי אור חדש שבתורה כו' (שזהו האופן הב' שנת\"ל פקע\"ו שהרצוא דתפלה היא במדרי' גבוה יותר דהיינו בבחי' כלה כו', וכ\"ש ההמשכה וההתקשרות שבאוא\"ס שבתו' כו'), והן בהתקשרות התו' באלקות שזהו בעצמות א\"ס כו'. וזהו תלת קשרין מתקשראין דא בדא קוב\"ה ואורייתא וישראל והוא התקשרות הנשמה בתו' ותו' בעצמות א\"ס כו', והסדר בזה דתחלה מתקשראין ישראל באורייתא כו', וע\"י ההתקשרות דנש\"י בתורה בב' האופנים הנ\"ל נעשה ההתקשרות דתורה בקוב\"ה והוא הגילוי אור חדש שנמשך בתורה כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש והי' עקב תשמעון כו', דהנה עקב הוא המדרי' התחתונה שבנשמה שזהו בירידתה למטה, דמה שבא למטה בבחי' התלבשות ה\"ז רק המדרי' שבנשמה כו', אך בזה דוקא הוא בחי' הרצון והכליון דבחי' כלה שנת\"ל, וגם עקב מורה על עקבות משיחא דבזה הזמן ע\"פ רוב הן נשמות ממדרי' תחתונות שבאים בבחי' התלבשות ובבחי' תפיסא בגשם ביותר כו', ובזה הוא עיקר ענין שחורה אני ונאוה בבחי' תוקף הרצוא והכליון ביותר כו', ועי\"ז דוקא נמשך גילוי אור חדש בתו' כו'. וזהו עקב תשמעון את המשפטים כו', דהיינו שההמשכה היא בתו' כו'. ומ\"ש ושמרתם ועשיתם אותם הוא שחשיב כאן ג' מדרי' מחדו\"מ, תשמעון הו\"ע המח' וכמ\"ש אזן מילין תבחן כו', ושמרתם הוא דבור וכמא' אם ערוכה בכל ושמורה כו', ועשיתם הוא מעשה כו' והן מחדו\"מ דתו', דעסק התו' צ\"ל במחדו\"מ דמח' הוא עיון להבין ולהשיג מה שהוא לומד כו', וכמו\"כ צ\"ל לימוד התו' בדבור דוקא וכמ\"ש חיים הם למוצאיהם למוציאיהם בפה כו', וצ\"ל מעשה ללמוד ע\"מ לעשות כו', ועי\"ז נמשך הגילוי אור חדש בתו' כו', וכמ\"ש\nבסש\"ב ח\"א פ\"ד דמחדו\"מ דתו' הגם שהן לבושים לבד גבהה מעלתן לאין קץ וסוף על מע' נר\"ן עצמן כו'. ועז\"א אח\"כ ושמר כו' את הברית כו' דברית זהו\"ע התו' שנק' ספר"],[3601330539,"הברית כו' וכמ\"ש אם לא בריתי כו' והו\"ע ההתאחדות כו', וכמו כר\"ב שכורתין דבר א' לשנים ועוברים בין הגזרים שעי\"ז מתאחדים הנבדלים זמ\"ז כו', והחסד הוא בחי' חסד דקשוט בחי' חסד דעתיק שזהו בחי' עצמות אוא\"ס כו', והשבועה היא כמ\"ש אשר נשבעת לאבותינו מימי קדם מבחי' קדמונו ש\"ע כו', והוא ג\"כ ענין ההתאחדות כו', והיינו שע\"י התו' נעשה התאחדות נש\"י בעצמות א\"ס כו', וזהו ג\"כ ענין ושמר ה' לך כו' ע\"ד דבנשמה או' ואתה משמרה בקרבי אחרי שחושב תחלה טהורה בראתה כו' ד' מדרי' בנשמה, או' אח\"כ ואתה משמרה בקרבי וידוע שזה קאי על עצם הנשמה כו', וכמו\"כ ענין ושמר לך היינו גילוי בחי' עצמות א\"ס כו'. וכ\"ז הוא ע\"י עקב תשמעון שע\"י בחי' עקב שבנשמה וכן בנשמות דבחי' עקבות משיחא כשע\"י עבודה באים לבחי' כלה וע\"י עסק התו' ממשיכים גילוי אור חדש שמבחי' עצמות א\"ס כו'. וזהו והי' עקב תשמעון את המשפטים האלה דהנשמה שבבחי' עקב מתקשרת באלקו' בבחי' כליון כו', ומתקשרת בתו' שז\"ע המשפטים כו' ושמרתם ועשיתם כו' בג' מדרי' דמחדו\"מ כו', עי\"ז ושמר ה'\nאלקיך את הברית כו', שא\"ז על תנאי כ\"א שכ\"ה אופן ההמשכה דכאשר עקב תשמעון כו', אז ושמר ה' אלקיך לך כו' שנמשך גילוי בחי' עצמות אוא\"ס למטה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו הגם דשחורה אני, מ\"מ ונאוה בתוקף הצמאון, והוא בחי' כלה, אחותי אהבה תמידית ובקרירות, כלה היא אהבה פנימית, וביראה הביטול דהנחת עצמותו הוא למטה דוקא, ע\"ד דהביטול דאין עוד הוא דוקא בהיש, וכן בנשמות לגבי תורה למעלה הוא שמושרשים באותיות התורה, ולמטה ההתקשרות באור התורה, ובאו\"ח הנמשך ע\"י הרצוא דבחי' כלה, וכן אורייתא בקוב\"ה למעלה באצי' היא בחי' אותיות הכתב, ולמטה ע\"י נש\"י מתקשרת בעצמות א\"ס. וזהו והי' עקב תשמעון, עקב הנשמה למטה, וע\"י הרצוא דבחי' כלה תשמעון את תוס' אור בתורה.</span>"],[3601330540,"<h3>בס\"ד. ש\"פ שופטים, תער\"ג</h3>\n<b>שופטים</b> ושוטרים תתן לך כו' צדק צדק תרדוף למען תחי' וירשת כו', וצ\"ל מהו\"ע ב\"פ צדק שאו' צדק צדק תרדוף כו', ואח\"כ או' ג\"כ ב' ענינים למען תחי' וירשת כו', ומשמעות הענין הוא שע\"י ב\"פ צדק עי\"ז תחי' וירשת כו', צ\"ל מהו ב' הענינים אלו ושזה ע\"י הב\"פ צדק כו', גם מה שייך זה למ\"ש שופטים ושוטרים תתן לך כו'. ולהבין כ\"ז ילה\"ק משנת\"ל בענין מאה\"ז תלת קשרין כו', דהתקשרות שייך בשני דברים נבדלים דבדבר א' כמו אור ומאור שהאור אינו מהות אחר מהמאור אינו שייך ענין ההתקשרות כ\"א דבקות כו', רק בשני דברים נבדלים כו', והיינו בנש\"י ותו' שהנשמה היא בבחי' מהות בפ\"ע שייך ההתקשרות בתו' כו',"],[3601330541,"וכן בתו' לגבי קוב\"ה להיות דנובלות חשמ\"ע תו' שייך ענין ההתקשרות כו'. ונת' דבההתקשרות יש בזה יתרון מע' לגבי ההתאחדות הקודמת דהנשמות למע' מיוחדים בתו', אך הוא רק באותיות התו' כו', ולמטה ההתקשרות היא בחכ' שבתו' ובהאור חדש הנמשך מבחי' עצמות א\"ס בתו' (ובד\"כ הו\"ע ב' אופני התקשרות דנש\"י בתו' כו'), וכן בתו' שדוקא ע\"י ירידתה למטה ונש\"י מתקשראין בתו' עי\"ז התו' מתקשרת בבחי' עצמות שז\"ע האור חדש שממשיכים בתו' כו'.\nקעט) <b>אמנם</b> צ\"ל כללות הענין שנת\"ל פקע\"ה דהתקשרות הוא בשני דברים הנבדלים זמ\"ז דכמו הא דאורייתא מתקשראה בקוב\"ה זהו כמו דבר הנבדל שמתקשר, והלא אמרו בזהר בכ\"ד דאורייתא וקוב\"ה כו\"ח, דהכוונה בזה שהן בבחי' חד ממש כו'. וכמ\"ש בסש\"ב פכ\"ג ההפרש בין תו' למצות דמצות נק' אברים שזהו כמו אברי הגוף שהן דבר בפ\"ע כו', דע\"ה שהנפש עם הגוף מתייחדים ממש עד שאין לחלק ביניהם כו', מ\"מ הרי הגוף הוא דבר בפ\"ע מהנפש, והיינו שני דברים נבדלים המתייחדים כו', וכמו\"כ המצות שנק' איברין דמלכא ה\"ז כיחוד שני דברים נבדלים כו' (וזהו לפי שהמצות בכלל הן בחי' כלים וכמ\"ש כי נר מצוה כו'), משא\"כ התו' היא חד ממש. ומבו' במ\"א שזהו ההפרש בין בחי' איהו וגרמוהי חד לאיהו וחיוהי חד, דהיחוד במצות הוא בחי' איהו וגרמוהי שזהו כב' דברים המתייחדים שא\"ז בבחי' יחוד עצמי כו', והיחוד בתו' הוא בחי' איהו וחיוהי יחוד האור במקורו שאינו בבחי' מהות אחר והיחוד בזה הוא בבחי' יחוד עצמי כו', וכמשנת\"ל פרק הנ\"ל דבאור ומאור ההתאחדות שלהם הוא בבחי' דבקות\nלא רק בבחי' התקשרות כו', וכמו\"כ בתו' היחוד הוא בבחי' יחוד עצמי' דז\"ע אורייתא וקוב\"ה כו\"ח ממש כו', ואיך שייך ענין ההתקשרות בתורה שזהו התקשרו' בדבר הנבדל כו'. ולכאו' י\"ל שזהו ההפרש בין חיצוני' התו' לפנימי' התו', דהנה חיצוני' התו' היא בחי' אותי' התו' לבד, דהרי מה שנגלה לנו בתו' הן רק האותי' לבד הן בתושב\"כ הרי נתגלה רק האותי' משא\"כ הנקודות והתגין וכ\"ש הטעמים לא נתגלו עכשיו כו' (ויתגלו לעתיד שז\"ע טעמי תו' והוא בחי' העונג והשעשועים שבתו' כו'), ומה שנתגלה עכשיו הן רק אותי' התו' כו', וזהו מה שניתן לנו במ\"ת הן האותי' דתו' כו'. הגם שבמ\"ת ניתן הכל היינו גם בחי' התגין נקודות כו' והרי יש גם עכשיו גילוים ממדרי' אלו כו', וגם לעתיד שיהי' גילוי טעמי תו' הרי לא יהי' עוד הפעם מ\"ת כו', כי הכל ניתן כבר במ\"ת כו', מ\"מ מה שניתן בהתגלות ולכאו\"א ה\"ה האותי' כו'. דמה שהתו' היא שייכה לכאו\"א מישראל ה\"ז האותי' דתו' כו', ולכן כאו\"א מברך נותן התו' גם הע\"ה שאין להם שום ידיעה גם בהחכ' דתו' המלובשת בהאותי' וכ\"ש בהמדרי'\nהעליונות דתו' כו', ומ\"מ מברכים נותן התו' על האותי' דתורה שזהו מה שניתן לכאו\"א מישראל לכולם בשוה כו'. הרי דתושב\"כ עיקרה הוא האותי' כו', וכן מה שבא מתושב\"כ בתושבע\"פ הרי הכל רק מהאותי' התו' כו' וכמשנת\"ל פקע\"ג, וגם שכל עניני התורה הכל הוא בהלכות המדברים בעניני' הגשמי', וכמו המחליף פרה בחמור ושנים אוחזין בטלית, וכמו דיני אונאה וכה\"ג, שהכל מדבר בענינים גשמי' שהן דברים נבדלים ונפרדים בעצם, וממילא גם בחי' החכ' דתו' שמתלבש בזה ה\"ז מתלבש בדבר הנפרד שהוא ג\"כ בבחי' נבדל כו', רק שאינו כמו המצות שבאין בבחי' התלבשו' ממש בדבר הגשמי כמו בציצית הגשמי"],[3601330542,"או בקלף הגשמי כו', שהרי הדבר הגשמי נעשה כלי ממש להרצה\"ע כו', וכמ\"ש בסש\"ב פכ\"ג שהחיות של מעהמ\"צ כו' ונעשה לו ממש כגוף לנשמה כו', ועמ\"ש באגה\"ק בקו\"א ד\"ה להבין מ\"ש בפע\"ח כמו עד\"מ האתרוג ומיניו הלביש בהן הקב\"ה ממהותן כו' (ולפמשנ\"ת שם לעיל נר' שזהו בחי' הלבנונית שבא בבחי' התלבשו' בחיצוני' הכלים כו', ומהות בחי' החיצוני' דחסדים פנימי' דז\"א (י\"ל שזהו בחי' הלבנונית כמו שבא בבחי' ז\"א כו') מתלבש במעהמ\"צ כמו בהאתרוג כו'), הרי נעשה בבחי' כלי ממש כו', ולכן יש בה קדושה במה שהוקצה למצותה כו'. ובמ\"א מבו' דבמצות יש ב' ענינים, הא' מה שהמצוה היא בס' השתל' דע\"ס דאצי' כו', והב' באוא\"ס שלמע' מאצי' כו', וכמו בתפילין שהד' בתים הן ד' מוחין דז\"א היינו מה שע\"י התפילין נמשכים מוחין לז\"א כו', והב' הוא הרצה\"ע שהוא ההמשכה מבחי' כתר כו' (שזה שוה בכל המצות כו'). וזהו משארז\"ל הקב\"ה מניח תפילין שיש בזה ב' פי', הא' דהקב\"ה הוא בחי' ז\"א ומניח תפילין היינו המשכת המוחין לז\"א מחו\"ב כו', אבל בבחי' הכתר אינו שייך ענין התפילין\nכו', והפי' הב' דקוב\"ה הוא בחי' הכתר ומניח תפילין היינו המשכת תוס' אורות בבחי' המוחין כו'. וזהו דבמא' פתח אליהו במ\"ש כתר עליון כו' ואיהו קרקפתא דתפילין כו' יש נוסחא ואיהו קרקפתא דלא מנח תפילין כו', והיינו לפי פי' הא' הנ\"ל דתפילין הן המשכת המוחין מחו\"ב אבל בחי' הכתר למע' מזה כו', ומבו' במ\"א דבהכנת המצות כמו בכתיבת הד' פרשיות והנחתן בבתים ועשייתן כתקונן נמשך בהם הד' מוחין מחו\"ב כו', וע\"י עשיית המצוה בהנחת תפילין על הזרוע ועל הראש נמשך בהם הרצה\"ע מבחי' הכתר בבחי' תוס' אורות בהמוחין כו'. ואיך שיהי' הרי בהמצות נעשים הדברים הגשמי' כלים לאלקו' כו', והתו' אינה באה בבחי' התלבשו' בהעניני' הגשמי' שעוסק בהם בלימוד ההלכה כו', שאין הדברים הגשמי' נעשים בזה כלים לאלקו' ואין בהם שום קדושה משו\"ז כו' (וכמו בענין הבירורים ההפרש בין הבירור דתפלה שהוא בדרך התלבשות בהמתברר, משא\"כ הבירור דתו' כמו ר\"י כולהו תנויי בנזיקין כו' אינו בבחי' התלבשו' כו', ועד\"ז הוא ג\"כ ההפרש בין תורה למצות בענין ההתלבשו' כו', רק בענין\nהבירורים הנה הבירורי' שע\"י המצות אינו כמו בתפלה, דבמצות ג\"כ הבירור דהאור עליון בדרך מלמעלמ\"ט וכמ\"ש במ\"א, להיות שזהו אור עליון שלמע' מבחי' התלבשו' ממש כו', שהרי האור המתלבש במעהמ\"צ הוא בלי הסתר פנים כו' כמ\"ש בסש\"ב, והיינו שהוא אור עליון יותר ובא בלי שום הסתר פנים, ע\"כ הבירור בזה הוא בדרך מלמעלמ\"ט לפי שאינו כענין ההתלבשו' שבס' השתל' כו', ומ\"מ אינו כמו התו' שאינה באה בבחי' התלבשו' כלל כו'), אבל א\"ז רק בדרך מקיף כ\"א בדרך התעסקות שמתעסק בהענינים הגשמי' כו', ומאחר שהוא עכ\"פ בבחי' התעסקות בדברים הנפרדים ה\"ז ג\"כ בבחי' נבדל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וצ\"ל והלא אורייתא וקוב\"ה כולא חד, דמצות הן כלים ואיברין שהיחוד בבחי' איהו וגרמוהי, ותורה אור יחוד איהו וחיוהי, ואיך הוא בבחי' התקשרות. וי\"ל דהתקשרות זהו בחיצוניות התורה אותיות התו' שזהו שנתגלה במ\"ת ובא בתושבע\"פ, ונתלבשה בענינים גשמיים נבדלים, רק לא כמו המצות שהגשמי הוא בבחי' כלי ממש, ולכן יש בהם קדושה, ובהכנת המצוה נמשך מס' השתל', ובעשייתן נמשך בהם רצה\"ע, וזהו הקב\"ה ז\"א מניח תפילין גילוי המוחין,</span>"],[3601330543,"<b>וגם</b> קוב\"ה כתר מניח תפילין תוס' אור במוחין, ותורה אינה בבחי' התלבשות ממש (וכמו בהבירור ההפרש בין תורה ותפלה, ומצות ג\"כ מלמעלמ\"ט), מ\"מ ה\"ז התעסקות בענינים נבדלים דגם החכ' שבזה הוא בבחי' נבדל.\nקפ) <b>והנה</b> ידוע דהלכות התו' כמו שבאו למטה זהו ע\"י התלבשו' גמורה דח\"ע באור הנשמה דמל' דברי' ויצי' כמ\"ש באגה\"ק בקו\"א ד\"ה להבין מ\"ש בפע\"ח, ואור הנשמה דבי\"ע ה\"ז מבחי' הכלים דאצי' שהן כמו דבר שבפ\"ע כו', וע\"כ גם התו' כמו שהיא למע' בבי\"ע ה\"ז ג\"כ בכלל בחי' חיצוני' התו' כו', שהרי כל הלכות התו' ישנם ברוחני' שזהו לימוד הנשמות בג\"ע שלומדים תורה הרי א\"ז הלכות הגשמי' כ\"א שלומדים שם אותן ההלכות ברוחני', וכמו קא מיפלגי במתיבתא דרקיע אם בהרת קדמה כו' דכ\"ז הוא ברוחני', מ\"מ ג\"ז הוא שמדבר בעולמו' ונבראים כו'. וכמו הנגעים באדם הגשמי למטה הוא שהדם נעכר שם ונתהפך לליחה והוא מורה הסתלקו' הדם והחיות מהמקום ההוא, ולכן נק' בתרגום סגירותא שנסגר הכלי לבלי יכנס האור והחיות כו', וכמו\"כ בברי' ויצי' הו\"ע אשר יוסגר כלי השגת הנברא מלקבל אור המהווה והמחי' אותו כו', וע\"ה דברי' ויצי' הוא בתכלית הרוחני' וכאן בעשי' הו\"ע סגירת דם גשמי, מ\"מ שניהם הוא בענין נבראים ובע\"ג כו', וכמו\"כ ההלכה דמחליף פרה בחמור שבג\"ע הוא\nהלימוד ברוחני' ההלכה. והוא להיות שכל דבר יש לו שרש ומקור למע', ובד\"כ הוא שרשם ומקורם בעש\"מ שהן הע\"ס דמל' אותי' דבור העליון כו', ובזה יש כמה אופנים שונים אם נמשכים מגוף ועצם האותי' או מחילופי האותי' ותמורותיהן ויש חילופים וחילופי דחילופים ותמורות דתמורות כו' וכמ\"ש בסש\"ב ח\"ב ומבו' במ\"א, דלפי אופן שרשו ומקורו לפי אופן זה הוא מדרי' הנברא כו'. והנה פרה וחמור שניהם שרשם מפני שור שבמרכבה רק שפרה הוא בהמה טהורה שיכולה להתברר ולעלות למע', וחמור הוא בהמה טמאה שא\"א להעלותו כו', אך הנה יש דרך אחרת שע\"י מתעלה גם בחי' חמור כמה שבאפשר שיתעלה, והוא ע\"ד יששכר חמור גרם והוא ע\"י ויט שכמו לסבול שסובל עול התו' שמייגעת ונוטלת כח האדם עי\"ז בירור גם בחי' חמור כו'. ובעבודה ענין החמור הוא כמארז\"ל חמרא אפי' בתקופת תמוז קרירא לי', והיינו גם בתוקף זריחת אור השמש קרירא לי', והיינו גם כשמתבונן בענין אני ה' לא שניתי שלא יש שום שינוי בין קודם הברי' לאחר הבריאה, מפני שכ\"ז הוא רק הארה לבד כו', וכמ\"ש שמש ומגן ה\"א שזהו רק\nהארת ש' הוי' הנמשך ע\"י אלקי' אבל בהוי' עצמו לא יש שום שינוי כלל כו', וממילא הרי גם לגבי ש' הוי' הכל בטל ממש שאינו בבחי' מציאו' כלל שז\"ע הוי' אחד שהכל הוא בבחי' אחדות גמורה כו', דמהתבוננות זאת הי' צ\"ל כלות הנפש להכלל בבחי' ש' הוי' עצמו כו', או להיות בבחי' ביטול במציאו' כו', והיינו דמההתבוננות איך שהכל הוא הארה לבד שאינו תופס מקום כלל לגבי הוי' עצמו ואינו עושה שום שינוי ח\"ו, צ\"ל כלוה\"נ בבחי' תוקף הרצוא להכלל בעצמו' אוא\"ס וכמו מי לי בשמים ועמך לא חפצתי כו', ומהיוצא מזה מאחר שכ\"ז הוא רק הארה לבד הרי כולא קמי' כל\"ח ממש בלי שום מציאו' כלל, הרי מובן מזה ענין האחדות איך שהוי' אחד כו' (והוא דבהדעה העליונה והיינו בש' הוי' עצמו הרי אין שום מציאו' כלל שכולא קמי' כלא כו', שע\"י ההתבוננות והעמקת הדעת בזה שנרגש בו הענין צ\"ל"],[3601330544,"בחי' הביטול במציאו' כמו שהוא בהדעה העליונה כו', ובאמת בההתבוננות איך שהוא הארה לבד הרי גם לפי דעה התחתונה אינו תופס מקום כלל כו', והביטול דהעדר תפיסת מקום (כשמרגיש העדר תפיסת מקום שלו) הרי מתבטל במציאותו כו', וכמו הקטן לגבי הגדול הרי מתבטל לגמרי (ער פארלירט זעך) כו', ובמ\"א מבו' דהביטול דהעדר תפיסת מקום הוא הביטול בההתפשטו' לבד וכמו שרגא בטיהרא כו'). ואתם בני יעקב לא כליתם שאינם באים לידי כלוה\"נ ואדרבה הוא בבחי' קרירות שאינו מתפעל כלל, והסבה לזה הוא להיותם בני יעקב עקוב הלב מכל והו\"ע טמטום הלב שנעשה כאבן שאינו מתפעל משום דבר כו', והעצה לזה הוא ויט שכמו לסבול לקבל עליו עול תו' כו', שהתו' היא עוז ותושי' כו', וכמ\"ש בתו\"א ד\"ה בחדש השלישי, וכמו מים הנוטפים על האבן שנעשה בו חלל כמו\"כ התו' מתשת כח הנה\"ב ונותנת עוז לנה\"א כו'. גם י\"ל חמרא קרירא לי' בתוקף זריחת השמש הוא כענין בני מחוזא דחזיין יקרא דאורייתא כו', והיינו גם שרואה הפלאה דאלקו' וכמו בהתבוננו' דשאו מרום עיניכם כו' איך שיש כח א\"ס בנבראי'\nכו', שזה מושג ומוכרח מאד מהנבראי' עצמן שיש בהם כח א\"ס כו', והוא מהקיום שלהם דנבראים העליונים קיימין באיש, ונבראי' התחתוני' קיימים במין כו', דע\"ה הווים ונפסדים וההפסדות שלהם הוא הכרחי מפני שכל מציאותם הוא מהרכבה כו' וכמ\"ש במ\"א, ומ\"מ המה קיימין באיש ובמין הרי בהכרח שיש בהם כח א\"ס המקיים ומתמיד מציאותם כו', וכמו\"כ בהתנועה שלהם מה שמתנענעים תמיד בלי הפסק מוכרח שזה מכח הא\"ס שבהם כו' וכמ\"ש במ\"א ועמשית\"ל, וזהו שאו מרום עיניכם וראו כו', שזהו בבחי' ראי' ממש כמו ראי' חושי' ממש שרואין כח א\"ס שבנבראים כו'. וכאשר בהשגתו הוא רואה ממש שיש כח א\"ס בנבראים ובפועל אינו נראה כלל הכח הא\"ס כ\"א הנברא הגשמי ונמשך אחרי הישות כו', הרי מזה צ\"ל האהבה והרצון בתוקף מאד שיהי' נראה הא\"ס בגילוי כו', והו\"ע חולת אה' בבחי' תוקף האה' והתשוקה ביותר כו' וכמ\"ש במ\"א, ומ\"מ אינו מתפעל. וע\"י עסק התו' בפועל בשקידה וביגיעה גדולה ה\"ה מתקן ומברר גם קלי' חמור כו', אך בבירור זה הרי צ\"ל בו יתרון דיתרון האור הוא מן החושך, ולהיות שהחמור\nהוא קלי' קשה דבד\"כ ענין הקרירות הוא קשה מאד וכידוע בענין קליפת עמלק אשר קרך כו', הרי בהבירור צ\"ל בזה יתרון גדול כו'. וזהו המחליף פרה בחמור פי' פרה הוא הנה\"ב ומחליפה במשא ועול החמור, צ\"ל יתרון אור מחליפין אלו כו', ובזה הוא הלימוד בג\"ע, וכן בכל ההלכות ברוחני' הענינים כו', ומ\"מ הרי כ\"ז הוא מדבר בעניני הנבראים כו', ומאחר שמדבר בעניני הנבראים ה\"ז בחי' חיצוני' התו' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובאגה\"ק בקו\"א דמהות ח\"ע המתלבשת באור הנשמה דמל' דברי' מתלבשת בהלכות דתורה, וה\"ז כלים דמל' דאצי', ולכן גם התורה בברי' היא בחי' חיצוניות, ושם הוא ברוחניות, וכמו הנגעים סגירותא היינו שנסגר כלי השגת הנבראים, המחליף פרה בחמור דשניהם מפני שור, אך חמור בה\"ט והו\"ע הקרירות, דהנה אני ה' לא שניתי מפני שהכל רק הארה, ומזה צ\"ל כליון אל העצמות, וגם מההרגש דהעדר תפיסת מקום צ\"ל הביטול במציאות, וגם מובן בזה איך דכולא קמי' כל\"ח, ואתם בנ\"י לא כליתם, וצ\"ל כשור לעול בתורה שהיא עוז ותושי', גם קלי' חמור שאינו מתפעל מהתבוננות כח הא\"ס שבעולם שזהו בבחי' ראי'</span>"],[3601330545,"<b>ממש</b>, והוא קלי' עמלק, והתיקון הוא ע\"י שקידה בתורה, וצ\"ל בזה יתרון אור, וכ\"ז מדבר בעניני הנבראים.\nקפא) <b>והנה</b> התו' כמו שהיא באצי' ה\"ה בעניני' דאלקו', וכמו ענין הנגעים הוא דש' אהי\"ה בריבוע בגימט' דם, ונודע דשם אהי\"ה הוא בבינה והוא בחי' אלקי' חיים בחי' בינה הממשכת האור והחיות (שזהו הדם) לאברי' דז\"א, ובינה מקבלת מאור אבא שהוא בחי' מים העושה התפשטו' הדם כו', וכמא' אכל ולא שתה אכילתו דם היינו שאינו מתפשט בהאברי' כו', וז\"ע אדם א' דם שע\"י הא' הוא התפשטו' הדם כו', והבהרת הוא מניעת התפשטו' הדם בחי' ש' אהי' מחמת שאין אור אבא יכול להתפשט בז\"א כו', ואזי יכול להיות בחי' נגעים שזהו דבחי' ק\"נ דאצי' יונק מבחי' עור אדה\"ע בחי' ז\"א דאצי', ואזי והובא אל הכהן וצריך הסגר שבעת ימים שהן הז' יומין עילאין דאצי' כו', וכהן יראנה שהוא בחי' יסוד אבא כו', שכ\"ז הוא במדרי' אלקו' כו'. וכן בענין האונאה מאריך בזה בע\"ח ובד\"כ הוא כשהצירוף דש' הוי' נמשך ביותר מס' ההמשכה אז נתאנה המוכר שהוא המשפיע, ואם להיפך נתאנה המקבל כו', דהחכ' בזה הוא בענין המשכת ש' הוי' שהוא בחי' א\"ס כו'. וי\"ל שג\"ז הוא בכלל בחי' חיצוני'\nהתו' להיות שכ\"ז הוא שמדבר במדרי' דהשתל' ע\"ה שזהו במדרי' דאצי' שהוא אלקו' ממש, מ\"מ מאחר שזהו במדרי' דהשתל' ה\"ז בחי' חיצוני' לבד כו', וכ\"ז הוא מבחי' חיצוני' החכ' דאצי' שנק' נובלות חשמ\"ע כו' כנ\"ל, וע\"כ ה\"ז בא בהשגה בכל עולם שהוא, דכשם שהנגלה דתו' למטה ה\"ז בא בהשגה וכמו הלכות הגשמי' הנ\"ל דהמחליף פרה בחמור ואונאה וכה\"ג ה\"ה אצלנו בהשגה ממש, כמו\"כ הוא רוחני' התו' בעולמו' עליוני' וכמו השגת הנשמו' בג\"ע בעסק התו' שלהם שזהו בבחי' השגה ממש כו', וכ\"ה בתו' דאצי' שמדברת בעניני' דאלקו' ה\"ז בבחי' השגה ממש באצי' כו', והיינו לפי שכ\"ז הוא מבחי' חיצוני' החכ' שבאה בהשגה דבינה כו'. ועיקר בחי' פנימי' התו' י\"ל שזהו בחי' העונג שבתו', דעונג בעצם הוא למע' מהשגה דגם העונג שבהשגה דהענין המושג ה\"ה בבחי' השגה ובבחי' תפיסא והתיישבות כו', הרי תענוג הנפש שבהענין ה\"ה למע' מהשגה ואינו בבחי' התיישבו' ואדרבה מביא לידי כליון, וכמו נכספה וגם כלתה נפשי שזהו היפך ההתיישבות כו' (וא\"ז רק בתענוג דאו\"ח דשם הוא בבחי' כליון ממש כו',\nאלא גם בתענוג דאו\"י התענוג גורם כליון הנפש בהדבר שמתענג בו כו', וגם מה שהתענוג משיב את הנפש וכמו נחת רוח שהוא בבחי' השבה והנחה כו' ג\"ז הוא למע' מהתיישבות בכלים כו', וכמו שבת שהוא בחי' מנוחה ועונג וכמ\"ש וירא אלקים כו' והנה טוב מאד שזהו המנוחה והעונג שאחר היגיעה כו' (אם כי לא בעמל ויגיעה כו'), ויש בחי' עונג ומנוחה שלמע' מזה והוא בחי' שבתא דיומא הנק' שבתו של שבת כו' וכמ\"ש במ\"א. הרי באמת הגילוים דשבת הן למע' מהשתל', וכנודע דמוחין דאבא למע' מהשתל' והוא מה שהחכ' נק' עדן כו'). וי\"ל דהעונג שבתו' זהו עיקר שכר הנשמו' בג\"ע והיינו לא רק ההשגה כ\"א בחי' התענוג שמתענגי' בלימוד התו' וכמא' נהנין מזיו השכינה תענוג הנשמה כו', דהעונג זהו עיקר הקבלת שכר כו', וכמ\"ש בסי' בפי' ברוך משלם שכר טוב דזיו הוא בחי' זיווא עילאה דעתיקא, וז\"ע שכר טוב דהגילוי בג\"ע לנשמו' הוא מבחי' עתיק דברי' כו', ועמ\"ש בסש\"ב ח\"ב ספ\"ה, ורקיע זה נק' רזא"],[3601330546,"דאורייתא כו', מרקיע זה נוטף טל למזון הנשמו' כו', וידוע דטל הוא מבחי' עתיק כו', והיינו דעיקר מזון הנשמו' בג\"ע הוא בחי' העונג כו'. ועפ\"ז י\"ל דחיצוני' התו' הוא בבחי' התקשרו' להיות שזהו כמו דבר הנבדל כו', ומש\"א אורייתא וקוב\"ה כו\"ח ממש זהו בבחי' פנימי' התו' שהוא בחי' העונג שלמע' מהחכ' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובאצי' התורה מדברת בעניני אלקות, וכמו נגעים הוא סילוק אור אבא, ואונאה באופני ההמשכה דש' הוי', ומ\"מ להיות שכ\"ז בס' השתל' י\"ל שזהו חיצוניות התורה, נובלות חשמ\"ע, ולכן בכל עולם היא בהשגה, והפנימיות הוא העונג שבתורה שלמעלה מהשגה גם העונג שבהשגה, והוא בבחי' כליון גם העונג דאו\"י, וגם מה שמשיב את הנפש ה\"ז למעלה מכלים, וכמו מנוחה דשבת, וי\"ל דעיקר שכר הנשמות בג\"ע הוא העונג שבתורה, ובזה א' דכולא חד.</span>\nקפב) <b>אך</b> כ\"ז אינו מתיישב עדיין דהרי במא' דתלת קשרין או' וכולהו דרגין על דרגין סתים וגליא, הרי שגם סתום דתו' הוא בבחי' התקשרו', ולפי הנ\"ל הרי פנימי' התו' היא בבחי' חד ממש כו'. אך הענין הוא דגם בבחי' פנימי' התו' יש בחי' נגלה ונסתר, וכמ\"ש בזהר בהעלותך הנ\"ל פקע\"ג שיש בתו' בחי' נשמתא ונשמתא לנשמתא כו'. והענין דהנה גם בחיצוני' התו' היינו בחי' הנגלית בהכרח שיש בזה בחי' סתום שלמע' מהשגה וכמו\"כ גם בפנימי' התו' יש בחי' גליא כו', דהנה יש בגמ' כמה שרשים ויסודות שעליהם נבנו בניני התו' כו', וכמו אוקי ממוני בחזקת מרא, והמוציא מחבירו עליו הראי', ועל שרש הזה בנוים כל הסברות והטעמים על כל דין לומר שראובן נק' מרא קמא או ששמעון נק' מוציא מחבירו וכה\"ג, וזה מושג היטב בשכלנו הטעם ששמעון נק' מוציא מחבירו וכה\"ג, אך אם באנו לחקור ולפלפל על עצם הכלל מדוע אוקי ממונא בחזקת מרא שהרי חברו טוען נגדו ואפי' כשחברו אומר ברי והוא אומר שמא מ\"מ אוקי ממונא כו', זה לא נוכל להשיג בשכלנו היטב כו', וכן בענין רשויות\nלשבת אחר שנגלה לנו השרשים שרה\"י הוא כך ורה\"ר הוא כך אז נחקור ונפלפל אם זהו רה\"י או רה\"ר וביציאה והכנסה מזל\"ז וכה\"ג, אבל המקור והשרש מדוע רה\"י הוא כך ורה\"ר כך דוקא זה אינו מושג לנו, הרי שגם בנגלה דתו' עצם הדבר הוא סתום ונעלם מהשגה כו'. והענין דהנה באד\"ר אי' ע\"פ קווצותיו תלתלים שחורות כעורב שהן שערות דז\"א בחי' שערות שחורות דאחידין בי' דכיין ומסאבן, ומכאן אתאחדן טעמי אורייתא בדכיא ובמסאבא כו', הרי דטעמי תו' במ\"ע ומל\"ת הן משערות דז\"א, ובת\"ז אי' ודלת ראשך כארגמן הם טעמי תו' והן בחי' שערות דנוק', ובאמת לא סתרי אהדדי, דהנה מוחין דז\"א שרשם משערות דא\"א, דאו\"א מקבלים המוחין ממזל ונוצר ונקה ומשפיעים אותם לז\"א כו' (וי\"ל שזהו בחי' גדלות המוחין, שממשיכים ע\"י עבודה שזהו בד\"כ המשכה מלמע' מס' השתל' וכמ\"ש במ\"א בהבי' דצדקת פזרונו), וגם קוצי דשערי דא\"א עצמו מכה בעורף ז\"א ועי\"ז מחלק הדעת דז\"א לב' מוחין דחו\"ג (עמ\"ש מזה בהבי' דזכור את אשר עשה לך עמלק בתו\"א פ' תצוה, ושם דעי\"ז נעשה פב\"פ היינו שמאירים פנימי'\nהמוחין להיות האה' בדרך ממילא לא רק בדרך חיוב והכרח כו' וכמ\"ש במ\"א, ולעיל פקל\"ד נת' דכ\"ז הוא מבחי' המוחין השייכים למדות לא עצמי' המוחין ממש כו', ובד\"כ הוא בחי' מוחין דיניקה כו'), ועצמי' בחי' ומדרי' זו"]]});
